def _install_spellcaster_theme_to_disk():
    """Install spellcaster-theme.css into GIMP's user theme directory.

    GIMP 3.x loads themes from themes/<ThemeName>/gimp.css when
    ``(theme "Spellcaster")`` is set in gimprc.

    Writes to all detected GIMP config versions (3.0, 3.2, etc.).
    """
    try:
        css_src = _PLUGIN_DIR / "spellcaster-theme.css"
        if not css_src.exists():
            return

        if sys.platform == "win32":
            appdata = os.environ.get("APPDATA", "")
            if not appdata:
                return
            gimp_base = Path(appdata) / "GIMP"
        elif sys.platform == "darwin":
            gimp_base = Path.home() / "Library" / "Application Support" / "GIMP"
        else:
            gimp_base = Path.home() / ".config" / "GIMP"

        if not gimp_base.is_dir():
            return

        import shutil
        installed = False
        for version_dir in gimp_base.iterdir():
            if version_dir.is_dir() and version_dir.name[0].isdigit():
                theme_dir = version_dir / "themes" / "Spellcaster"
                theme_dir.mkdir(parents=True, exist_ok=True)
                dest = theme_dir / "gimp.css"
                if not dest.exists() or css_src.stat().st_mtime > dest.stat().st_mtime:
                    shutil.copy2(css_src, dest)
                    installed = True
        if installed:
            print(f"[Spellcaster] Theme installed to themes/Spellcaster/gimp.css")
    except Exception as e:
        print(f"Note: Could not install persistent theme: {e}")


def _apply_spellcaster_theme():
    """Inject the Spellcaster premium dark CSS into GIMP's GTK3 environment.

    Only applies if the user opted in via config.json {"apply_theme": true}.
    Default is UNBRANDED — we never reskin GIMP without explicit consent.

    1. Load the full theme from spellcaster-theme.css (bundled next to this file).
    2. Apply it to the current GTK screen at APPLICATION priority.
    3. Also install the CSS to GIMP's user theme directory for persistence.
    """
    # Read config directly — _load_config() isn't defined yet at boot time.
    try:
        _cfg = json.loads((_PLUGIN_DIR / "config.json").read_text(encoding="utf-8"))
    except Exception:
        _cfg = {}
    if not _cfg.get("apply_theme", False):
        return
    try:
        from gi.repository import Gdk, Gtk

        # --- Load from the bundled CSS file ---
        css_file = _PLUGIN_DIR / "spellcaster-theme.css"
        if css_file.exists():
            css = css_file.read_bytes()
        else:
            # Minimal fallback if the CSS file is missing
            css = b'''
            window, dialog { background-color: #150B07; color: #EBE2DF; }
            label { color: #EBE2DF; }
            button { background-image: none; background-color: #301A14; color: #EBE2DF;
                     border: 1px solid #633A32; border-radius: 6px; }
            button:hover { background-color: #E32234; color: white; }
            '''

        provider = Gtk.CssProvider()
        provider.load_from_data(css)
        Gtk.StyleContext.add_provider_for_screen(
            Gdk.Screen.get_default(),
            provider,
            Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION
        )
    except Exception as e:
        print(f"Warning: Failed to load premium UI theme: {e}")

    # Also install to GIMP's theme directory for persistence
    _install_spellcaster_theme_to_disk()


def _make_branded_header():
    """Create a branded Spellcaster header with live server status indicator.

    Shows a green/red dot next to the title so the user instantly knows
    whether their ComfyUI server is reachable.
    """
    try:
        from gi.repository import Gtk
        hbox = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
        ctx = hbox.get_style_context()
        ctx.add_class("spellcaster-header-box")

        title = Gtk.Label()
        title.set_markup('<span size="14000" weight="bold" color="#E32234">Spellcaster</span>')
        title.set_xalign(0)
        hbox.pack_start(title, False, False, 0)

        # Live server + enhance status indicator
        status_label = Gtk.Label()
        status_label.set_xalign(0)
        status_label.set_valign(Gtk.Align.END)
        try:
            _api_get(COMFYUI_DEFAULT_URL, "/system_stats")
            enhance_tag = ' <span color="#B246F2">✦ AI Enhance</span>' if _PROMPT_ENHANCE else ''
            status_label.set_markup(
                f'<span size="9000" color="#00E676">● Connected</span>'
                f'<span size="9000">{enhance_tag}</span>')
        except Exception:
            status_label.set_markup(
                f'<span size="9000" color="#FF5252">● Server offline</span>')
        hbox.pack_start(status_label, False, False, 0)

        return hbox
    except Exception:
        return None


def _style_dialog_buttons(dialog):
    """Apply premium styling to a dialog's OK/Cancel action buttons.

    Marks the OK button as suggested-action and the Cancel button as
    destructive-action so the CSS theme can make them prominent and branded.
    """
    try:
        for btn in dialog.get_action_area().get_children():
            resp = dialog.get_response_for_widget(btn)
            ctx = btn.get_style_context()
            if resp == Gtk.ResponseType.OK:
                ctx.add_class("suggested-action")
                ctx.add_class("spellcaster-primary")
            elif resp == Gtk.ResponseType.CANCEL:
                ctx.add_class("destructive-action")
    except Exception:
        pass


# Apply premium theme only if the user opted in (check is inside the function).
_apply_spellcaster_theme()

def _auto_update():
    """Check GitHub for a newer commit and download ALL plugin files dynamically.

    Uses the GitHub Tree API to discover every file under the plugin directory,
    so new files, renamed files, and removed files are handled automatically.

    Flow:
      1. GET /commits → latest SHA (quick, 1 API call)
      2. Compare with local .spellcaster_version (supports both 7-char and 40-char)
      3. If different: GET /git/trees/main?recursive=1
      4. Filter for files under plugins/gimp/comfyui-connector/
      5. Download each via raw.githubusercontent.com
      6. If direct replace fails (Windows file locking), stage as .update
      7. Remove local files that no longer exist in the repo
      8. Delete GIMP pluginrc cache (forces menu re-scan on next restart)
      9. Write new SHA to .spellcaster_version

    Shared primitives live in spellcaster_core.auto_updater. This function
    keeps the GIMP-specific logic: canonical-source priority for sc_core
    files, .py-always-staged policy, pluginrc purge, theme reapply.
    """
    import sys as _sys
    _hdrs = _github_headers()

    # Import shared auto-updater primitives from spellcaster_core (bundled
    # next to this plugin). Fall back to legacy inline path if import fails
    # (shouldn't happen in normal installs, but defensive).
    try:
        from spellcaster_core import auto_updater as _au
    except ImportError:
        _au = None

    # Cross-process lock — if another GIMP instance (or a crashed one
    # whose lock is fresh) is already updating, back off. Prevents two
    # concurrent updaters racing on the same files.
    _lock_file = _PLUGIN_DIR / ".spellcaster_update.lock"
    _lock_held = False
    if _au is not None:
        _lock_held = _au.acquire_lock(_lock_file, stale_after=600.0)
        if not _lock_held:
            print("[Spellcaster] Auto-update skipped: another update in flight.",
                  file=_sys.stderr)
            return

    try:
        # Step 1: Check latest commit SHA
        local_sha = _VERSION_FILE.read_text().strip() if _VERSION_FILE.exists() else ""
        if _au is not None:
            try:
                latest_sha = _au.fetch_latest_sha(_GITHUB_API, _hdrs, timeout=15)
            except Exception:
                return
            if _au.shas_match(latest_sha, local_sha):
                return
            try:
                tree = {"tree": _au.fetch_tree(_GITHUB_TREE, _hdrs, timeout=30)}
            except Exception:
                return
        else:
            # Legacy fallback (kept so shim-only installs still self-heal)
            req = urllib.request.Request(_GITHUB_API, headers=_hdrs)
            with urllib.request.urlopen(req, timeout=15) as r:
                latest_sha = json.loads(r.read())[0]["sha"]
            if latest_sha == local_sha or latest_sha[:7] == local_sha[:7]:
                return
            req_tree = urllib.request.Request(_GITHUB_TREE, headers=_hdrs)
            with urllib.request.urlopen(req_tree, timeout=30) as r:
                tree = json.loads(r.read())

        # Step 3: Filter for files in our plugin directory (including subdirectories)
        # Also grab spellcaster_core/ — the shims need it at runtime.
        # list of (repo_path, local_remainder, expected_size, expected_sha)
        remote_files = []
        # Track which local remainders we've already seen so the canonical
        # source (comfyui-spellcaster/) always wins over the bundled copy
        # (plugins/gimp/.../spellcaster_core/). Without this, the stale
        # bundled copy in the repo overwrites the canonical one because
        # the tree API returns files alphabetically and plugins/ > comfyui-.
        _seen_remainders = set()
        _rejected_paths = 0
        for item in tree.get("tree", []):
            if item["type"] != "blob":
                continue
            # CANONICAL SOURCE FIRST: spellcaster_core from comfyui-spellcaster/
            # This is the single source of truth — always takes priority.
            raw_remainder: str = ""
            if item["path"].startswith(_CORE_LIB_PREFIX):
                raw_remainder = item["path"][len("comfyui-spellcaster/"):]
            elif item["path"].startswith(_GIMP_PLUGIN_PREFIX):
                raw_remainder = item["path"][len(_GIMP_PLUGIN_PREFIX):]
            if not raw_remainder:
                continue
            # Path-traversal defense — reject `../`, drive markers, NTFS
            # reserved names, backslashes, control chars, etc. A hostile
            # mirror or MITM can't smuggle a write outside _PLUGIN_DIR.
            remainder = _au.safe_remainder(raw_remainder) if _au else raw_remainder
            if remainder is None:
                _rejected_paths += 1
                continue
            # Skip plugins/gimp spellcaster_core/ files if the canonical
            # source already provided the same remainder. Single SoT.
            if remainder in _seen_remainders:
                continue
            remote_files.append((
                item["path"],
                remainder,
                item.get("size", 0),
                item.get("sha", ""),
            ))
            _seen_remainders.add(remainder)

        if _rejected_paths:
            print(f"[Spellcaster] Auto-update rejected {_rejected_paths} "
                  "unsafe tree entries.", file=_sys.stderr)

        if not remote_files:
            return  # Something went wrong with API, don't touch local files

        # Step 4: Download all remote files (supports subdirectories)
        # .py files are ALWAYS staged as .update (never live-replaced) because
        # Python has already loaded them into memory. Live-replacing can cause
        # crashes if a lazy import or __pycache__ reload picks up the new code
        # mid-session with incompatible function signatures.
        updated = 0
        staged = 0
        failed = 0
        remote_filenames = set()
        # Track non-py assets that failed so the end-of-run summary
        # can call them out by name — the user's support complaint
        # was about silently-skipped theme / icon updates, and the
        # fix is to name names in stderr so they can eyeball which
        # file actually broke.
        _failed_assets: list[tuple[str, str]] = []
        _plugin_root = _PLUGIN_DIR.resolve()
        for rel_path, remainder, expected_size, expected_sha in remote_files:
            remote_filenames.add(remainder)
            # NEVER overwrite the crash-safe boot shim. It is immutable.
            if remainder == "comfyui-connector.py":
                continue
            try:
                url = f"{_RAW_BASE}/{rel_path}"
                dest = _PLUGIN_DIR / remainder
                # Belt-and-suspenders: after joining the (validated)
                # remainder, resolve the path and confirm it still lives
                # under the plugin root. If safe_remainder accepted it,
                # this always passes — but defense-in-depth is free.
                dest_resolved = dest.resolve() if dest.exists() else dest.parent.resolve() / dest.name
                try:
                    dest_resolved.relative_to(_plugin_root)
                except ValueError:
                    print(f"[Spellcaster] BUG: path {remainder} resolved "
                          f"outside plugin root — skipping.", file=_sys.stderr)
                    failed += 1
                    continue
                dest.parent.mkdir(parents=True, exist_ok=True)
                tmp = dest.with_suffix(dest.suffix + ".tmp")
                if _au is not None:
                    # Use the retry wrapper when available — asset
                    # files (CSS / PNG / GIF) fail more often than
                    # plain .py downloads because they hit large
                    # blob endpoints. Transient network hiccups get
                    # smoothed over 3 attempts with exp backoff;
                    # deterministic failures (SHA / size mismatch)
                    # still fail fast and land in the `failed`
                    # counter.
                    _dl = getattr(_au, "download_blob_with_retry",
                                  _au.download_blob)
                    blob = _dl(
                        url, expected_size, _hdrs,
                        timeout=60,
                        filename_hint=remainder,
                        expected_sha=expected_sha,
                    )
                else:
                    req_dl = urllib.request.Request(url, headers=_hdrs)
                    with urllib.request.urlopen(req_dl, timeout=60) as r2:
                        blob = r2.read(50 * 1024 * 1024 + 1)
                    if len(blob) > 50 * 1024 * 1024:
                        raise IOError("blob exceeds 50 MB cap")
                    if expected_size > 0 and len(blob) != expected_size:
                        raise IOError(
                            f"Incomplete download: got {len(blob)} bytes, "
                            f"expected {expected_size}")
                    if remainder.endswith((".py", ".js", ".jsx", ".css",
                                           ".json", ".md", ".txt", ".html")):
                        blob = blob.replace(b"\x00", b"")
                tmp.write_bytes(blob)
                # Always stage .py files — never replace running Python modules
                if remainder.endswith(".py"):
                    stage_path = dest.with_suffix(dest.suffix + ".update")
                    tmp.replace(stage_path)
                    staged += 1
                else:
                    try:
                        tmp.replace(dest)
                        updated += 1
                    except PermissionError:
                        stage_path = dest.with_suffix(dest.suffix + ".update")
                        tmp.replace(stage_path)
                        staged += 1
            except Exception as e:
                failed += 1
                # Track failed non-py assets separately so the final
                # summary can call them out by name.
                if not remainder.endswith(".py"):
                    _failed_assets.append((remainder, str(e)[:120]))
                print(f"[Spellcaster] Failed to download {remainder}: {e}", file=_sys.stderr)
                # Clean up any partial tmp file so the next run starts fresh.
                try:
                    tmp_cleanup = dest.with_suffix(dest.suffix + ".tmp")
                    if tmp_cleanup.exists():
                        tmp_cleanup.unlink()
                except Exception:
                    pass

        # Step 5: Remove local files that no longer exist in the repo
        protected = {
            "comfyui-connector.py",  # crash-safe boot shim — NEVER touch
            "_spellcaster_main.py.bak",  # rollback backup
            "config.json", ".spellcaster_version",
            "user_presets.json", "session_state.json",
        }
        protected_suffixes = (".pyc", ".update", ".tmp", ".onnx", ".safetensors")
        for local_file in _PLUGIN_DIR.rglob("*"):
            if not local_file.is_file():
                continue
            rel = local_file.relative_to(_PLUGIN_DIR).as_posix()
            if rel in protected or local_file.name in protected \
               or local_file.suffix in protected_suffixes:
                continue
            if rel not in remote_filenames:
                try:
                    local_file.unlink()
                except Exception:
                    pass

        # Step 5b: Validate config.json integrity (fix truncation)
        _cfg_path = _PLUGIN_DIR / "config.json"
        if _cfg_path.exists():
            try:
                _cfg_raw = _cfg_path.read_text(encoding="utf-8").strip()
                json.loads(_cfg_raw)  # validate
            except (json.JSONDecodeError, ValueError):
                # Config is corrupt - try to salvage by closing braces
                try:
                    _cfg_raw = _cfg_raw.rstrip().rstrip(",")
                    if not _cfg_raw.endswith("}"):
                        _cfg_raw += "\n}"
                    json.loads(_cfg_raw)  # re-validate
                    _cfg_path.write_text(_cfg_raw, encoding="utf-8")
                    print("[Spellcaster] Repaired truncated config.json", file=_sys.stderr)
                except Exception:
                    pass  # unfixable - _load_config() returns {} safely

        # Step 6: Re-apply appearance assets if user opted in
        cfg = _load_config()
        if cfg.get("apply_theme", False):
            # Re-install gimp.css to all GIMP config dirs (opt-in only)
            _install_spellcaster_theme_to_disk()

            # Update the banner GIF in the parent plugins/gimp/ directory
            banner_gif = _PLUGIN_DIR / "gimp_banner.gif"
            if not banner_gif.exists():
                banner_gif = _PLUGIN_DIR.parent / "gimp_banner.gif"
            parent_banner = _PLUGIN_DIR.parent / "gimp_banner.gif"
            if banner_gif.exists() and banner_gif != parent_banner:
                import shutil
                try:
                    shutil.copy2(banner_gif, parent_banner)
                except Exception:
                    pass

            # Re-apply system splash if the banner PNG exists
            banner_png = _PLUGIN_DIR.parent / "gimp_banner.png"
            if not banner_png.exists():
                banner_png = _PLUGIN_DIR / "gimp_banner.png"
            if banner_png.exists():
                # Find and replace GIMP system splash
                import shutil
                splash_candidates = []
                if _sys.platform == "win32":
                    for pf in [Path("C:/Program Files/GIMP 3"), Path("C:/Program Files (x86)/GIMP 3")]:
                        share = pf / "share" / "gimp" / "3.0" / "images"
                        if share.is_dir():
                            for f in share.glob("gimp-splash*.png"):
                                splash_candidates.append(f)
                for splash in splash_candidates:
                    if splash.exists():
                        try:
                            backup = splash.with_suffix(".orig" + splash.suffix)
                            if not backup.exists():
                                shutil.copy2(splash, backup)
                            shutil.copy2(banner_png, splash)
                        except (PermissionError, OSError):
                            pass
                        break

            # Re-apply custom icon
            icon_src = _PLUGIN_DIR / "spellcaster_icon.png"
            if icon_src.exists():
                if _sys.platform == "win32":
                    for pf in [Path("C:/Program Files/GIMP 3"), Path("C:/Program Files (x86)/GIMP 3")]:
                        for icon_name in ["gimp-logo.png", "wilber.png"]:
                            icon_path = pf / "share" / "gimp" / "3.0" / "images" / icon_name
                            if icon_path.exists():
                                try:
                                    import shutil
                                    backup = icon_path.with_suffix(".orig" + icon_path.suffix)
                                    if not backup.exists():
                                        shutil.copy2(icon_path, backup)
                                    shutil.copy2(icon_src, icon_path)
                                except (PermissionError, OSError):
                                    pass

        # Step 7b: Delete GIMP pluginrc cache — forces re-scan of procedures
        # Scans ALL GIMP versions (3.0, 3.2, etc.) not just 3.0
        _delete_all_gimp_pluginrc()

        # Step 7c: Purge __pycache__ to prevent stale bytecode
        for pycache in _PLUGIN_DIR.rglob("__pycache__"):
            try:
                import shutil as _shutil
                _shutil.rmtree(pycache)
            except Exception:
                pass

        # Step 8: Record version — but ONLY if every file downloaded
        # cleanly. Writing the new SHA after a partial update would make
        # the next run skip the retry (shas_match short-circuits), so
        # failed files would stay stale indefinitely.
        if failed == 0 and (updated > 0 or staged > 0):
            _VERSION_FILE.write_text(latest_sha)
        if updated > 0 or staged > 0 or failed > 0:
            sha7 = latest_sha[:7]
            msg = f"Spellcaster updated to {sha7} ({updated} files"
            if staged > 0:
                msg += f", {staged} staged for next restart"
            msg += ")."
            if failed > 0:
                msg += (f"\n{failed} file(s) failed integrity check or "
                        "download — next launch will retry them.")
                # Name the failed asset files explicitly. Without
                # this, "3 files failed" doesn't tell the user their
                # themes / icons specifically are affected.
                if _failed_assets:
                    names = ", ".join(n for n, _err in _failed_assets[:6])
                    if len(_failed_assets) > 6:
                        names += f", +{len(_failed_assets) - 6} more"
                    msg += f"\nAssets that failed: {names}"
            if staged > 0:
                msg += "\nRestart GIMP to apply all updates (some files were in use)."
            elif updated > 0:
                msg += "\nRestart GIMP to use the new version."
            if updated > 0 or staged > 0:
                msg += "\nPlugin cache cleared — new menus will appear on restart."
            def _show_update_msg_once(m=msg):
                try:
                    print(f"[Spellcaster] {m}", file=_sys.stderr)
                except Exception:
                    pass
                return False
            # Use idle_add (thread-safe) instead of timeout_add to avoid
            # corrupting any open GTK dialog's widget tree.
            GLib.idle_add(_show_update_msg_once)
    except Exception as e:
        import traceback
        print(f"[Spellcaster] Auto-update check failed: {e}", file=_sys.stderr)
        traceback.print_exc(file=_sys.stderr)
    finally:
        # Always release the lock — even on exception paths — so the
        # next launch doesn't wait for the stale_after fallback.
        if _lock_held and _au is not None:
            _au.release_lock(_lock_file)

# Fire-and-forget: runs once per GIMP session, daemon=True so it
# won't prevent GIMP from exiting. Guard uses sys.modules to survive
# module reload (globals() is reset on reload, sys.modules persists).
_AUTO_UPDATE_KEY = "_spellcaster_auto_update_started"
if not getattr(sys.modules.get(__name__), _AUTO_UPDATE_KEY, False):
    setattr(sys.modules[__name__], _AUTO_UPDATE_KEY, True)
    threading.Thread(target=_auto_update, daemon=True).start()

# ═══════════════════════════════════════════════════════════════════════════
#  Configuration loading — server URL and user-saved presets
# ═══════════════════════════════════════════════════════════════════════════

_config_lock = threading.Lock()

def _load_config():
    """Load config.json from the plugin directory. Returns {} on any error.
    Thread-safe: serialized with _save_config via _config_lock."""
    cfg_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "config.json")
    with _config_lock:
        try:
            with open(cfg_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return {}


# Feature → sentinel node class names. When ANY sentinel is present in
# ComfyUI's /object_info the feature is considered installed. Kept compact:
# we don't list every node, just the distinctive ones per feature.
#
# This map is the authoritative mapping for menu-registration purposes.
# Features not listed here are treated as always-present (fail-open).
_FEATURE_SENTINELS: dict[str, tuple[str, ...]] = {
    "klein_flux2":       ("Flux2KleinRefLatentController", "Flux2KleinTextRefBalance"),
    "flux_kontext":      ("FluxKontextImageScale", "FluxKontextModelLoader"),
    "face_swap_reactor": ("ReActorFaceSwap",),
    "face_swap_mtb":     ("Face Swap (mtb)", "MTB_FaceSwap"),
    "faceid_img2img":    ("IPAdapterFaceID", "IPAdapterUnifiedLoaderFaceID"),
    "pulid_flux":        ("PulidFluxModelLoader", "ApplyPulidFlux"),
    "upscale":           ("UltimateSDUpscale", "UpscaleModelLoader"),
    "face_restore":      ("FaceRestoreCFWithModel", "ReActorRestoreFace"),
    "photo_restore":     ("FaceRestoreCFWithModel",),   # reuses face_restore
    "supir":             ("SUPIR_sample", "SUPIR_first_stage"),
    "seedv2r":           ("SeedVR2VideoUpscaler", "SeedVR2Upscaler"),
    "colorize":          ("DDColor_Colorize",),
    "lama_remove":       ("LaMaInpaint", "LaMaInpaintingModelLoader"),
    "wan_i2v":           ("WanImageToVideo", "LoadWanVideoModel"),
    "detail_hallucinate": ("UltimateSDUpscale",),
    "rembg":             ("BiRefNetRMBG", "RMBG"),
    "lut_grading":       ("ApplyLUT",),
    "style_transfer":    ("IPAdapterAdvanced", "IPAdapterUnifiedLoader"),
    "iclight":           ("LoadICLightModel", "ICLightApplyMaskGrey"),
    # R117: LTX sentinels — previously the ltx-t2v / ltx-i2v procedures
    # had their feature key set to None (always-register) which bypassed
    # this gate. Any of these LTX nodes being present confirms the LTX
    # runtime is installed; use the distilled sampler as the primary
    # sentinel (present in every LTX install from 2.0 onward).
    "ltx_video":         ("LTXVImgToVideo", "LTXVScheduler",
                           "LTXAVTextEncoderLoader"),
}


def _probe_comfyui_nodes(server_url: str, timeout: float = 3.0) -> set[str]:
    """One-shot GET /object_info → set of class_type names. Empty on failure."""
    try:
        import urllib.request as _ur
        req = _ur.Request(f"{server_url.rstrip('/')}/object_info")
        with _ur.urlopen(req, timeout=timeout) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        return set(data.keys()) if isinstance(data, dict) else set()
    except Exception:
        return set()


def _require_comfyui_node(server_url, class_names, feature_name,
                            install_hint=None):
    """Preflight that a ComfyUI install has the custom-pack node(s) a
    feature needs before dispatching a workflow that would otherwise
    fail at the class-type resolver (silent in the queue log — user
    just sees "nothing happened").

    Args:
        server_url: ComfyUI base URL, usually from the active dialog.
        class_names: str | iterable[str] — require any ONE of these
                     names to be present. Pass the canonical class
                     (e.g. "LamaRemover") plus a couple of known
                     aliases (e.g. "AILab_LamaRemover") and the gate
                     passes if ANY match.
        feature_name: human-readable feature label for the message
                     (e.g. "LaMa Remove", "IPAdapter FaceID").
        install_hint: optional extra line with install URL / ComfyUI
                     Manager hint. Defaults to a generic "install the
                     relevant custom pack via ComfyUI Manager".

    Returns True when the requirement is met (or the probe failed —
    fail-open so a flaky connection doesn't block a user who has the
    node installed). Returns False and shows a Gimp.message when the
    probe succeeded AND none of the class_names are registered.

    Pair this with the existing ``_probe_comfyui_nodes`` cache;
    callers who need to test multiple features in one dialog should
    read the probe set once and check membership directly.
    """
    if isinstance(class_names, str):
        class_names = (class_names,)
    nodes = _probe_comfyui_nodes(server_url)
    if not nodes:
        return True  # probe failed — fail open; submit-time error is best we can do
    if any(c in nodes for c in class_names):
        return True
    try:
        names_str = " / ".join(class_names)
        hint = install_hint or (
            "Install the missing custom pack via ComfyUI Manager → "
            "Install Custom Nodes, then restart ComfyUI.")
        Gimp.message(
            f"{feature_name} needs a ComfyUI node that isn't "
            f"registered on your server.\n\n"
            f"Required class_type (any of): {names_str}\n\n"
            f"{hint}")
    except Exception:
        pass
    return False


def _get_features_present_cached(cfg: dict):
    """Return the set of features currently installed on the ComfyUI server,
    or None if the probe can't run (fail-open: caller shows everything).

    Caches the probe per server_url in config.json under "features_probe":
      {"server_url": "...", "features_present": ["klein_flux2", ...], "ts": <epoch>}
    so we only hit /object_info once per GIMP launch. The cache is invalidated
    when the server URL changes or the TTL expires (default 1 hour).
    """
    import time as _time
    TTL_SECONDS = 3600
    server_url = cfg.get("server_url") or COMFYUI_DEFAULT_URL
    probe = cfg.get("features_probe") or {}
    # Use cached value if fresh and still pointing at the same server
    if (probe.get("server_url") == server_url
            and probe.get("features_present") is not None
            and (_time.time() - probe.get("ts", 0)) < TTL_SECONDS):
        return set(probe["features_present"])
    # Miss — probe now. Fail-open on error: return None so caller falls back
    # to showing every non-disabled procedure.
    nodes = _probe_comfyui_nodes(server_url)
    if not nodes:
        return None
    present = {
        feat for feat, sentinels in _FEATURE_SENTINELS.items()
        if any(s in nodes for s in sentinels)
    }
    # Write cache back (best-effort; don't crash registration if config is RO)
    try:
        cfg_copy = dict(cfg)
        cfg_copy["features_probe"] = {
            "server_url": server_url,
            "features_present": sorted(present),
            "ts": int(_time.time()),
        }
        _save_config(cfg_copy)
    except Exception:
        pass
    return present

# Default ComfyUI server URL — overridable via config.json {"server_url": "..."}
# Updated at runtime whenever the user successfully runs a workflow with a different URL.
COMFYUI_DEFAULT_URL = _load_config().get("server_url", "http://127.0.0.1:8188")

# Workflow timeout: 0 = disabled (wait forever), >0 = seconds.
# Default: disabled. Users generating massive tiled videos on slow GPUs
# should never be interrupted by an arbitrary timeout.
WORKFLOW_TIMEOUT = _load_config().get("workflow_timeout", 0)

# ── AI Prompt Enhancement ─────────────────────────────────────────────
# When enabled, every user prompt is automatically rewritten by a local
# LLM (KoboldCpp, Ollama, or any OpenAI-compatible server) before being
# sent to ComfyUI. The rewrite is architecture-aware: SDXL gets tag-style
# prompts, Flux gets natural language, Klein gets concise descriptions.
# Toggle via config.json {"prompt_enhance": true, "llm_url": "http://..."}
# or via the Settings dialog.
_PROMPT_ENHANCE = _load_config().get("prompt_enhance", False)
_LLM_URL = _load_config().get("llm_url", "http://127.0.0.1:5001")

# ── Cross-interface backbone client ───────────────────────────────────
# Announces GIMP's presence to the Wizard Guild and lets _run_* methods
# publish events like `gimp.generation.finished` so the Guild and other
# interfaces can react. When the client is healthy, GIMP appears as an
# active interface in the Guild UI (Settings panel + "Send to GIMP" chip).
#
# Known limitation: GIMP 3 plug-ins run as short-lived per-invocation
# processes, so a long-lived SSE subscription to receive events from the
# Guild (e.g., "Open in GIMP" clicks) isn't reliable here. The heartbeat
# + emit half — the GIMP→Guild direction — works cleanly. Guild→GIMP
# receive is handled by a separate optional background helper (future).
_CROSS_IFACE_CLIENT = None


def _get_cross_interface_client():
    """Lazily start the cross-interface client on first use.

    Memoized. Only retained if the Guild actually answers — we never
    leave a zombie heartbeat thread pinging a dead port.
    """
    global _CROSS_IFACE_CLIENT
    if _CROSS_IFACE_CLIENT is not None:
        return _CROSS_IFACE_CLIENT
    try:
        from spellcaster_core.cross_interface import CrossInterfaceClient
        cfg = _load_config()
        guild_url = cfg.get("guild_url") or "http://127.0.0.1:7777"
        client = CrossInterfaceClient(
            interface_key="gimp",
            guild_url=guild_url,
            auto_heartbeat=True,
        )
        if client.is_reachable():
            _CROSS_IFACE_CLIENT = client
            print(f"[Spellcaster] Cross-interface client online (guild={guild_url})")
        else:
            client.stop_auto_heartbeat()
    except Exception as e:
        print(f"[Spellcaster] Cross-interface client disabled: {e}")
    return _CROSS_IFACE_CLIENT


# ── ComfyUI-side presence (phase-9) ─────────────────────────────────
#
# Zero-config cross-app discovery: each plugin registers itself with
# the ComfyUI-Spellcaster custom-nodes pack's /spellcaster/presence/*
# routes. When another plugin (Darktable, SillyTavern) installs later
# against the SAME ComfyUI, everyone sees everyone — no Wizard Guild
# required. The Guild's /api/interfaces still gets heartbeats (via
# CrossInterfaceClient); this supplements it with a ComfyUI-hosted
# fallback so the Guild isn't a hard dep for discovery.
#
# Fire-and-forget: failures (old ComfyUI-Spellcaster pack without the
# routes; ComfyUI down; mis-configured URL) are swallowed. Presence is
# best-effort; absence of presence just means the "Send to X" menu in
# sibling plugins won't list GIMP until GIMP next heartbeats.

def _safe_hostname():
    """Short, LAN-safe hostname. Falls back to 'gimp-host' if the
    platform returns something weird — the broker only uses it for
    display + instance_id disambiguation."""
    try:
        import socket
        h = socket.gethostname() or ""
    except Exception:
        h = ""
    h = h.strip().split(".")[0][:64]
    # Sanitize to match the broker's _safe_host charset.
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
                  "0123456789-_")
    h = "".join(c for c in h if c in allowed)
    return h or "gimp-host"


_GIMP_HOST = _safe_hostname()
_GIMP_PRESENCE_META = {
    "key": "gimp",
    "label": "GIMP",
    "icon": "🖼️",
    "version": "2.0.0",
    "capabilities": ["send_image", "receive_image", "pixel_edit"],
    "host": _GIMP_HOST,
    "instance_id": f"gimp@{_GIMP_HOST}",
}
_GIMP_PRESENCE_THREAD = None
_GIMP_PRESENCE_STOP = None


def _presence_post(comfy_url, path, body, timeout=3.0):
    try:
        import urllib.request, json as _json
        req = urllib.request.Request(
            f"{comfy_url.rstrip('/')}{path}",
            data=_json.dumps(body).encode("utf-8"),
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=timeout):
            pass
    except Exception:
        pass


def _presence_get(comfy_url, path, timeout=3.0):
    try:
        import urllib.request, json as _json
        req = urllib.request.Request(f"{comfy_url.rstrip('/')}{path}")
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return _json.loads(resp.read().decode("utf-8"))
    except Exception:
        return None


def _start_comfy_presence_heartbeat():
    """Start a daemon that registers with ComfyUI-Spellcaster's
    presence broker and heartbeats every 20 s. Idempotent."""
    global _GIMP_PRESENCE_THREAD, _GIMP_PRESENCE_STOP
    if _GIMP_PRESENCE_THREAD and _GIMP_PRESENCE_THREAD.is_alive():
        return
    cfg = _load_config()
    comfy_url = cfg.get("server_url") or "http://127.0.0.1:8188"
    _GIMP_PRESENCE_STOP = threading.Event()

    def _loop():
        # Explicit register first so label/icon/capabilities land cleanly.
        _presence_post(comfy_url, "/spellcaster/presence/register",
                        _GIMP_PRESENCE_META)
        # Heartbeat immediately, then every 20 s until told to stop.
        hb_body = {
            "key": _GIMP_PRESENCE_META["key"],
            "instance_id": _GIMP_PRESENCE_META["instance_id"],
            "host": _GIMP_PRESENCE_META["host"],
        }
        while not _GIMP_PRESENCE_STOP.is_set():
            _presence_post(comfy_url, "/spellcaster/presence/heartbeat",
                            hb_body)
            if _GIMP_PRESENCE_STOP.wait(20.0):
                break

    _GIMP_PRESENCE_THREAD = threading.Thread(
        target=_loop, daemon=True, name="spellcaster-gimp-presence")
    _GIMP_PRESENCE_THREAD.start()


def _peer_online(target_key):
    """Three-valued check: True if presence confirms peer is alive,
    False if we queried and it wasn't listed, None if we couldn't
    reach any presence surface (ComfyUI + Guild both unreachable).

    Callers that gate UI/actions should treat None as "allow the
    action" — when we can't tell, don't pre-emptively block.
    """
    cfg = _load_config()
    comfy_url = cfg.get("server_url") or "http://127.0.0.1:8188"
    guild_url = cfg.get("guild_url") or "http://127.0.0.1:7777"
    queried = False
    # Primary: ComfyUI presence broker. Match on key (logical) so that
    # GIMP@alice-pc OR GIMP@bob-pc both satisfy a "gimp online" check.
    data = _presence_get(comfy_url, "/spellcaster/presence/list")
    if isinstance(data, dict) and "peers" in data:
        queried = True
        for p in data.get("peers", []):
            if p.get("key") == target_key:
                return True
    # Secondary: Wizard Guild registry.
    data = _presence_get(guild_url, "/api/interfaces")
    if isinstance(data, dict) and "interfaces" in data:
        queried = True
        info = (data.get("interfaces") or {}).get(target_key)
        if info and info.get("online") is not False:
            return True
    return False if queried else None


def _list_peers():
    """Union of ComfyUI-Spellcaster's /spellcaster/presence/list and
    the Guild's /api/interfaces. Used by the Send-to-X menu to gate
    which siblings are alive. Returns a list of dicts with at least
    {key, label, icon, capabilities, age_s}."""
    cfg = _load_config()
    comfy_url = cfg.get("server_url") or "http://127.0.0.1:8188"
    guild_url = cfg.get("guild_url") or "http://127.0.0.1:7777"
    seen = {}

    # Primary: ComfyUI-Spellcaster pack. Dedup by instance_id so the
    # same plugin on two different hosts both appear in the list (the
    # broker returns them as separate entries). Filter out only OUR
    # own instance_id, not every "gimp" entry — another GIMP on the
    # LAN is a real peer.
    my_inst = _GIMP_PRESENCE_META["instance_id"]
    data = _presence_get(comfy_url, "/spellcaster/presence/list")
    if isinstance(data, dict):
        for p in data.get("peers", []):
            inst = p.get("instance_id") or p.get("key")
            if inst and inst != my_inst:
                seen[inst] = p

    # Secondary: Wizard Guild (richer data; wins where both exist).
    # Guild keys are per-kind not per-instance, so collisions fall back
    # to kind-level dedup there.
    data = _presence_get(guild_url, "/api/interfaces")
    if isinstance(data, dict):
        import time as _time
        now = _time.time()
        for key, info in (data.get("interfaces") or {}).items():
            if key == _GIMP_PRESENCE_META["key"]:
                continue
            if not info or info.get("online") is False:
                continue
            last_hb = info.get("last_heartbeat") or 0
            seen[key] = {
                "key": key,
                "instance_id": key,
                "label": info.get("ui_label") or key,
                "icon": info.get("icon") or "",
                "capabilities": info.get("capabilities") or [],
                "host": info.get("host") or "",
                "age_s": max(0, round(now - last_hb, 2)),
                "source": "guild",
            }
    return list(seen.values())


def _publish_event(kind, **data):
    """Publish an event to the Guild's cross-interface bus.

    Fire-and-forget — callers should not depend on success. Typical use:

        _publish_event("gimp.generation.finished",
                       prompt=prompt, model=model, arch=arch,
                       image_path=out_path)

    If the Guild is unreachable or the client isn't available, this
    silently no-ops.
    """
    try:
        client = _get_cross_interface_client()
        if client is None:
            return
        client.publish(kind, data=dict(data))
    except Exception:
        pass


# Kick off the ComfyUI-side presence heartbeat at module load — guarded
# by sys.modules so the thread is single-instance across GIMP reloads
# (mirrors the _auto_update guard convention).
_PRESENCE_KEY = "_spellcaster_presence_started"
if not getattr(sys.modules.get(__name__), _PRESENCE_KEY, False):
    setattr(sys.modules[__name__], _PRESENCE_KEY, True)
    try:
        _start_comfy_presence_heartbeat()
    except Exception as _e:  # pragma: no cover — defensive
        print(f"[Spellcaster] Presence heartbeat failed to start: {_e}")


# ═══════════════════════════════════════════════════════════════════════
#  Cross-interface INBOX — worker + per-menu-invocation auto-drain
# ═══════════════════════════════════════════════════════════════════════
#
# Every Spellcaster menu click triggers a silent inbox drain BEFORE the
# user's intended action runs. GIMP 3 plugins are one-shot processes
# (no persistent main loop for a background timer), so instead of a
# long-lived poller, we gate on an on-disk timestamp and drain at most
# once per `_INBOX_POLL_INTERVAL_S` seconds across the whole user
# session. Errors are swallowed — the inbox drain must never block or
# fail a user's primary action.
#
# Manual "Check Spellcaster Inbox" still exists and shares the same
# worker — it bypasses the interval gate so "force drain now" works.
#
# The on-disk gate file sits next to GIMP's pluginrc under the user's
# plug-ins dir. We deliberately avoid the main plugin config.json so a
# stale timestamp never blocks legitimate config reads.

_INBOX_GATE_FILE = None          # lazy-populated on first call
_INBOX_POLL_INTERVAL_S = 30.0    # don't hit the mailbox more than twice/min
_INBOX_AUTO_HTTP_TIMEOUT = 3.0   # short cap — silent path, not blocking
_INBOX_AUTO_ASSET_TIMEOUT = 8.0  # per-asset download budget on auto path
_INBOX_AUTO_MAX_SIZE = 25 * 1024 * 1024   # 25 MB on auto path


def _inbox_gate_path():
    global _INBOX_GATE_FILE
    if _INBOX_GATE_FILE is None:
        try:
            _INBOX_GATE_FILE = os.path.join(
                os.path.dirname(os.path.abspath(__file__)),
                "spellcaster_inbox_gate.json")
        except Exception:
            # Fallback: system temp if somehow __file__ isn't resolvable.
            _INBOX_GATE_FILE = os.path.join(
                tempfile.gettempdir(), "spellcaster_inbox_gate.json")
    return _INBOX_GATE_FILE


def _inbox_gate_read():
    try:
        with open(_inbox_gate_path(), "r", encoding="utf-8") as f:
            return float((json.load(f) or {}).get("last_poll_ts") or 0.0)
    except Exception:
        return 0.0


def _inbox_gate_write(ts):
    try:
        with open(_inbox_gate_path(), "w", encoding="utf-8") as f:
            json.dump({"last_poll_ts": float(ts)}, f)
    except Exception:
        pass  # best-effort — a missed write just re-polls sooner


def _drain_inbox_worker(*, http_timeout, per_asset_timeout, max_asset_size,
                        silent):
    """Pull and open gimp mailbox assets. Used by both the manual
    "Check Inbox" menu entry and the silent per-invocation auto-drain.

    Returns a dict:
      {"status":  "ok" | "empty" | "cross_interface_missing" |
                  "guild_backbone_off" | "guild_http_error" |
                  "guild_unreachable",
       "opened":  int,
       "failures": [str],
       "http_code": int | None,
       "error":    str | None}

    ``silent=True`` suppresses ``Gimp.message`` popups and caps size +
    timeouts so the auto-poll path never blocks a user for more than a
    few seconds even if the Guild is slow.
    """
    result = {"status": "ok", "opened": 0, "failures": [],
              "http_code": None, "error": None}
    try:
        from spellcaster_core.cross_interface import resolve_guild_url
    except ImportError as e:
        result["status"] = "cross_interface_missing"
        result["error"] = str(e)
        return result

    import urllib.request as _ur
    import urllib.error as _ue
    import urllib.parse as _up
    import json as _json

    guild_base = resolve_guild_url()
    url = f"{guild_base}/api/gimp/inbox?consume=1&max=20"
    try:
        req = _ur.Request(url, headers={"Accept": "application/json"})
        with _ur.urlopen(req, timeout=http_timeout) as resp:
            body = _json.loads(resp.read())
    except _ue.HTTPError as e:
        if e.code == 501:
            result["status"] = "guild_backbone_off"
        else:
            result["status"] = "guild_http_error"
            result["http_code"] = e.code
        return result
    except Exception as e:
        result["status"] = "guild_unreachable"
        result["error"] = str(e)
        return result

    messages = (body or {}).get("messages") or []
    keepers = [m for m in messages
                if (m.get("kind") or "").startswith("gimp.asset.")]
    if not keepers:
        result["status"] = "empty"
        return result

    opened = 0
    failures = []
    for m in keepers:
        md = m.get("data") or {}
        image_url = (md.get("image_url") or md.get("url") or "").strip()
        if not image_url:
            failures.append("(message with no image_url)")
            continue
        if image_url.startswith("/"):
            image_url = guild_base.rstrip("/") + image_url
        try:
            _scheme = _up.urlparse(image_url).scheme.lower()
        except Exception:
            _scheme = ""
        if _scheme not in ("http", "https"):
            failures.append(f"blocked non-http url: {image_url[:80]}")
            continue
        try:
            req = _ur.Request(image_url,
                              headers={"User-Agent": "spellcaster-gimp/2.0"})
            with _ur.urlopen(req, timeout=per_asset_timeout) as resp:
                asset_bytes = resp.read(max_asset_size + 1)
                if len(asset_bytes) > max_asset_size:
                    failures.append(
                        f"oversize (>{max_asset_size // (1024*1024)} MB): "
                        f"{image_url[:80]}")
                    continue
        except Exception as e:
            failures.append(f"download: {e}")
            continue
        suffix = ".png"
        if image_url.lower().endswith((".jpg", ".jpeg")):
            suffix = ".jpg"
        elif image_url.lower().endswith(".mp4"):
            failures.append(
                f"mp4 can't open in GIMP: {image_url.rsplit('/', 1)[-1]}")
            continue
        tmp = tempfile.NamedTemporaryFile(
            delete=False, suffix=suffix, prefix="spellcaster_inbox_")
        try:
            tmp.write(asset_bytes)
            tmp.close()
            gfile = Gio.File.new_for_path(tmp.name)
            new_image = Gimp.file_load(
                Gimp.RunMode.NONINTERACTIVE, gfile)
            if new_image is None:
                failures.append(f"GIMP couldn't load {tmp.name}")
                continue
            Gimp.Display.new(new_image)
            opened += 1
        except Exception as e:
            failures.append(f"load: {e}")

    result["opened"] = opened
    result["failures"] = failures
    return result


def _maybe_auto_drain_inbox():
    """Silent, interval-gated inbox drain. Called at the top of every
    wrapped Spellcaster procedure callback.

    Returns immediately if:
      - disabled via config (``auto_inbox_poll=false``);
      - less than ``_INBOX_POLL_INTERVAL_S`` has passed since the
        last drain (on-disk timestamp);
      - any exception during gate read (fail-open skips the drain
        rather than risk blocking the user).

    NEVER raises. Prints any internal error to stdout for the dev log
    but does not surface to the user — the auto path is fire-and-forget.
    """
    try:
        cfg = _load_config()
        if not cfg.get("auto_inbox_poll", True):
            return
        now = time.time()
        last = _inbox_gate_read()
        if (now - last) < _INBOX_POLL_INTERVAL_S:
            return
        _inbox_gate_write(now)
        result = _drain_inbox_worker(
            http_timeout=_INBOX_AUTO_HTTP_TIMEOUT,
            per_asset_timeout=_INBOX_AUTO_ASSET_TIMEOUT,
            max_asset_size=_INBOX_AUTO_MAX_SIZE,
            silent=True)
        # Only log when something actually happened — silent drains
        # shouldn't clutter the dev console.
        if result.get("opened"):
            print(f"[Spellcaster] Auto-drained {result['opened']} "
                  f"inbox asset(s)")
    except Exception as e:
        print(f"[Spellcaster] auto inbox drain skipped: {e}")


def _wrap_auto_drain(callback):
    """Wrap a GIMP procedure callback so the inbox auto-drain runs
    before the user's action. The drain is capped by timeout + size
    (see `_INBOX_AUTO_*` constants) so even a slow or hostile Guild
    can't block the user more than a few seconds. Errors from the
    drain NEVER propagate to the wrapped callback.
    """
    def wrapped(procedure, run_mode, image, drawables, config, data):
        _maybe_auto_drain_inbox()
        return callback(procedure, run_mode, image, drawables, config, data)
    return wrapped


def _auto_enhance(prompt, arch_key, negative="", model_name=None,
                   method="scene"):
    """Enhance a prompt via local LLM if the global toggle is ON.

    Args:
        prompt:     raw user prompt
        arch_key:   diffusion family (sdxl, flux2klein, ...)
        negative:   negative prompt (returned unchanged — architectures
                    already ship optimal quality_negative lists)
        model_name: optional concrete checkpoint name; used by
                    spellcaster_core.llm_prompt_db to overlay per-model
                    hints / sampling overrides on top of the arch baseline.
        method:     generation method this prompt feeds (default "scene"
                    for full-image txt2img/img2img). Methods with narrow
                    scope — inpaint, outpaint, refine, face_detail, tryon,
                    iclight, colorize — scope the enhancement so the LLM
                    doesn't over-describe outside the method's region of
                    interest. Methods like "kontext", "faceswap",
                    "upscale", "rembg" skip enhancement entirely.

    Returns (enhanced_prompt, enhanced_negative). If enhancement is
    disabled, the LLM is unreachable, or the prompt is already detailed,
    returns the originals unchanged. Never blocks generation.
    """
    if not _PROMPT_ENHANCE or not prompt or not prompt.strip():
        return prompt, negative
    # Never enhance turbo models (ZIT) — fast-step samplers don't need it.
    if arch_key == "zit":
        return prompt, negative
    # flux_kontext uses edit-instruction prompts; handled via method="edit"
    # by callers but we keep the legacy arch-level guard for safety.
    if arch_key == "flux_kontext" and method == "scene":
        method = "edit"
    try:
        from spellcaster_core.prompt_enhance import enhance_prompt
        enhanced = enhance_prompt(prompt, arch_key, _LLM_URL, is_negative=False,
                                  comfy_url=COMFYUI_DEFAULT_URL,
                                  model_name=model_name,
                                  method=method)
        if enhanced and enhanced != prompt:
            tail = f", {model_name.split('/')[-1]}" if model_name else ""
            mtag = f"/{method}" if method and method != "scene" else ""
            print(f"[Spellcaster] Prompt enhanced ({arch_key}{mtag}{tail}): "
                  f"{len(prompt.split())}→{len(enhanced.split())} words")
        else:
            enhanced = prompt
        # Don't enhance negative — architecture quality_negative is already optimal
        return enhanced, negative
    except Exception as e:
        print(f"[Spellcaster] Prompt enhance skipped: {e}")
        return prompt, negative


