# Skin-specific anti-artifact prompts (for skin-heavy content)
SKIN_REALISM_POSITIVE = (
    "natural skin texture, visible pores, subsurface scattering, realistic skin tone, "
    "natural skin imperfections, peach fuzz, moles, freckles"
)
SKIN_REALISM_NEGATIVE = (
    "plastic skin, orange peel texture, waxy skin, airbrushed, porcelain doll, "
    "mannequin, smooth plastic, crunchy artifacts, oversaturated skin"
)


def _boost_prompt(prompt, arch="sdxl", skin_realism=False):
    """Prepend quality tokens to a prompt for better photorealism.

    arch: architecture key (sd15, sdxl, flux1dev, etc.)
    skin_realism: if True, also adds skin-specific realism tokens.
    """
    prefix = QUALITY_BOOST_POSITIVE.get(arch, QUALITY_BOOST_POSITIVE["sdxl"])
    if skin_realism:
        prefix = prefix + ", " + SKIN_REALISM_POSITIVE
    if prompt.strip():
        return prefix + ", " + prompt
    return prefix


def _boost_negative(negative, arch="sdxl", skin_realism=False):
    """Prepend quality-boost negative tokens to a negative prompt.

    arch: architecture key (sd15, sdxl, flux1dev, etc.)
    skin_realism: if True, also adds skin-specific anti-artifact tokens.
    """
    prefix = QUALITY_BOOST_NEGATIVE.get(arch, QUALITY_BOOST_NEGATIVE["sdxl"])
    if skin_realism:
        prefix = prefix + ", " + SKIN_REALISM_NEGATIVE
    if negative.strip():
        return prefix + ", " + negative
    return prefix


def _save_config(data):
    """Write config.json to the plugin directory, merging with existing config.
    Thread-safe: serialized with _load_config via _config_lock."""
    cfg_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "config.json")
    with _config_lock:
        try:
            with open(cfg_path, "r", encoding="utf-8") as f:
                existing = json.load(f)
        except Exception:
            existing = {}
        existing.update(data)
        try:
            with open(cfg_path, "w", encoding="utf-8") as f:
                json.dump(existing, f, indent=2)
        except Exception:
            pass

def _propagate_server_url(new_url):
    """Update the session-wide default server URL and persist to config.json."""
    global COMFYUI_DEFAULT_URL
    new_url = new_url.strip().rstrip("/")
    if new_url and new_url != COMFYUI_DEFAULT_URL:
        COMFYUI_DEFAULT_URL = new_url
        _save_config({"server_url": new_url})

# ── Session state — remembers last-used settings per dialog ──────────
# In-memory only: forgotten when GIMP restarts. Each dialog type stores
# its last-used values here so reopening the same tool pre-fills with
# the user's previous settings. Persisted to session_state.json on disk.
_SESSION_PATH = Path(__file__).parent / "session_state.json"

def _load_session():
    try:
        return json.loads(_SESSION_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}

def _save_session():
    try:
        _SESSION_PATH.write_text(json.dumps(_SESSION, indent=2, default=str), encoding="utf-8")
    except Exception:
        pass

def _session_to_values(key, image=None):
    """Reconstruct a get_values()-compatible dict from saved session state.

    Used by WITH_LAST_VALS (GIMP Repeat) to re-run without showing the dialog.
    Returns None if no session data exists for this key.
    """
    s = _SESSION.get(key)
    if not s:
        return None
    idx = s.get("model_preset_idx", 0)
    preset = dict(MODEL_PRESETS[idx] if 0 <= idx < len(MODEL_PRESETS) else MODEL_PRESETS[0])
    preset["steps"] = s.get("steps", preset["steps"])
    preset["cfg"] = s.get("cfg", preset["cfg"])
    preset["denoise"] = s.get("denoise", preset.get("denoise", 0.6))
    preset["width"] = s.get("width", image.get_width() if image else preset.get("width", 1024))
    preset["height"] = s.get("height", image.get_height() if image else preset.get("height", 1024))
    preset["sampler"] = s.get("sampler", preset["sampler"])
    preset["scheduler"] = s.get("scheduler", preset["scheduler"])
    seed = s.get("seed", -1)
    if seed < 0:
        seed = random.randint(0, 2**32 - 1)
    # Style preset recall
    style_preset = None
    prompt_text = s.get("prompt", preset.get("prompt_hint", ""))
    negative_text = s.get("negative", preset.get("negative_hint", ""))
    loras = s.get("loras", [])
    style_idx = s.get("style_idx", 0)
    if style_idx and 0 < style_idx < len(IMG2IMG_STYLE_PRESETS):
        style_preset = IMG2IMG_STYLE_PRESETS[style_idx]
        if style_preset["prompt"]:
            prompt_text = (prompt_text + ", " + style_preset["prompt"]) if prompt_text else style_preset["prompt"]
        if style_preset["negative"]:
            negative_text = (negative_text + ", " + style_preset["negative"]) if negative_text else style_preset["negative"]
        arch = preset.get("arch", "sdxl")
        style_loras = style_preset["loras"].get(arch, [])
        existing_names = {l["name"] for l in loras} if isinstance(loras, list) and loras else set()
        for lora_path, model_str, clip_str in style_loras:
            if lora_path not in existing_names:
                loras.append({
                    "name": lora_path,
                    "strength_model": model_str,
                    "strength_clip": clip_str,
                })

    return {
        "server": COMFYUI_DEFAULT_URL,
        "preset": preset,
        "prompt": prompt_text,
        "negative": negative_text,
        "seed": seed,
        "loras": loras,
        "controlnet": {
            "mode": s.get("cn_mode", "Off"),
            "strength": s.get("cn_strength", 0.8),
            "start_percent": s.get("cn_start", 0.0),
            "end_percent": s.get("cn_end", 1.0),
        },
        "controlnet_2": {
            "mode": s.get("cn_mode_2", "Off"),
            "strength": s.get("cn_strength_2", 0.6),
            "start_percent": 0.0,
            "end_percent": 1.0,
        },
        "custom_workflow": None,
        "runs": s.get("runs", 1),
        "style_preset": style_preset,
    }

_SESSION = _load_session()

# User presets persist prompt/model/LoRA combinations across sessions
_USER_PRESETS_PATH = Path(__file__).parent / "user_presets.json"

def _load_user_presets(dialog_key="preset_dialog"):
    """Load user-saved preset configurations from user_presets.json.

    Supports keyed dict format (multiple dialog types) and auto-migrates
    the old flat list format under the "preset_dialog" key.
    """
    try:
        all_data = json.loads(_USER_PRESETS_PATH.read_text(encoding="utf-8"))
        if isinstance(all_data, list):
            # Old format: flat list belongs to preset_dialog
            return all_data if dialog_key == "preset_dialog" else []
        return all_data.get(dialog_key, [])
    except Exception:
        return []

def _save_user_presets(presets, dialog_key="preset_dialog"):
    """Persist user presets to disk. Fails silently on write errors.

    Stores presets in a keyed dict so different dialogs don't collide.
    Auto-migrates old flat list format on first write.
    """
    try:
        all_data = {}
        try:
            raw = json.loads(_USER_PRESETS_PATH.read_text(encoding="utf-8"))
            if isinstance(raw, list):
                all_data = {"preset_dialog": raw}
            else:
                all_data = raw
        except Exception:
            pass
        all_data[dialog_key] = presets
        _USER_PRESETS_PATH.write_text(
            json.dumps(all_data, indent=2, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass


# ── Reusable user-preset UI helpers ──────────────────────────────────────
# These functions add Save / Load / Delete preset functionality to any
# dialog class.  The dialog must implement two methods:
#   _collect_user_preset()  → dict of saveable widget values
#   _apply_user_preset(p)   → restore widget values from a dict
#
# Usage in __init__:  _add_preset_ui(self, parent_box, "my_dialog_key")

def _add_preset_ui(dialog, box, dialog_key):
    """Add a My Presets bar (combo + Load / Save / Delete) to *dialog*.

    Stores helper state on the dialog instance:
      dialog._up_key      — storage key in user_presets.json
      dialog._up_presets  — in-memory list of presets for this key
      dialog._up_combo    — the GtkComboBoxText widget
    """
    dialog._up_key = dialog_key
    dialog._up_presets = _load_user_presets(dialog_key)

    up_hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
    up_hb.pack_start(Gtk.Label(label="My Presets:"), False, False, 0)
    dialog._up_combo = Gtk.ComboBoxText()
    dialog._up_combo.set_hexpand(True)
    dialog._up_combo.set_tooltip_text("Your saved parameter presets. Save and load your favorite settings.")
    up_hb.pack_start(dialog._up_combo, True, True, 0)

    load_btn = Gtk.Button(label="Load")
    load_btn.set_tooltip_text("Load the selected preset into all fields")
    load_btn.connect("clicked", lambda _b: _up_load(dialog))
    up_hb.pack_start(load_btn, False, False, 0)

    save_btn = Gtk.Button(label="Save\u2026")
    save_btn.set_tooltip_text("Save current settings as a named preset")
    save_btn.connect("clicked", lambda _b: _up_save(dialog))
    up_hb.pack_start(save_btn, False, False, 0)

    del_btn = Gtk.Button(label="\u2715")
    del_btn.set_tooltip_text("Delete selected preset")
    del_btn.connect("clicked", lambda _b: _up_delete(dialog))
    up_hb.pack_start(del_btn, False, False, 0)

    box.pack_start(up_hb, False, False, 0)
    _up_refresh(dialog)


def _up_refresh(dialog):
    """Repopulate the preset combo from the in-memory list."""
    dialog._up_combo.remove_all()
    for p in dialog._up_presets:
        dialog._up_combo.append_text(p["name"])
    if dialog._up_presets:
        dialog._up_combo.set_active(0)


def _up_load(dialog):
    """Load the currently selected preset into dialog widgets."""
    idx = dialog._up_combo.get_active()
    if idx < 0 or idx >= len(dialog._up_presets):
        return
    if hasattr(dialog, "_apply_user_preset"):
        dialog._apply_user_preset(dialog._up_presets[idx])


def _up_save(dialog):
    """Prompt for a name and save the current dialog state as a preset."""
    dlg = Gtk.Dialog(title="Save Preset", transient_for=dialog, modal=True)
    dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
    dlg.add_button("_Save", Gtk.ResponseType.OK)
    dlg.set_default_response(Gtk.ResponseType.OK)
    area = dlg.get_content_area()
    area.set_spacing(8)
    area.set_margin_start(12); area.set_margin_end(12)
    area.set_margin_top(12); area.set_margin_bottom(12)
    area.pack_start(Gtk.Label(label="Preset name:"), False, False, 0)
    name_entry = Gtk.Entry()
    name_entry.set_activates_default(True)
    name_entry.set_tooltip_text("Name for saving. Use descriptive text like 'my_portrait'.")
    cur_idx = dialog._up_combo.get_active()
    if 0 <= cur_idx < len(dialog._up_presets):
        name_entry.set_text(dialog._up_presets[cur_idx]["name"])
    area.pack_start(name_entry, False, False, 0)
    area.show_all()
    resp = dlg.run()
    name = name_entry.get_text().strip()
    dlg.destroy()
    if resp != Gtk.ResponseType.OK or not name:
        return
    data = dialog._collect_user_preset()
    data["name"] = name
    existing = next((i for i, p in enumerate(dialog._up_presets) if p["name"] == name), None)
    if existing is not None:
        dialog._up_presets[existing] = data
    else:
        dialog._up_presets.append(data)
    _save_user_presets(dialog._up_presets, dialog._up_key)
    _up_refresh(dialog)
    new_idx = next((i for i, p in enumerate(dialog._up_presets) if p["name"] == name), 0)
    dialog._up_combo.set_active(new_idx)


def _up_delete(dialog):
    """Delete the selected preset after confirmation."""
    idx = dialog._up_combo.get_active()
    if idx < 0 or idx >= len(dialog._up_presets):
        return
    name = dialog._up_presets[idx]["name"]
    dlg = Gtk.MessageDialog(transient_for=dialog, modal=True,
                            message_type=Gtk.MessageType.QUESTION,
                            buttons=Gtk.ButtonsType.YES_NO,
                            text=f'Delete preset "{name}"?')
    resp = dlg.run()
    dlg.destroy()
    if resp == Gtk.ResponseType.YES:
        del dialog._up_presets[idx]
        _save_user_presets(dialog._up_presets, dialog._up_key)
        _up_refresh(dialog)

# ── Runs spinner helper ────────────────────────────────────────────────
# Adds a "Runs" spinner (1-99) to any dialog so users can queue multiple
# generations from one dialog submit.  Each run gets a fresh random seed.

def _add_runs_spinner(dialog, box):
    """Add a 'Runs' spinner (1-99) to the bottom of any dialog.

    Lets the user queue multiple generations from one dialog submit.
    Each run gets a fresh random seed (unless the user set a specific seed).
    """
    hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
    hb.pack_start(Gtk.Label(label="Runs:"), False, False, 0)
    dialog._runs_spin = Gtk.SpinButton.new_with_range(1, 99, 1)
    dialog._runs_spin.set_value(1)
    dialog._runs_spin.set_tooltip_text(
        "Number of times to run this generation. Each run uses a fresh random seed.")
    hb.pack_start(dialog._runs_spin, False, False, 0)
    hb.pack_start(Gtk.Label(label="(each run gets a new seed)"), False, False, 0)
    box.pack_start(hb, False, False, 0)


def _add_normal_map_selector(dialog, box, image):
    """Add a normal map layer dropdown to any dialog.

    Scans the image's layers for any with 'normal' in the name and
    populates a dropdown. When no candidate layer exists, shows an
    inline "Generate now" button that runs NormalCrafter in-place and
    adds the result as a new layer — no dialog-cancel dance required
    (fix 2 from the 2026-04-20 3D audit).

    Sets dialog._normal_combo (ComboBoxText) and dialog._normal_enabled
    (CheckButton). Use dialog._normal_combo.get_active_id() to get the
    layer index, or None/"none" if disabled.
    """
    frame = Gtk.Frame(label="  3D Normal Map (optional)  ")
    fbox = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=4)
    fbox.set_margin_start(8); fbox.set_margin_end(8)
    fbox.set_margin_top(4); fbox.set_margin_bottom(6)

    dialog._normal_enabled = Gtk.CheckButton(label="Use normal map for 3D-aware generation")
    dialog._normal_enabled.set_tooltip_text(
        "When enabled, the selected normal map layer provides 3D surface\n"
        "information to the AI. This dramatically improves:\n"
        "  • Relighting accuracy (light wraps around surfaces correctly)\n"
        "  • Inpainting consistency (fills respect 3D geometry)\n"
        "  • Style transfer (preserves 3D structure)")
    fbox.pack_start(dialog._normal_enabled, False, False, 0)

    dialog._normal_combo = Gtk.ComboBoxText()
    dialog._normal_combo.append("none", "(no normal map)")
    dialog._normal_combo.set_tooltip_text(
        "Pick the layer that holds the 3D normal map.\n"
        "Normal maps are RGB images where R=X, G=Y, B=Z surface direction.\n"
        "Only layers with 'normal' in their name are pre-filtered; click\n"
        "the Generate button below if no candidate is present.")

    # Populate with layers that look like normal maps (● prefix) first,
    # then all remaining layers (so the user can still manually pick
    # any layer if they named their normal layer something odd).
    found_normal = False
    normal_layers: list[tuple[int, str]] = []
    other_layers: list[tuple[int, str]] = []
    for i, layer in enumerate(image.get_layers()):
        name = layer.get_name() or f"Layer {i}"
        if "normal" in name.lower():
            normal_layers.append((i, name))
        else:
            other_layers.append((i, name))
    for i, name in normal_layers:
        dialog._normal_combo.append(str(i), f"● {name}")
        if not found_normal:
            dialog._normal_combo.set_active_id(str(i))
            dialog._normal_enabled.set_active(True)
            found_normal = True
    for i, name in other_layers:
        dialog._normal_combo.append(str(i), name)

    if not found_normal:
        dialog._normal_combo.set_active_id("none")
        dialog._normal_enabled.set_active(False)

    fbox.pack_start(dialog._normal_combo, False, False, 0)

    # Inline "Generate now" row — removes the cancel-and-reopen dance
    # when the user hasn't made a normal map yet. Runs NormalCrafter
    # in place, adds the result as a new layer named 'Normal Map
    # (auto)', then re-populates this combo so the new layer is the
    # selected candidate. Pre-flights the NormalCrafter node + server
    # reachability before running.
    gen_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
    gen_btn = Gtk.Button(label=" Generate normal map now ")
    gen_btn.set_tooltip_text(
        "Run NormalCrafter on the current canvas and import the 3D\n"
        "normal map as a new layer. Takes ~10-60 s depending on\n"
        "resolution and server load. The new layer is selected\n"
        "automatically so you can click OK to use it immediately.")
    gen_status = Gtk.Label(label="")
    gen_status.set_xalign(0.0)

    def _do_generate(_btn):
        try:
            srv = (_load_config().get("server_url")
                   or COMFYUI_DEFAULT_URL)
            nodes = _probe_comfyui_nodes(srv)
            if nodes and "NormalCrafterNode" not in nodes:
                gen_status.set_markup(
                    '<span color="#c06040">⚠ Install NormalCrafter '
                    'node on ComfyUI first.</span>')
                return
            gen_btn.set_sensitive(False)
            gen_status.set_text("Exporting canvas…")
            while Gtk.events_pending():
                Gtk.main_iteration()
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_nm_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname)
            os.unlink(tmp)
            gen_status.set_text("Generating… (may take ~30 s)")
            while Gtk.events_pending():
                Gtk.main_iteration()
            from spellcaster_core.workflows import build_normal_map
            wf = build_normal_map(
                uname,
                max_res=min(image.get_width(), 1024))
            results = list(_run_comfyui_workflow(srv, wf, timeout=300))
            if not results:
                gen_status.set_markup(
                    '<span color="#c06040">⚠ No result from server.'
                    '</span>')
                gen_btn.set_sensitive(True)
                return
            fn, sf, ft = results[0]
            data = _download_image(srv, fn, sf, ft)
            new_layer_name = "Normal Map (auto)"
            _import_result_as_layer(image, data,
                                     new_layer_name, keep_size=True)
            # Re-populate the combo so the new layer appears with the
            # ● prefix + is selected. Easier than surgically inserting.
            dialog._normal_combo.remove_all()
            dialog._normal_combo.append("none", "(no normal map)")
            for i, layer in enumerate(image.get_layers()):
                n = layer.get_name() or f"Layer {i}"
                label = f"● {n}" if "normal" in n.lower() else n
                dialog._normal_combo.append(str(i), label)
            # Find the freshly-inserted layer index and select it
            for i, layer in enumerate(image.get_layers()):
                if (layer.get_name() or "") == new_layer_name:
                    dialog._normal_combo.set_active_id(str(i))
                    dialog._normal_enabled.set_active(True)
                    dialog._normal_combo.set_sensitive(True)
                    break
            gen_status.set_markup(
                '<span color="#4a8a4a">✓ Normal map ready.</span>')
            gen_btn.set_sensitive(True)
        except Exception as _e:
            gen_status.set_markup(
                f'<span color="#c06040">⚠ {_e}</span>')
            gen_btn.set_sensitive(True)

    gen_btn.connect("clicked", _do_generate)
    gen_row.pack_start(gen_btn, False, False, 0)
    gen_row.pack_start(gen_status, True, True, 6)
    fbox.pack_start(gen_row, False, False, 0)

    # Grey out combo when checkbox unchecked
    dialog._normal_combo.set_sensitive(found_normal)
    def _on_toggle(cb):
        dialog._normal_combo.set_sensitive(cb.get_active())
    dialog._normal_enabled.connect("toggled", _on_toggle)

    frame.add(fbox)
    box.pack_start(frame, False, False, 0)


def _export_normal_map_layer(image, layer_index):
    """Export a specific layer as a temp PNG file for upload to ComfyUI.

    Temporarily makes only the target layer visible, exports the
    flattened image, then restores original visibility.

    Returns the temp file path (caller must unlink after upload).
    """
    layers = image.get_layers()
    if layer_index < 0 or layer_index >= len(layers):
        return None

    # Save and hide all layers
    orig_vis = [(l, l.get_visible()) for l in layers]
    for l, _ in orig_vis:
        l.set_visible(False)
    layers[layer_index].set_visible(True)

    # Export
    path = _export_image_to_tmp(image)

    # Restore
    for l, v in orig_vis:
        l.set_visible(v)

    return path


def _collect_normal_map_from_dialog(dlg, image, server_url):
    """If the dialog's normal-map picker is enabled + a layer is
    selected, export that layer to a PNG and upload it to ComfyUI's
    input directory. Returns the uploaded filename, or None when the
    feature is disabled / unconfigured.

    Silently no-ops when the dialog hasn't had `_add_normal_map_selector`
    called on it — every caller passes any dlg, and we check for the
    attributes before reading.
    """
    cb = getattr(dlg, "_normal_enabled", None)
    cmb = getattr(dlg, "_normal_combo", None)
    if cb is None or cmb is None or not cb.get_active():
        return None
    idx_id = cmb.get_active_id()
    if not idx_id or idx_id == "none":
        return None
    try:
        idx = int(idx_id)
    except (TypeError, ValueError):
        return None
    tmp = _export_normal_map_layer(image, idx)
    if not tmp:
        return None
    nm_name = f"gimp_nm_{uuid.uuid4().hex[:8]}.png"
    try:
        _upload_image(server_url, tmp, nm_name)
    except Exception as e:
        print(f"[Spellcaster] normal-map upload failed: {e}")
        try:
            os.unlink(tmp)
        except Exception:
            pass
        return None
    try:
        os.unlink(tmp)
    except Exception:
        pass
    return nm_name


#: Arch keys that cannot accept ControlNet conditioning at all — the
#: canonical `build_*` functions silently skip CN injection for these
#: (see workflows.py guard `arch_key not in ("flux2klein","flux_kontext",
#: "chroma")`). Exposed here so the dialog layer can warn the user
#: BEFORE they submit, instead of silently dropping their normal map.
_CN_INCOMPATIBLE_ARCHS = frozenset({"flux2klein", "flux_kontext", "chroma"})


def _maybe_override_cn_with_normal_map(controlnet, normal_map_filename,
                                         arch_key=None):
    """Overlay the 'Normal Map (use existing layer)' CN mode onto the
    user's ControlNet selection whenever a normal-map filename is set.

    The user's strength / start_percent / end_percent choices are
    preserved — only the mode + ref_image_filename are replaced. When
    they hadn't picked a CN at all, we default to strength=0.8 (solid
    3D guidance, still leaves room for prompt creativity).

    canonical inject_controlnet (composites.py) reads the
    `ref_image_filename` key and loads that file via LoadImage as the
    CN input — see CLAUDE.md note on 3D normal map integration.

    When ``arch_key`` identifies a ControlNet-incompatible architecture
    (flux2klein / flux_kontext / chroma), we show a Gimp.message
    explaining the normal map will be ignored for this run — instead
    of silently dropping it at workflow build time (fix 3 from the
    2026-04-20 3D audit).
    """
    if not normal_map_filename:
        return controlnet
    if arch_key in _CN_INCOMPATIBLE_ARCHS:
        # Fail visibly rather than silently. Return the user's original
        # (possibly None) controlnet unchanged — we're not injecting
        # the normal-map mode because it would be a no-op anyway.
        try:
            Gimp.message(
                f"3D Normal Map is not supported on this architecture "
                f"({arch_key}).\n\n"
                f"Flux Klein, Flux Kontext, and Chroma don't accept "
                f"ControlNet conditioning. The normal map will be "
                f"ignored for this run.\n\n"
                f"Use SD 1.5, SDXL, Illustrious, Flux.1-dev, or "
                f"Z-Image-Turbo if you need normal-map guidance.")
        except Exception:
            # Gimp may not be imported in bare-test contexts.
            print(f"[Spellcaster] Normal Map skipped: "
                  f"arch {arch_key} does not support ControlNet.")
        return controlnet
    merged = dict(controlnet or {})
    merged["mode"] = "Normal Map (use existing layer) — all archs"
    merged["ref_image_filename"] = normal_map_filename
    merged.setdefault("strength", 0.8)
    merged.setdefault("start_percent", 0.0)
    merged.setdefault("end_percent", 1.0)
    return merged


def _add_mask_mode_checkbox(dialog, box):
    """Add a 'Generate as Mask (transparent)' checkbox to any image dialog.

    When enabled, the result is post-processed through rembg to remove
    the background and produce a transparent PNG with alpha channel.
    Useful for creating cutouts, overlays, compositing elements, etc.
    """
    dialog._mask_mode_check = Gtk.CheckButton(label="Generate as Transparent Mask (remove background)")
    dialog._mask_mode_check.set_active(False)
    dialog._mask_mode_check.set_tooltip_text(
        "Transparent Mask Mode — auto-removes background after generation.\n\n"
        "When enabled, the AI generates the image normally, then runs\n"
        "background removal (rembg) to produce a transparent PNG.\n\n"
        "USE CASES:\n"
        "  - Create character cutouts for compositing\n"
        "  - Generate objects/props with transparent background\n"
        "  - Make overlay elements for video scenes\n"
        "  - Extract subjects for Studio Set actor placement\n"
        "  - Create stickers, overlays, collage elements\n\n"
        "The result is imported as a layer with alpha channel.\n"
        "Requires: rembg custom node on your ComfyUI server.")
    box.pack_start(dialog._mask_mode_check, False, False, 0)


def _apply_mask_mode(server, image, img_data, layer_name, mask_enabled):
    """Import image data as layer, optionally with background removed.

    If mask_enabled is True, runs rembg on the result first to produce
    a transparent PNG, then imports that as the layer.

    Returns True if successful.
    """
    if mask_enabled:
        # Upload the image, run rembg, get transparent result
        try:
            rembg_input = f"gimp_masktmp_{uuid.uuid4().hex[:8]}.png"
            tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
            tmp.write(img_data); tmp.close()
            _upload_image(server, tmp.name, rembg_input)
            os.unlink(tmp.name)
            wf = build_rembg(rembg_input)
            results = list(_run_comfyui_workflow(server, wf))
            for fn, sf, ft in results:
                if fn.lower().endswith(".png"):
                    img_data = _download_image(server, fn, sf, ft)
                    layer_name = f"{layer_name} (transparent)"
                    break
        except Exception:
            pass  # rembg failed — import as-is

    _import_result_as_layer(image, img_data, layer_name)
    return True


# ═══════════════════════════════════════════════════════════════════════════
#  MODEL PRESETS — one img2img workflow per checkpoint, tuned per arch
# ═══════════════════════════════════════════════════════════════════════════
# Each preset defines a complete set of generation parameters for a specific
# checkpoint model. Fields:
#   label      — display name in the UI dropdown
#   arch       — architecture key (sd15/sdxl/flux1dev/flux2klein/flux_kontext/zit)
#                used to filter compatible LoRAs via ARCH_LORA_PREFIXES
#   ckpt       — checkpoint filename relative to ComfyUI's models/checkpoints/
#   width/height — native resolution for this model (512 for SD1.5, 1024 for SDXL/Flux)
#   steps      — denoising steps (more = slower but more detailed)
#   cfg        — classifier-free guidance scale (how strictly to follow the prompt)
#   denoise    — denoising strength for img2img (0=no change, 1=full regeneration)
#   sampler    — sampling algorithm (euler, dpmpp_2m, euler_ancestral, etc.)
#   scheduler  — noise schedule (karras, normal, simple, sgm_uniform, etc.)
#   prompt_hint    — example positive prompt pre-filled for the user
#   negative_hint  — example negative prompt (empty for Flux/Klein which don't use negatives)


