def _get_turbo_config(arch):
    """Return the turbo config for an architecture, or None if unsupported."""
    return TURBO_CONFIGS.get(arch)


# ═══════════════════════════════════════════════════════════════════════════
#  Scene / Subject Presets — beginner-friendly prompt templates per category
# ═══════════════════════════════════════════════════════════════════════════
# Keyed by (architecture, category). When a user picks a scene preset,
# the prompt and negative are filled in automatically — zero typing needed.
# The first entry "(custom)" means the user writes their own prompt.
#
# Architecture groups:
#   "sd15"         — SD 1.5 models (Juggernaut Reborn, Realistic Vision, etc.)
#   "sdxl"         — SDXL realistic/general models
#   "sdxl_anime"   — SDXL anime/pony models (NoobAI, Nova Anime, Wai, CyberRealistic Pony)
#   "sdxl_cartoon" — SDXL cartoon/3D (Modern Disney, Nova Cartoon)
#   "flux"         — Flux 1 Dev and Flux 2 Klein (natural language, no quality tags)
#   "flux_kontext" — Flux Kontext (edit instructions, not descriptions)

def _scene_arch(model_arch, model_label=""):
    """Map a MODEL_PRESETS arch + label to the scene preset architecture group."""
    label_lower = model_label.lower()
    if model_arch in ("flux1dev", "flux2klein"):
        return "flux"
    if model_arch == "flux_kontext":
        return "flux_kontext"
    if model_arch == "zit":
        return "sdxl"  # ZIT uses SDXL-style prompts
    if model_arch == "sd15":
        return "sd15"
    # SDXL sub-groups
    if any(kw in label_lower for kw in ("anime", "noob", "nova anime", "wai", "pony", "cyberrealistic pony")):
        return "sdxl_anime"
    if any(kw in label_lower for kw in ("disney", "cartoon", "nova cartoon")):
        return "sdxl_cartoon"
    return "sdxl"  # default for SDXL/Illustrious realistic

def _load_presets_json(filename, fallback=None):
    """Load a preset list from presets/<filename>.json next to this file."""
    try:
        _pdir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "presets")
        with open(os.path.join(_pdir, filename), "r", encoding="utf-8") as _f:
            loaded = json.load(_f)
        # Convert [pos, neg] lists back to tuples for prompt pairs
        for entry in loaded:
            if "prompts" in entry:
                for arch, pair in entry["prompts"].items():
                    if isinstance(pair, list) and len(pair) == 2:
                        entry["prompts"][arch] = tuple(pair)
        return loaded
    except Exception as e:
        print(f"Spellcaster: Could not load {filename}: {e}")
        return fallback if fallback is not None else []


SCENE_PRESETS = _load_presets_json("scene_presets.json",
    fallback=[{"label": "(custom \u2014 write your own)"}])


# ═══════════════════════════════════════════════════════════════════════════
#  Inpaint Refinement Presets — body-part-specific prompts, LoRAs, settings
# ═══════════════════════════════════════════════════════════════════════════
# These presets auto-fill the inpaint dialog with optimized prompts, LoRAs,
# and generation parameters for fixing specific body parts or applying
# creative effects. When the user selects one, _on_refinement_changed()
# populates all relevant fields.
#
# Each entry:
#   label          — display name in the inpaint refinement dropdown
#   prompt         — positive prompt text (overwrites user's prompt)
#   negative       — negative prompt text
#   denoise        — override denoise strength (None = keep model default)
#   cfg_boost      — added to the model's base CFG (e.g. +1.0 for stronger guidance)
#   steps_override — override step count (None = keep model default)
#   loras          — dict of arch → [(lora_path, model_strength, clip_strength), ...]
#                    auto-selected if the LoRA exists on the server
# The first LoRA in each list is the primary recommendation; extras are stacked.

INPAINT_REFINEMENTS = _load_presets_json("inpaint_refinements.json",
    fallback=[{"label": "(none \u2014 manual prompt)", "prompt": "", "negative": "",
              "denoise": None, "cfg_boost": 0, "steps_override": None, "loras": {}}])

# Style presets usable across img2img, txt2img, and inpaint
# References the ✦ presets from INPAINT_REFINEMENTS (style/effect based, not body-part fixes)
IMG2IMG_STYLE_PRESETS = [
    {"label": "(none — no style)", "prompt": "", "negative": "", "denoise": None,
     "cfg_boost": 0, "steps_override": None, "loras": {}},
] + [p for p in INPAINT_REFINEMENTS if p["label"].startswith("\u2726")]


_IMAGE_ARCHS = frozenset({
    "sd15", "sdxl", "zit", "illustrious", "pony",
    "flux2klein", "flux1dev", "flux_kontext", "chroma",
})

# Strong video-LoRA markers. Matching is case-insensitive on the
# lowered full path (folder + filename) so a generic filename inside a
# WAN/LTX folder still gets flagged (e.g. `Wan-2.2-I2V/KISSHIGH.safetensors`
# carries no tags in the file portion but the folder clearly marks it
# as video-only). Each pattern is a strong video indicator — no
# legitimate image LoRA uses these tokens.
#
#   wan2.1 / wan2.2 / wan22 / wan-2.1 / wan_2_2 — Wan 2.x family
#   i2v with non-alphanum boundaries             — image-to-video tag
#   high_noise / low_noise / highnoise / lownoise — Wan dual-UNET split
#   lightx2v                                     — Wan accel LoRA family
#   wan-lightning                                — Wan lightning family
#   ltxv / ltx-2 / ltx_2 / ltx2 / ltx-distill    — LTX 2.x family
#   seed-vr / seedvr                             — SeedVR family
_VIDEO_LORA_RE = re.compile(
    r'(?:'
    r'wan[-_]?2[.\-_]?[12]'
    r'|(?<![a-z0-9])i2v(?![a-z0-9])'
    r'|(?:high|low)[_-]?noise'
    r'|lightx2v'
    r'|wan[-_]?lightning'
    r'|ltx[-_]?(?:2|v|distill)'
    r'|ltx2(?![a-z0-9])'
    r'|seed[-_]?vr'
    r')',
    re.IGNORECASE,
)


def _looks_like_video_lora(lora_name):
    """Return True if the LoRA path has strong video-only markers.

    Image architectures (SD15 / SDXL / Illustrious / Pony / Flux /
    Klein / Kontext / Chroma / ZIT) NEVER load WAN, LTX, or SeedVR
    LoRAs — different UNET family → immediate crash or silently
    mangled output. This path-level check is the last line of
    defence if a user drops a WAN LoRA into SDXL\\ by mistake or
    the server stores everything in a flat folder. The regex
    inspects the full path (lowered) so a bare filename like
    `KISSHIGH.safetensors` under `Wan-2.2-I2V/` is still caught.
    """
    path = lora_name.replace("\\", "/").lower()
    return bool(_VIDEO_LORA_RE.search(path))


def cn_modes_for_arch(modes_dict, target_arch):
    """List of CONTROLNET_GUIDE_MODES keys compatible with ``target_arch``.

    Thin local wrapper that delegates to the canonical
    spellcaster_core.model_detect.cn_modes_for_arch (CLAUDE.md §3
    single source of truth for compatibility logic), with an inline
    fallback so the dialog still builds when spellcaster_core fails
    to import (e.g. partial install). Mirrors the pattern used by
    ``_filter_loras_for_arch`` above.

    Filters via cn_is_compatible:
      * "Off" entry (cn_models is None) is always available.
      * Klein / Kontext / Chroma never get a real CN entry.
      * Other arches see only modes whose cn_models dict has their key.
    """
    if not isinstance(modes_dict, dict):
        return []
    try:
        from spellcaster_core.model_detect import cn_modes_for_arch as _cn_for_arch
        return _cn_for_arch(modes_dict, target_arch)
    except Exception:
        # Fallback — keep the same gating semantics as the canonical
        # impl so behaviour stays predictable on partial installs.
        _forbidden = ("flux2klein", "flux_kontext", "chroma")
        out = []
        for key, cfg in modes_dict.items():
            cn_models = cfg.get("cn_models") if isinstance(cfg, dict) else None
            if cn_models is None:
                out.append(key)
                continue
            if not target_arch or target_arch in _forbidden:
                continue
            if isinstance(cn_models, dict) and target_arch in cn_models:
                out.append(key)
        return out


def _filter_loras_for_arch(all_loras, arch):
    """Return LoRAs compatible with ``arch``.

    Three gates, each progressively more permissive:

    1. **Folder-prefix match** — if the LoRA's path starts with one
       of ``ARCH_LORA_PREFIXES[arch]``, it's in. Case-insensitive
       (Linux/Mac ComfyUI reports lowercase paths like ``sdxl/foo``
       but our prefixes use ``SDXL\\``) and slash-agnostic (server
       may emit either ``\\`` or ``/``).
    2. **Root-folder LoRAs** for image arches — a LoRA stored
       directly at ``loras/my_lora.safetensors`` has no subfolder
       and can't strictly be arch-typed. For image arches, let it
       through (minus video markers) so users who keep LoRAs flat
       aren't locked out. The picker's tooltip tells the user the
       LoRA might not match their arch.
    3. **Empty-prefix arches** (``sd15``, ``chroma``) — these arches
       historically had no dedicated LoRA folders. Fall through to
       "every image LoRA except video markers" so users can still
       pick LoRAs from any subfolder.

    In all three gates, filename-level video markers
    (``_looks_like_video_lora``) reject WAN/LTX/SeedVR LoRAs so a
    cross-arch mismatch can't slip through.
    """
    is_image_arch = arch in _IMAGE_ARCHS
    prefixes = ARCH_LORA_PREFIXES.get(arch, [])
    # Pre-lower the prefix list (with both slash variants) so the
    # per-LoRA check is one lowercased startswith() comparison.
    prefix_variants = []
    for p in prefixes:
        pl = p.lower()
        alt = pl.replace("\\", "/") if "\\" in pl else pl.replace("/", "\\")
        prefix_variants.append(pl)
        if alt != pl:
            prefix_variants.append(alt)

    result = []
    for lora in all_loras:
        lora_lower = lora.lower()
        # Filename-level video gate applies to every path for image arches.
        if is_image_arch and _looks_like_video_lora(lora):
            continue
        # Gate 1 — canonical folder prefix match (case-insensitive).
        if prefix_variants and any(
                lora_lower.startswith(p) for p in prefix_variants):
            result.append(lora)
            continue
        # Gate 2 — root-folder LoRA (no subfolder separator). Only
        # admitted for image arches so we don't surface bare video
        # LoRAs in image dialogs — the video-marker check above is
        # the backstop.
        has_separator = ("\\" in lora) or ("/" in lora)
        if is_image_arch and not has_separator:
            result.append(lora)
            continue
        # Gate 3 — empty-prefix image arches: let ANY non-video LoRA
        # through so users with sd15/chroma setups see their library.
        if is_image_arch and not prefixes:
            result.append(lora)
            continue
    return result


# ═══════════════════════════════════════════════════════════════════════════
#  Shared single-slot LoRA picker — inline dialogs
# ═══════════════════════════════════════════════════════════════════════════
# Five secondary dialogs (detail_hallucinate, seedv2r, style_transfer,
# colorize, iclight) each need ONE optional LoRA slot. Before this
# helper they hand-rolled near-identical code with three shared bugs:
# synchronous fetch at construction, bare ``except Exception: pass``
# swallowing server errors so users saw only ``(none)`` with zero
# feedback, and no re-filter when the checkpoint model changed.
# PresetDialog's multi-slot path already handles this correctly;
# this helper gives inline dialogs the same async-fetch + error
# label + model-change re-filter in one call.


class _InlineLoraPicker:
    """State + widgets for a single-slot async LoRA picker.

    Created via :func:`_build_inline_lora_picker`. Exposes ``combo``,
    ``strength_spin``, ``status_label``, ``fetch_btn``, plus:
      - ``get_values()`` → ``(lora_name_or_None, strength)``
      - ``set_active_lora(name)`` — restore session state; silently
        no-ops if ``name`` isn't in the filtered list.

    Caches the full LoRA list so model-change refilter is a pure UI
    operation (no re-fetch).
    """

    def __init__(self, combo, strength_spin, status_label, fetch_btn,
                 server_entry, arch_getter):
        self.combo = combo
        self.strength_spin = strength_spin
        self.status_label = status_label
        self.fetch_btn = fetch_btn
        self._server_entry = server_entry
        self._arch_getter = arch_getter
        self._all_loras = []
        self._filtered = []

    def get_values(self):
        name = self.combo.get_active_id()
        if not name or name == "none":
            return None, float(self.strength_spin.get_value())
        return name, float(self.strength_spin.get_value())

    def set_active_lora(self, name):
        if not name or name == "none":
            self.combo.set_active_id("none")
            return
        if not self.combo.set_active_id(name):
            self.combo.set_active_id("none")

    def refilter(self):
        """Re-apply the arch filter to the cached full list and
        rebuild the combo. Called on model_combo ``changed`` and
        after every successful fetch.
        """
        arch = self._arch_getter() or "sdxl"
        self._filtered = _filter_loras_for_arch(self._all_loras, arch)
        previous = self.combo.get_active_id()
        self.combo.remove_all()
        self.combo.append("none", "(none)")
        for lname in self._filtered:
            short = lname.replace("\\", "/").rsplit("/", 1)[-1]
            self.combo.append(lname, short)
        if previous and previous != "none" and previous in self._filtered:
            self.combo.set_active_id(previous)
        else:
            self.combo.set_active_id("none")
        total = len(self._all_loras)
        shown = len(self._filtered)
        self.fetch_btn.set_label(f"Fetch ({shown}/{total} for {arch})")

    def fetch(self, _btn=None):
        """Async fetch from the current server. Wires status + refilter."""
        server = self._server_entry.get_text().strip()
        _propagate_server_url(server)
        self.fetch_btn.set_label("Fetching...")
        self.status_label.set_markup("")

        def on_done(res):
            self._all_loras = list(res or [])
            self.status_label.set_markup(
                '<span color="green">● Connected</span>')
            self.refilter()

        def on_err(e):
            self._all_loras = []
            self.status_label.set_markup(
                f'<span color="red">⚠ Cannot reach {server} — '
                f'{type(e).__name__}</span>')
            self.refilter()

        _async_fetch(lambda: _fetch_loras(server), on_done, on_err)


def _build_inline_lora_picker(
        parent_box, server_entry, arch_getter, *,
        model_combo=None, initial_strength=0.5,
        min_strength=0.0, max_strength=2.0,
        expander_label="▸ LoRA", collapsed=True):
    """Build a single-slot LoRA picker inside a collapsible expander.

    Auto-fetches on the next GTK idle tick so users see the list
    without clicking Fetch. Failure surfaces as a red ⚠ label inside
    the expander — never raises.

    ``model_combo`` (optional Gtk.ComboBoxText): when given, subscribes
    to its ``changed`` signal and re-filters the combo without
    refetching. Arch-switch is a pure UI operation.
    """
    exp = Gtk.Expander(label=expander_label)
    _shrink_on_collapse(exp, None)
    exp.set_expanded(not collapsed)

    box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=4)
    box.set_margin_start(4); box.set_margin_top(4)

    row1 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
    row1.pack_start(Gtk.Label(label="LoRA:"), False, False, 0)
    combo = Gtk.ComboBoxText()
    combo.append("none", "(none)")
    combo.set_active_id("none")
    combo.set_tooltip_text(
        "Optional LoRA to modify the model output. Filtered to the "
        "selected checkpoint architecture; root-folder LoRAs are "
        "always included (their arch can't be inferred). Click "
        "Fetch to refresh from the server.")
    row1.pack_start(combo, True, True, 0)
    fetch_btn = Gtk.Button(label="Fetch")
    fetch_btn.set_tooltip_text(
        "Fetch the LoRA list from the ComfyUI server. Auto-fires on "
        "dialog open; click again to retry if the server was offline "
        "or to pick up newly-installed LoRAs.")
    row1.pack_start(fetch_btn, False, False, 0)
    box.pack_start(row1, False, False, 0)

    row2 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
    row2.pack_start(Gtk.Label(label="Strength:"), False, False, 0)
    strength = Gtk.SpinButton.new_with_range(min_strength, max_strength, 0.05)
    strength.set_digits(2)
    strength.set_value(float(initial_strength))
    strength.set_tooltip_text(
        "LoRA effect strength. 1.0 = full effect, 0.5 = half.")
    row2.pack_start(strength, False, False, 0)
    box.pack_start(row2, False, False, 0)

    status = Gtk.Label(label="")
    status.set_xalign(0)
    status.set_use_markup(True)
    box.pack_start(status, False, False, 0)

    exp.add(box)
    parent_box.pack_start(exp, False, False, 0)
    exp.show_all()

    picker = _InlineLoraPicker(combo, strength, status, fetch_btn,
                               server_entry, arch_getter)
    fetch_btn.connect("clicked", picker.fetch)

    if model_combo is not None:
        model_combo.connect("changed", lambda _c: picker.refilter())

    GLib.idle_add(picker.fetch, None)
    return picker


# ═══════════════════════════════════════════════════════════════════════════
#  HTTP helpers — pure urllib, no pip installs needed
# ═══════════════════════════════════════════════════════════════════════════
# All communication with the ComfyUI server uses Python's built-in urllib,
# avoiding any dependency on requests/aiohttp. This is critical because
# GIMP 3 plugins run in a restricted Python environment where pip-installed
# packages may not be available.
#
# Model/LoRA discovery: Each _fetch_* function queries ComfyUI's /object_info
# endpoint for a specific node type, extracting the list of available models
# from that node's input schema. This is how the plugin discovers what
# checkpoints, LoRAs, and other models are installed on the server.

def _fetch_loras(server):
    """Fetch available LoRA names from ComfyUI server."""
    try:
        info = _api_get(server, "/object_info/LoraLoader")
        return info["LoraLoader"]["input"]["required"]["lora_name"][0]
    except Exception:
        return []


def _fetch_wan_ipadapter_models(server):
    """Fetch available IPAdapterWANLoader model names from ComfyUI server.

    Returns a list (possibly empty) of filenames known to the server's
    IPAdapterWANLoader node. Used to decide whether the Face Identity Lock
    block in the Wan i2v workflow should be built or silently skipped.
    """
    try:
        info = _api_get(server, "/object_info/IPAdapterWANLoader")
        return info["IPAdapterWANLoader"]["input"]["required"]["ipadapter"][0]
    except Exception:
        return []


_WAN_PATCH_PROBE_CACHE = {}


def _wan_quality_patches_available(server):
    """Probe the server for optional Wan 2.2 quality + speed patches.

    Returns a dict with four bool keys:
      - slg       — SkipLayerGuidanceSD3, core ComfyUI (present on any
                    reasonably-recent server; cleaner motion during CFG).
      - nag       — WanVideoNAG, ships with Kijai's WanVideoWrapper pack.
                    Wraps each branch's attention with the negative
                    conditioning for sharper motion and less drift.
      - sage      — PatchSageAttentionKJ, ships with ComfyUI-KJNodes.
                    Rewires attention to use the SageAttention kernel —
                    50-100% sampler speedup on RTX 40/50xx, neutral
                    quality.
      - cfg_zero  — CFGZeroStar, core ComfyUI on recent builds. Sets
                    CFG=0 for the first sampling step to reduce
                    burn-in artifacts. Small quality win at zero cost.

    Cached per-server so we don't hammer /object_info on every tool run.
    Imports of the Wan 2.2 quality patches are based on xb1n0ry's WAN 2.2
    I2V workflow (github.com/xb1n0ry/Comfy-Workflows).
    """
    if server in _WAN_PATCH_PROBE_CACHE:
        return _WAN_PATCH_PROBE_CACHE[server]
    result = {"slg": False, "nag": False, "sage": False, "cfg_zero": False}
    probes = [
        ("slg",      "/object_info/SkipLayerGuidanceSD3"),
        ("nag",      "/object_info/WanVideoNAG"),
        ("sage",     "/object_info/PatchSageAttentionKJ"),
        ("cfg_zero", "/object_info/CFGZeroStar"),
    ]
    for key, path in probes:
        try:
            _api_get(server, path)
            result[key] = True
        except Exception:
            pass
    _WAN_PATCH_PROBE_CACHE[server] = result
    return result

_LTX_PATCH_PROBE_CACHE = {}


def _ltx_quality_patches_available(server):
    """Probe the server for optional LTX 2.3 quality + speed patches.

    Returns a dict with two bool keys:
      - sage      — PatchSageAttentionKJ (ComfyUI-KJNodes). 50-100%
                    sampler speedup on RTX 40/50xx; neutral quality.
      - cfg_zero  — CFGZeroStar, core ComfyUI on recent builds. Sets
                    CFG=0 for the first sampling step; small quality
                    win at zero cost. LTX distilled mode skips this
                    automatically since its cfg=1.0.

    TeaCache, SLG, and NAG do NOT apply to LTX (different sampler
    path — LTXVBaseSampler / STGGuider instead of Wan's
    KSamplerAdvanced). See CLAUDE.md §16.3 for the LTX canon.

    Cached per-server so we don't hammer /object_info on every tool
    run.
    """
    if server in _LTX_PATCH_PROBE_CACHE:
        return _LTX_PATCH_PROBE_CACHE[server]
    result = {"sage": False, "cfg_zero": False}
    probes = [
        ("sage",     "/object_info/PatchSageAttentionKJ"),
        ("cfg_zero", "/object_info/CFGZeroStar"),
    ]
    for key, path in probes:
        try:
            _api_get(server, path)
            result[key] = True
        except Exception:
            pass
    _LTX_PATCH_PROBE_CACHE[server] = result
    return result


