# ── Architecture-aware CFG override ──────────────────────────────────
# Klein/Flux2 models need CFG=1.0. Many presets embed SDXL-tuned CFG
# values (3.0-7.0) which deepfry distilled models.  This function
# fixes the preset before any workflow builder sees it.
_CFG_OVERRIDE = {"flux2klein": 1.0, "chroma": 1.0}

def _fix_preset_cfg(preset):
    """Return a copy of preset with CFG clamped for the architecture."""
    arch = preset.get("arch", "sdxl")
    override = _CFG_OVERRIDE.get(arch)
    if override is not None and preset.get("cfg", 0) > override:
        preset = dict(preset)
        preset["cfg"] = override
    return preset


def _build_img2img(image_filename, preset, prompt_text, negative_text, seed,
                  loras=None, controlnet=None, controlnet_2=None):
    """→ Delegated to v2 builder, with automatic prompt enhancement."""
    arch_key = preset.get("arch", "sdxl")
    preset = _fix_preset_cfg(preset)
    prompt_text, negative_text = _auto_enhance(prompt_text, arch_key, negative_text)
    return build_img2img(image_filename, preset, prompt_text, negative_text, seed,
                         loras=loras, controlnet=controlnet, controlnet_2=controlnet_2,
                         guide_modes=CONTROLNET_GUIDE_MODES)

def _build_inpaint(image_filename, mask_filename, preset, prompt_text, negative_text, seed, loras=None, controlnet=None, controlnet_2=None):
    """→ Delegated to v2 builder, with automatic prompt enhancement."""
    preset = _fix_preset_cfg(preset)
    arch_key = preset.get("arch", "sdxl")
    prompt_text, negative_text = _auto_enhance(prompt_text, arch_key, negative_text,
                                                method="inpaint")
    return build_inpaint(image_filename, mask_filename, preset, prompt_text, negative_text, seed,
                         loras=loras, controlnet=controlnet, controlnet_2=controlnet_2,
                         guide_modes=CONTROLNET_GUIDE_MODES)

def _rembg_post_process(server, filename, subfolder="", folder_type="output"):
    """Run rembg on an already-generated image and return transparent PNG bytes.

    Downloads the image from ComfyUI, uploads it back as input, runs rembg,
    and returns the transparent result bytes. Used by the 'Generate as Mask'
    feature across all image generation tools.

    Returns transparent PNG bytes, or None on failure.
    """
    try:
        # Download the generated image
        img_data = _download_image(server, filename, subfolder, folder_type)
        # Upload as input for rembg
        rembg_input = f"gimp_rembg_{uuid.uuid4().hex[:8]}.png"
        tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
        tmp.write(img_data); tmp.close()
        _upload_image(server, tmp.name, rembg_input)
        os.unlink(tmp.name)
        # Run rembg
        wf = build_rembg(rembg_input)
        results = list(_run_comfyui_workflow(server, wf))
        for fn, sf, ft in results:
            if fn.lower().endswith(".png"):
                return _download_image(server, fn, sf, ft)
    except Exception:
        pass
    return None


def _build_outpaint(image_filename, preset, prompt_text, negative_text, seed,
                    left, top, right, bottom, feathering, loras=None, controlnet=None):
    """→ Delegated to v2 builder, with method='outpaint' enhancement."""
    preset = _fix_preset_cfg(preset)
    arch = preset.get("arch", "sdxl")
    # Outpaint scope: describe what extends BEYOND the canvas, not the
    # existing image. Profile caps at 40-80 words, reinforces "match
    # the original's palette / lighting so the seam is invisible".
    prompt_text, negative_text = _auto_enhance(prompt_text, arch, negative_text,
                                                method="outpaint")
    return build_outpaint(image_filename, preset, prompt_text, negative_text, seed,
                          left, top, right, bottom, feathering, loras=loras, controlnet=controlnet,
                          guide_modes=CONTROLNET_GUIDE_MODES)

def _build_style_transfer(target_filename, style_ref_filename, preset,
                           prompt_text, negative_text, seed,
                           ipadapter_preset="PLUS (high strength)",
                           weight=0.8, denoise=0.6,
                           controlnet=None, controlnet_2=None, loras=None):
    """→ Delegated to v2 builder, with method='style_transfer' enhancement."""
    preset = _fix_preset_cfg(preset)
    arch = preset.get("arch", "sdxl")
    # Style transfer: prompt describes the OUTPUT (scene default is fine
    # — style_transfer method is registered as empty overlay).
    prompt_text, negative_text = _auto_enhance(prompt_text, arch, negative_text,
                                                method="style_transfer")
    return build_style_transfer(target_filename, style_ref_filename, preset,
                                prompt_text, negative_text, seed,
                                ipadapter_preset=ipadapter_preset,
                                weight=weight, denoise=denoise,
                                controlnet=controlnet, controlnet_2=controlnet_2,
                                guide_modes=CONTROLNET_GUIDE_MODES,
                                loras=loras)

def _build_detail_hallucinate(image_filename, upscale_model, preset, prompt_text, negative_text,
                              seed, denoise, cfg, steps=None, scale_factor=2.0,
                              controlnet=None, controlnet_2=None, loras=None,
                              orig_width=512, orig_height=512):
    """→ Delegated to v2 builder, with method='hallucinate' enhancement."""
    preset = _fix_preset_cfg(preset)
    arch = preset.get("arch", "sdxl")
    if arch in _CFG_OVERRIDE and cfg > _CFG_OVERRIDE[arch]:
        cfg = _CFG_OVERRIDE[arch]
    # Detail hallucinate adds texture/detail without inventing new
    # subjects — method='hallucinate' inherits from 'refine'.
    prompt_text, negative_text = _auto_enhance(prompt_text, arch, negative_text,
                                                method="hallucinate")
    return build_detail_hallucinate(image_filename, upscale_model, preset, prompt_text, negative_text,
                                    seed, denoise, cfg, steps=steps,
                                    upscale_factor=scale_factor,
                                    controlnet=controlnet, controlnet_2=controlnet_2,
                                    guide_modes=CONTROLNET_GUIDE_MODES,
                                    loras=loras)

def _build_seedv2r(image_filename, upscale_model, preset, prompt_text, negative_text,
                    seed, denoise, cfg, steps, scale_factor, orig_width, orig_height,
                    controlnet=None, controlnet_2=None, loras=None):
    """→ Delegated to v2 builder, with method='refine' enhancement."""
    preset = _fix_preset_cfg(preset)
    arch = preset.get("arch", "sdxl")
    if arch in _CFG_OVERRIDE and cfg > _CFG_OVERRIDE[arch]:
        cfg = _CFG_OVERRIDE[arch]
    # Controllable upscale — prompt guides detail synthesis, not new
    # subjects. Treat as refine scope.
    prompt_text, negative_text = _auto_enhance(prompt_text, arch, negative_text,
                                                method="refine")
    return build_seedv2r(image_filename, upscale_model, preset, prompt_text, negative_text,
                         seed, denoise, cfg, steps, scale_factor, orig_width, orig_height,
                         controlnet=controlnet, controlnet_2=controlnet_2,
                         guide_modes=CONTROLNET_GUIDE_MODES,
                         loras=loras)

def _build_faceid_img2img(target_filename, face_ref_filename, preset_key,
                           prompt_text, negative_text, seed,
                           faceid_preset="FACEID PLUS V2",
                           lora_strength=0.6, weight=0.85, weight_v2=1.0,
                           denoise=None, steps=None, cfg=None,
                           turbo_loras=None, turbo=False):
    """→ Delegated to v2 builder (resolves preset_key → preset dict)."""
    preset = FACEID_PRESETS[preset_key]
    # turbo_loras are just LoRAs injected before the FaceID loader
    loras = turbo_loras if turbo and turbo_loras else None
    return build_faceid_img2img(target_filename, face_ref_filename, preset,
                                prompt_text, negative_text, seed,
                                faceid_preset=faceid_preset,
                                lora_strength=lora_strength, weight=weight,
                                weight_v2=weight_v2,
                                denoise=denoise, steps=steps, cfg=cfg,
                                loras=loras)

def _is_flux2_model(model_name):
    """Return True if model_name is a Flux.2 (Klein) model requiring PuLID-Flux2 nodes."""
    lower = model_name.lower()
    return "flux2" in lower or "flux-2" in lower or "klein" in lower

def _build_pulid_flux(target_filename, face_ref_filename,
                      prompt_text, negative_text, seed,
                      flux_model="Flux\\FLUX1 Dev fp8.safetensors",
                      pulid_model="pulid_flux_v0.9.1.safetensors",
                      strength=0.9, steps=20, guidance=3.5,
                      denoise=0.65, width=1024, height=1024,
                      turbo_loras=None, turbo=False):
    """→ Delegated to v2 builder."""
    loras = turbo_loras if turbo and turbo_loras else None
    return build_pulid_flux(target_filename, face_ref_filename,
                            prompt_text, negative_text, seed,
                            flux_model=flux_model, pulid_model=pulid_model,
                            strength=strength, steps=steps, guidance=guidance,
                            denoise=denoise, width=width, height=height,
                            loras=loras)

def _wan_video_dims(src_w, src_h, target_long=720, align=16):
    """Compute video output dimensions preserving aspect ratio.

    Scales so the longest side is ≈ target_long, then rounds both
    dimensions to the nearest multiple of *align* (VAE requirement).
    Examples:
        1920×1080 → 720×400    (landscape)
        1080×1920 → 400×720    (portrait)
        1024×1024 → 720×720    (square — floored to align)
        832×480   → 832×480    (already ≤720 on long side, kept as-is)
    """
    if src_w <= 0 or src_h <= 0:
        return 832, 480
    long = max(src_w, src_h)
    if long <= target_long:
        # Already small enough — just align
        w = max(align, round(src_w / align) * align)
        h = max(align, round(src_h / align) * align)
        return w, h
    scale = target_long / long
    w = max(align, round(src_w * scale / align) * align)
    h = max(align, round(src_h * scale / align) * align)
    return w, h


