        # ── Prompt (editable, auto-filled from presets) ───────────────
        bx.pack_start(Gtk.Label(label="Prompt (auto-built from presets above, edit freely):"),
                       False, False, 2)
        sw = Gtk.ScrolledWindow(); sw.set_min_content_height(90)
        prompt_tv = Gtk.TextView(); prompt_tv.set_wrap_mode(Gtk.WrapMode.WORD_CHAR)
        prompt_tv.set_tooltip_text("Full prompt sent to Klein. Auto-generated from your preset\n"
                                    "selections above — feel free to edit, add details, or rewrite entirely")
        sw.add(prompt_tv); bx.pack_start(sw, True, True, 0)

        # ── Auto-build prompt from combos ─────────────────────────────
        def _rebuild_prompt(*_args):
            char_key = char_combo.get_active_id() or "Single character"
            pose_key = pose_combo.get_active_id() or "Standing relaxed"
            pos_key = pos_combo.get_active_id() or "Keep current position"
            cam_key = cam_combo.get_active_id() or "Keep current angle"
            multi_key = multi_combo.get_active_id() or "(none)"
            style_key = style_combo.get_active_id() or "Keep original style"

            parts = []
            # Subject
            char_txt = CHAR_TEMPLATES.get(char_key, "a person")
            if char_txt: parts.append(char_txt)
            # Pose
            pose_txt = POSE_PRESETS.get(pose_key, "standing relaxed")
            if pose_txt: parts.append(pose_txt)
            # Multi-char interaction
            if multi_key != "(none)" and multi_key in MULTI_CHAR_PRESETS:
                parts.append(MULTI_CHAR_PRESETS[multi_key])
            # Position
            pos_txt = POSITION_PRESETS.get(pos_key, "")
            if pos_txt: parts.append(pos_txt)
            # Camera — major viewpoint changes need high denoise to override
            # ReferenceLatent which otherwise locks the original composition.
            cam_txt = CAMERA_PRESETS.get(cam_key, "")
            if cam_txt:
                parts.append(cam_txt)
                # Any camera preset that radically changes the viewpoint
                _radical_cam = ("orbit" in cam_key.lower() or
                                "bird" in cam_key.lower() or
                                "worm" in cam_key.lower() or
                                "behind" in cam_key.lower() or
                                "overhead" in cam_key.lower() or
                                "extreme" in cam_key.lower() or
                                "low angle" in cam_key.lower() or
                                "high angle" in cam_key.lower() or
                                "dutch" in cam_key.lower())
                if _radical_cam:
                    denoise_sp.set_value(max(denoise_sp.get_value(), 0.95))
            # Style
            style_txt = STYLE_PRESETS.get(style_key, "")
            if style_txt: parts.append(style_txt)
            # Always add quality tail
            parts.append("high quality, detailed, masterful composition")

            prompt_tv.get_buffer().set_text(", ".join(parts))

        for combo in [char_combo, pose_combo, pos_combo, cam_combo, multi_combo, style_combo]:
            combo.connect("changed", _rebuild_prompt)
        _rebuild_prompt()  # initial fill

        # ── User Presets (save/load) ──────────────────────────────────
        bx.pack_start(Gtk.Separator(), False, False, 4)
        def _collect_user_preset():
            pbuf = prompt_tv.get_buffer()
            return {
                "klein_model": klein_combo.get_active_id() or "Klein 9B",
                "character": char_combo.get_active_id() or "Single character",
                "pose": pose_combo.get_active_id() or "Standing relaxed",
                "position": pos_combo.get_active_id() or "Keep current position",
                "camera": cam_combo.get_active_id() or "Keep current angle",
                "interaction": multi_combo.get_active_id() or "(none)",
                "style": style_combo.get_active_id() or "Keep original style",
                "denoise": denoise_sp.get_value(),
                "steps": int(steps_sp.get_value()),
                "seed": int(seed_sp.get_value()),
                "runs": int(runs_sp.get_value()),
                "prompt": pbuf.get_text(pbuf.get_start_iter(), pbuf.get_end_iter(), False),
            }
        def _apply_user_preset(p):
            if "klein_model" in p: klein_combo.set_active_id(p["klein_model"])
            if "character" in p: char_combo.set_active_id(p["character"])
            if "pose" in p: pose_combo.set_active_id(p["pose"])
            if "position" in p: pos_combo.set_active_id(p["position"])
            if "camera" in p: cam_combo.set_active_id(p["camera"])
            if "interaction" in p: multi_combo.set_active_id(p["interaction"])
            if "style" in p: style_combo.set_active_id(p["style"])
            if "denoise" in p: denoise_sp.set_value(p["denoise"])
            if "steps" in p: steps_sp.set_value(p["steps"])
            if "seed" in p: seed_sp.set_value(p["seed"])
            if "runs" in p: runs_sp.set_value(p["runs"])
            if "prompt" in p: prompt_tv.get_buffer().set_text(p["prompt"])
        dlg._collect_user_preset = _collect_user_preset
        dlg._apply_user_preset = _apply_user_preset
        _add_preset_ui(dlg, bx, "klein_repose")
        _last = _SESSION.get("klein_repose")
        if _last: _apply_user_preset(_last)

        bx.show_all()
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())

        # Collect values
        _SESSION["klein_repose"] = _collect_user_preset(); _save_session()
        srv = srv_e.get_text().strip(); _propagate_server_url(srv)
        klein_key = klein_combo.get_active_id() or "Klein 9B"
        pbuf = prompt_tv.get_buffer()
        prompt = pbuf.get_text(pbuf.get_start_iter(), pbuf.get_end_iter(), False)
        denoise = denoise_sp.get_value()
        steps = int(steps_sp.get_value())
        runs = int(runs_sp.get_value())
        base_seed = int(seed_sp.get_value())
        if base_seed < 0:
            base_seed = random.randint(0, 2**32 - 1)
        dlg.destroy()

        try:
            _update_spinner_status("Klein Re-poser: exporting image...")
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_repose_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)

            # Repose preserves the subject and changes only the pose — treat
            # as refine scope so the LLM doesn't invent new characters.
            prompt, _ = _auto_enhance(prompt, "flux2klein", method="refine")

            for run_i in range(runs):
                seed = base_seed if runs == 1 else random.randint(0, 2**32 - 1)
                label = f"Klein Re-poser run {run_i+1}/{runs}" if runs > 1 else "Klein Re-poser"
                wf = build_klein_repose(
                    uname, klein_key, prompt, seed,
                    steps=steps, denoise=denoise, guidance=1.0,
                    klein_models=KLEIN_MODELS,
                )

                results = _run_with_spinner(f"{label}: generating new pose...",
                                             lambda: list(_run_comfyui_workflow(srv, wf, timeout=300)))
                for i, (fn, sf, ft) in enumerate(results):
                    lbl = f"Klein Repose run {run_i+1} #{i+1}" if runs > 1 else f"Klein Repose #{i+1}"
                    _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft), lbl, False)
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Klein Re-poser Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

