    # ── Klein Color Match (ColorMatchV2, no diffusion) ───────────────
    def _run_klein_color_match(self, procedure, run_mode, image, drawables, config, data):
        """Klein Color Match: ColorMatchV2 to a reference image (no diffusion)."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        srv_probe = COMFYUI_DEFAULT_URL
        try:
            _api_get(srv_probe, "/object_info/ColorMatchV2")
        except Exception:
            Gimp.message(
                "comfyui-kjnodes (ColorMatchV2) is not installed.\n\n"
                "Install via ComfyUI Manager (search 'kjnodes'), then restart.\n\n"
                f"Server checked: {srv_probe}")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        GimpUi.init("spellcaster")
        dlg = Gtk.Dialog(title="Spellcaster — Klein Color Match")
        dlg.set_default_size(500, -1)
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Match", Gtk.ResponseType.OK)
        _style_dialog_buttons(dlg)
        bx = dlg.get_content_area()
        bx.set_spacing(8); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(12); bx.set_margin_bottom(12)
        _hdr = _make_branded_header()
        if _hdr: bx.pack_start(_hdr, False, False, 0)
        # Server
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        se = Gtk.Entry(); se.set_text(COMFYUI_DEFAULT_URL); se.set_hexpand(True)
        hb.pack_start(se, True, True, 0); bx.pack_start(hb, False, False, 0)
        se.set_tooltip_text("ComfyUI server URL (e.g. http://192.168.x.x:8188)")
        # Reference file picker
        bx.pack_start(Gtk.Label(label="Reference image (color source):", xalign=0), False, False, 0)
        hf = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        ref_entry = Gtk.Entry()
        ref_entry.set_placeholder_text("Browse for a reference image...")
        ref_entry.set_hexpand(True)
        ref_entry.set_tooltip_text("The reference whose palette/grade will be transferred.")
        hf.pack_start(ref_entry, True, True, 0)
        def _browse_ref(*_a):
            fc = Gtk.FileChooserDialog(title="Select Reference Image",
                                       action=Gtk.FileChooserAction.OPEN)
            fc.add_button("_Cancel", Gtk.ResponseType.CANCEL)
            fc.add_button("_Open", Gtk.ResponseType.OK)
            ff = Gtk.FileFilter(); ff.set_name("Images")
            for ext in ["*.png", "*.jpg", "*.jpeg", "*.webp"]: ff.add_pattern(ext)
            fc.add_filter(ff)
            if fc.run() == Gtk.ResponseType.OK:
                ref_entry.set_text(fc.get_filename())
            fc.destroy()
        browse_btn = Gtk.Button(label="Browse...")
        browse_btn.connect("clicked", _browse_ref)
        hf.pack_start(browse_btn, False, False, 0)
        bx.pack_start(hf, False, False, 0)
        # Method
        bx.pack_start(Gtk.Label(label="Method:", xalign=0), False, False, 0)
        method_combo = Gtk.ComboBoxText()
        for m in ("mkl", "histogram", "reinhard"):
            method_combo.append(m, m)
        method_combo.set_active_id("mkl")
        method_combo.set_tooltip_text(
            "mkl = Monge-Kantorovich (best, default)\n"
            "histogram = channel histogram matching\n"
            "reinhard = global mean/std transfer")
        bx.pack_start(method_combo, False, False, 0)
        # Strength
        hs = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hs.pack_start(Gtk.Label(label="Strength:"), False, False, 0)
        strength_sp = Gtk.SpinButton.new_with_range(0.0, 1.0, 0.05); strength_sp.set_value(0.95)
        strength_sp.set_digits(2)
        strength_sp.set_tooltip_text("Blend factor. 1.0 = full transfer, 0.5 = half-way.")
        hs.pack_start(strength_sp, False, False, 0)
        bx.pack_start(hs, False, False, 0)
        bx.show_all()
        last = _SESSION.get("klein_color_match")
        if last:
            if "ref_file" in last: ref_entry.set_text(last["ref_file"])
            if "method" in last: method_combo.set_active_id(last["method"])
            if "strength" in last: strength_sp.set_value(last["strength"])
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        srv = se.get_text().strip(); _propagate_server_url(srv)
        ref_file = ref_entry.get_text().strip()
        method = method_combo.get_active_id() or "mkl"
        strength = strength_sp.get_value()
        _SESSION["klein_color_match"] = {
            "ref_file": ref_file, "method": method, "strength": strength,
        }
        _save_session()
        dlg.destroy()
        if not ref_file:
            Gimp.message("Select a reference image.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        try:
            _update_spinner_status("Klein Color Match: uploading...")
            tmp = _export_image_to_tmp(image)
            tgt_name = f"gimp_klcm_tgt_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, tgt_name); os.unlink(tmp)
            ref_name = f"gimp_klcm_ref_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, ref_file, ref_name)
            wf = build_klein_color_match(tgt_name, ref_name, method=method, strength=strength)
            _wf = wf
            results = _run_with_spinner("Klein Color Match: matching...",
                                         lambda: list(_run_comfyui_workflow(srv, _wf, timeout=120)))
            for i, (fn, sf, ft) in enumerate(results):
                _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft),
                                 f"Color Match ({method}) #{i+1}", False)
            _LAST_PROCEDURE["name"] = "spellcaster-klein-color-match"
            _LAST_PROCEDURE["session_key"] = "klein_color_match"
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Klein Color Match Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    # ── Klein Virtual Try-On (face + outfit + optional bg + pose) ────
    def _run_klein_virtual_tryon(self, procedure, run_mode, image, drawables, config, data):
        """Klein Virtual Try-On: 4-reference photoshoot composition.

        NOTE: the current canvas is used as the FACE reference (primary
        character identity). The outfit picker is required; bg/pose are
        optional. Klein synthesises all refs through chained ReferenceLatent.
        """
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        GimpUi.init("spellcaster")
        dlg = Gtk.Dialog(title="Spellcaster — Klein Virtual Try-On")
        dlg.set_default_size(560, -1)
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Generate", Gtk.ResponseType.OK)
        _style_dialog_buttons(dlg)
        bx = dlg.get_content_area()
        bx.set_spacing(8); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(12); bx.set_margin_bottom(12)
        _hdr = _make_branded_header()
        if _hdr: bx.pack_start(_hdr, False, False, 0)
        bx.pack_start(Gtk.Label(
            label="Canvas = face/identity reference (ref #1).\n"
                  "Pick an outfit, and optionally a background and pose."),
            False, False, 4)
        # Server
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        se = Gtk.Entry(); se.set_text(COMFYUI_DEFAULT_URL); se.set_hexpand(True)
        hb.pack_start(se, True, True, 0); bx.pack_start(hb, False, False, 0)
        se.set_tooltip_text("ComfyUI server URL (e.g. http://192.168.x.x:8188)")
        # Klein model
        bx.pack_start(Gtk.Label(label="Klein Model:", xalign=0), False, False, 0)
        klein_combo = Gtk.ComboBoxText()
        for k in KLEIN_MODELS: klein_combo.append(k, k)
        klein_combo.set_active_id("Klein 9B")
        bx.pack_start(klein_combo, False, False, 0)

        def _file_row(label_text, placeholder, tooltip):
            bx.pack_start(Gtk.Label(label=label_text, xalign=0), False, False, 0)
            hf = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
            entry = Gtk.Entry()
            entry.set_placeholder_text(placeholder)
            entry.set_hexpand(True)
            entry.set_tooltip_text(tooltip)
            hf.pack_start(entry, True, True, 0)
            def _browse(*_a):
                fc = Gtk.FileChooserDialog(title=f"Select {label_text}",
                                           action=Gtk.FileChooserAction.OPEN)
                fc.add_button("_Cancel", Gtk.ResponseType.CANCEL)
                fc.add_button("_Open", Gtk.ResponseType.OK)
                ff = Gtk.FileFilter(); ff.set_name("Images")
                for ext in ["*.png", "*.jpg", "*.jpeg", "*.webp"]: ff.add_pattern(ext)
                fc.add_filter(ff)
                if fc.run() == Gtk.ResponseType.OK:
                    entry.set_text(fc.get_filename())
                fc.destroy()
            btn = Gtk.Button(label="Browse...")
            btn.connect("clicked", _browse)
            hf.pack_start(btn, False, False, 0)
            bx.pack_start(hf, False, False, 0)
            return entry

        outfit_entry = _file_row("Outfit reference (required):",
                                  "headless body / outfit photo...",
                                  "Wardrobe reference. A headless body works best.")
        bg_entry = _file_row("Background (optional):",
                              "location / environment photo...",
                              "Optional background reference.")
        pose_entry = _file_row("Pose reference (optional):",
                                "DAZ render / pose photo...",
                                "Optional pose reference.")

        # Prompt
        bx.pack_start(Gtk.Label(label="Scene description:", xalign=0), False, False, 0)
        prompt_tv = Gtk.TextView(); prompt_tv.set_wrap_mode(Gtk.WrapMode.WORD_CHAR)
        prompt_tv.set_size_request(-1, 60)
        prompt_tv.set_tooltip_text("Describe the desired composition.")
        sw = Gtk.ScrolledWindow(); sw.set_min_content_height(60); sw.add(prompt_tv)
        bx.pack_start(sw, False, False, 0)
        # Parameters
        grid = Gtk.Grid(column_spacing=8, row_spacing=4)
        grid.attach(Gtk.Label(label="Steps:", xalign=1), 0, 0, 1, 1)
        steps_sp = Gtk.SpinButton.new_with_range(1, 50, 1); steps_sp.set_value(4)
        grid.attach(steps_sp, 1, 0, 1, 1)
        grid.attach(Gtk.Label(label="Denoise:", xalign=1), 2, 0, 1, 1)
        denoise_sp = Gtk.SpinButton.new_with_range(0.1, 1.0, 0.05); denoise_sp.set_value(1.0)
        denoise_sp.set_digits(2)
        grid.attach(denoise_sp, 3, 0, 1, 1)
        grid.attach(Gtk.Label(label="Guidance:", xalign=1), 0, 1, 1, 1)
        guidance_sp = Gtk.SpinButton.new_with_range(0.5, 10.0, 0.5); guidance_sp.set_value(1.0)
        guidance_sp.set_digits(1)
        grid.attach(guidance_sp, 1, 1, 1, 1)
        grid.attach(Gtk.Label(label="Seed:", xalign=1), 2, 1, 1, 1)
        seed_sp = Gtk.SpinButton.new_with_range(-1, 2**32-1, 1); seed_sp.set_value(-1)
        grid.attach(seed_sp, 3, 1, 1, 1)
        bx.pack_start(grid, False, False, 0)
        # Enhance toggle
        enhance_cb = Gtk.CheckButton(label="Auto-enhance prompt (LLM)")
        enhance_cb.set_active(False)
        bx.pack_start(enhance_cb, False, False, 0)
        _add_runs_spinner(dlg, bx)
        bx.show_all()
        last = _SESSION.get("klein_virtual_tryon")
        if last:
            if "klein_model" in last: klein_combo.set_active_id(last["klein_model"])
            if "outfit_file" in last: outfit_entry.set_text(last["outfit_file"])
            if "bg_file" in last: bg_entry.set_text(last["bg_file"])
            if "pose_file" in last: pose_entry.set_text(last["pose_file"])
            if "prompt" in last: prompt_tv.get_buffer().set_text(last["prompt"])
            if "steps" in last: steps_sp.set_value(last["steps"])
            if "denoise" in last: denoise_sp.set_value(last["denoise"])
            if "guidance" in last: guidance_sp.set_value(last["guidance"])
            if "enhance" in last: enhance_cb.set_active(bool(last["enhance"]))
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        srv = se.get_text().strip(); _propagate_server_url(srv)
        klein_key = klein_combo.get_active_id() or "Klein 9B"
        outfit_file = outfit_entry.get_text().strip()
        bg_file = bg_entry.get_text().strip() or None
        pose_file = pose_entry.get_text().strip() or None
        pbuf = prompt_tv.get_buffer()
        prompt = pbuf.get_text(pbuf.get_start_iter(), pbuf.get_end_iter(), False)
        steps = int(steps_sp.get_value())
        denoise = denoise_sp.get_value()
        guidance = guidance_sp.get_value()
        base_seed = int(seed_sp.get_value())
        if base_seed < 0: base_seed = random.randint(0, 2**32 - 1)
        enhance = enhance_cb.get_active()
        runs = int(dlg._runs_spin.get_value())
        _SESSION["klein_virtual_tryon"] = {
            "klein_model": klein_key,
            "outfit_file": outfit_file,
            "bg_file": bg_file or "", "pose_file": pose_file or "",
            "prompt": prompt, "steps": steps, "denoise": denoise,
            "guidance": guidance, "enhance": enhance,
        }
        _save_session()
        dlg.destroy()
        if not outfit_file:
            Gimp.message("Outfit reference is required.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        if not prompt.strip():
            Gimp.message("Type a scene description.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        try:
            _update_spinner_status("Klein Try-On: exporting face (canvas)...")
            tmp = _export_image_to_tmp(image)
            face_name = f"gimp_tryon_face_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, face_name); os.unlink(tmp)
            outfit_name = f"gimp_tryon_outfit_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, outfit_file, outfit_name)
            bg_name = None
            if bg_file:
                bg_name = f"gimp_tryon_bg_{uuid.uuid4().hex[:8]}.png"
                _upload_image(srv, bg_file, bg_name)
            pose_name = None
            if pose_file:
                pose_name = f"gimp_tryon_pose_{uuid.uuid4().hex[:8]}.png"
                _upload_image(srv, pose_file, pose_name)
            _prompt = prompt
            if enhance:
                _prompt, _ = _auto_enhance(prompt, "flux2klein",
                                            method="klein_virtual_tryon")
            for run_i in range(runs):
                seed = base_seed if runs == 1 else random.randint(0, 2**32 - 1)
                wf = build_klein_virtual_tryon(
                    face_name, outfit_name, _prompt, seed,
                    bg_filename=bg_name, pose_filename=pose_name,
                    klein_model_key=klein_key,
                    steps=steps, denoise=denoise, guidance=guidance,
                )
                label = f"Klein Try-On run {run_i+1}/{runs}" if runs > 1 else "Klein Try-On"
                _wf = wf
                results = _run_with_spinner(f"{label}: processing...",
                                             lambda: list(_run_comfyui_workflow(srv, _wf, timeout=600)))
                for i, (fn, sf, ft) in enumerate(results):
                    lbl = f"{label} #{i+1}"
                    _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft), lbl, False)
            _LAST_PROCEDURE["name"] = "spellcaster-klein-virtual-tryon"
            _LAST_PROCEDURE["session_key"] = "klein_virtual_tryon"
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Klein Virtual Try-On Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    # ── Generate Anything (all models) ────────────────────────────────
    def _run_generate_anything(self, procedure, run_mode, image, drawables, config, data):
        """Generate Anything: create any object as a transparent layer with ANY model."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        GimpUi.init("spellcaster")
        _apply_spellcaster_theme()
        dlg = Gtk.Dialog(title="Spellcaster — Generate Anything")
        dlg.set_default_size(560, -1)
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Generate", Gtk.ResponseType.OK)
        dlg.set_default_response(Gtk.ResponseType.OK)
        _style_dialog_buttons(dlg)
        bx = dlg.get_content_area()
        bx.set_spacing(8); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(12); bx.set_margin_bottom(12)
        _hdr = _make_branded_header()
        if _hdr:
            bx.pack_start(_hdr, False, False, 0)
        # Server
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        se = Gtk.Entry(); se.set_text(COMFYUI_DEFAULT_URL); se.set_hexpand(True)
        hb.pack_start(se, True, True, 0); bx.pack_start(hb, False, False, 0)
        se.set_tooltip_text("ComfyUI server URL (e.g. http://192.168.x.x:8188)")
        # Model selector — ALL models
        bx.pack_start(Gtk.Label(label="Model:", xalign=0), False, False, 0)
        model_combo = Gtk.ComboBoxText()
        model_combo.set_tooltip_text(
            "Any model works. Klein/Flux use scene reference for lighting.\n"
            "SDXL/SD15 use quality tokens. Each model is auto-optimized.")
        for i, p in enumerate(MODEL_PRESETS):
            arch = p.get("arch", "")
            # Add diamond indicators per architecture
            if arch == "flux2klein":
                prefix = "◇ "
            elif arch == "flux_kontext":
                prefix = "◆ "
            elif arch in ("flux1dev",):
                prefix = "◈ "
            else:
                prefix = ""
            model_combo.append(str(i), f"{prefix}{p['label']}")
        _fav = _load_config().get("favourite_model", -1)
        if 0 <= _fav < len(MODEL_PRESETS):
            model_combo.set_active_id(str(_fav))
        if model_combo.get_active() < 0:
            model_combo.set_active(0)
        bx.pack_start(model_combo, False, False, 0)
        # Object description
        bx.pack_start(Gtk.Separator(), False, False, 4)
        bx.pack_start(Gtk.Label(label="What to Generate:", xalign=0), False, False, 0)
        prompt_tv = Gtk.TextView()
        prompt_tv.set_wrap_mode(Gtk.WrapMode.WORD_CHAR)
        prompt_tv.set_tooltip_text(
            "Describe what to generate. The AI will create it on a white\n"
            "background and cut it out as a transparent layer.\n\n"
            "  'a red sports car, side view'\n"
            "  'a tabby cat sitting'\n"
            "  'a medieval sword with ornate handle'\n"
            "  'a woman in a blue dress, full body'")
        sw = Gtk.ScrolledWindow(); sw.set_min_content_height(70); sw.add(prompt_tv)
        bx.pack_start(sw, False, False, 0)
        # Negative prompt
        bx.pack_start(Gtk.Label(label="Negative (optional):", xalign=0), False, False, 0)
        neg_entry = Gtk.Entry()
        neg_entry.set_text("blurry, low quality, deformed")
        neg_entry.set_tooltip_text("What to avoid. Ignored by Flux/Klein models.")
        bx.pack_start(neg_entry, False, False, 0)
        # Info
        info = Gtk.Label()
        info.set_markup(
            '<span size="small" color="#A88B7F">'
            'Your canvas provides lighting/style reference for Flux/Klein models.\n'
            'Result: transparent PNG layer — position and scale freely.\n'
            '◇ = Flux 2 Klein  ◆ = Flux Kontext  ◈ = Flux Dev</span>')
        info.set_line_wrap(True)
        bx.pack_start(info, False, False, 4)
        # Seed
        seed_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        seed_row.pack_start(Gtk.Label(label="Seed (-1=rand):"), False, False, 0)
        seed_spin = Gtk.SpinButton.new_with_range(-1, 2**31, 1); seed_spin.set_value(-1)
        seed_row.pack_start(seed_spin, False, False, 0)
        seed_spin.set_tooltip_text("ComfyUI server URL (e.g. http://192.168.x.x:8188)")
        bx.pack_start(seed_row, False, False, 0)
        # Runs
        _add_runs_spinner(dlg, bx)
        bx.show_all()
        # Recall
        last = _SESSION.get("generate_anything")
        if last:
            if "model_idx" in last:
                model_combo.set_active_id(str(last["model_idx"]))
            if "prompt" in last:
                prompt_tv.get_buffer().set_text(last["prompt"])
            if "negative" in last:
                neg_entry.set_text(last["negative"])
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        srv = se.get_text().strip(); _propagate_server_url(srv)
        idx = int(model_combo.get_active_id() or "0")
        preset = dict(MODEL_PRESETS[idx])
        preset["width"] = image.get_width()
        preset["height"] = image.get_height()
        buf = prompt_tv.get_buffer()
        prompt = buf.get_text(buf.get_start_iter(), buf.get_end_iter(), False)
        negative = neg_entry.get_text().strip()
        seed = int(seed_spin.get_value())
        if seed < 0:
            seed = random.randint(0, 2**32 - 1)
        runs = int(dlg._runs_spin.get_value())
        _SESSION["generate_anything"] = {
            "model_idx": idx, "prompt": prompt, "negative": negative,
        }
        _save_session()
        dlg.destroy()
        if not prompt.strip():
            Gimp.message("Please describe what to generate.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        try:
            _update_spinner_status("Generate Anything: preparing...")
            # Upload scene as reference (for Klein/Flux lighting matching)
            scene_uname = None
            arch_key = preset.get("arch", "sdxl")
            if arch_key in ("flux2klein", "flux1dev"):
                tmp = _export_image_to_tmp(image)
                scene_uname = f"gimp_scene_{uuid.uuid4().hex[:8]}.png"
                _upload_image(srv, tmp, scene_uname); os.unlink(tmp)
            # Auto-enhance prompt if enabled
            prompt, negative = _auto_enhance(prompt, arch_key, negative)
            base_seed = seed
            for run_i in range(runs):
                _seed = base_seed if runs == 1 else random.randint(0, 2**32 - 1)
                wf = build_generate_anything(
                    prompt, negative, _seed, preset,
                    scene_filename=scene_uname,
                )
                label = f"run {run_i+1}/{runs}" if runs > 1 else "generating"
                _wf = wf
                results = _run_with_spinner(f"Generate Anything: {label}...",
                                            lambda: list(_run_comfyui_workflow(srv, _wf)))
                # Import the transparent cutout (generated_object), not raw
                for fn, sf, ft in results:
                    if 'object' in fn.lower() or 'rmbg' in fn.lower():
                        _import_result_as_layer(
                            image, _download_image(srv, fn, sf, ft),
                            f"Generated: {prompt[:35]}... #{run_i+1}",
                            keep_size=True)
                        break
                else:
                    if results:
                        fn, sf, ft = results[0]
                        _import_result_as_layer(
                            image, _download_image(srv, fn, sf, ft),
                            f"Generated #{run_i+1}", keep_size=True)
                Gimp.displays_flush()
            _LAST_PROCEDURE["name"] = "spellcaster-generate-anything"
            _LAST_PROCEDURE["session_key"] = "generate_anything"
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Generate Anything Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    # ── Layer Blend by Ratio (utility) ────────────────────────────────
    def _run_layer_blend_ratio(self, procedure, run_mode, image, drawables, config, data):
        """Blend two layers by ratio using ComfyUI ImageBlend node."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        GimpUi.init("spellcaster")

        layers = image.get_layers()
        if len(layers) < 2:
            Gimp.message("Need at least 2 layers to blend.\n\nLayer 1 = Image A\nLayer 2 = Image B\n"
                         "The blend ratio controls how much of each layer appears in the result.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())

        BLEND_MODES = ["normal", "multiply", "screen", "overlay", "soft_light", "difference"]

        dlg = Gtk.Dialog(title="Spellcaster — Layer Blend by Ratio")
        dlg.set_default_size(460, -1)
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Blend", Gtk.ResponseType.OK)
        bx = dlg.get_content_area()
        bx.set_spacing(6); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(10); bx.set_margin_bottom(10)

        # Server
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        srv_e = Gtk.Entry(); srv_e.set_text(COMFYUI_DEFAULT_URL); srv_e.set_hexpand(True)
        hb.pack_start(srv_e, True, True, 0); bx.pack_start(hb, False, False, 0)
        srv_e.set_tooltip_text("ComfyUI server URL (e.g. http://192.168.x.x:8188)")

        bx.pack_start(Gtk.Label(label="Blend two layers by a controllable ratio.\n"
                                      "0% = 100% Layer A, 100% = 100% Layer B."),
                       False, False, 4)

        # Layer A
        hla = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hla.pack_start(Gtk.Label(label="Layer A:"), False, False, 0)
        la_combo = Gtk.ComboBoxText()
        for idx, l in enumerate(layers):
            la_combo.append(str(idx), l.get_name())
        la_combo.set_active(0)
        la_combo.set_tooltip_text("First image (base). At ratio 0% you see only this layer")
        hla.pack_start(la_combo, True, True, 0); bx.pack_start(hla, False, False, 0)

        # Layer B
        hlb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hlb.pack_start(Gtk.Label(label="Layer B:"), False, False, 0)
        lb_combo = Gtk.ComboBoxText()
        for idx, l in enumerate(layers):
            lb_combo.append(str(idx), l.get_name())
        lb_combo.set_active(1 if len(layers) > 1 else 0)
        lb_combo.set_tooltip_text("Second image (blend target). At ratio 100% you see only this layer")
        hlb.pack_start(lb_combo, True, True, 0); bx.pack_start(hlb, False, False, 0)

        # Blend ratio slider
        hr = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hr.pack_start(Gtk.Label(label="Blend ratio:"), False, False, 0)
        ratio_sp = Gtk.SpinButton.new_with_range(0.0, 1.0, 0.05)
        ratio_sp.set_value(0.50)
        ratio_sp.set_digits(2)
        ratio_sp.set_tooltip_text("0.0 = 100% Layer A\n0.5 = equal mix\n1.0 = 100% Layer B")
        hr.pack_start(ratio_sp, True, True, 0)
        # Percentage label
        pct_label = Gtk.Label(label="50% A / 50% B")
        def _update_pct(*_a):
            r = ratio_sp.get_value()
            pct_label.set_text(f"{100 - r*100:.0f}% A / {r*100:.0f}% B")
        ratio_sp.connect("value-changed", _update_pct)
        hr.pack_start(pct_label, False, False, 4)
        bx.pack_start(hr, False, False, 0)

        # Blend mode
        hm = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hm.pack_start(Gtk.Label(label="Mode:"), False, False, 0)
        mode_combo = Gtk.ComboBoxText()
        for m in BLEND_MODES: mode_combo.append(m, m)
        mode_combo.set_active_id("normal")
        mode_combo.set_tooltip_text("Blending mode:\n• normal: linear interpolation (most common)\n"
                                     "• multiply: darkens, good for shadows\n• screen: lightens\n"
                                     "• overlay: contrast boost\n• soft_light: subtle toning")
        hm.pack_start(mode_combo, True, True, 0); bx.pack_start(hm, False, False, 0)

        bx.show_all()
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())

        srv = srv_e.get_text().strip(); _propagate_server_url(srv)
        la_idx = int(la_combo.get_active_id() or "0")
        lb_idx = int(lb_combo.get_active_id() or "1")
        ratio = ratio_sp.get_value()
        mode = mode_combo.get_active_id() or "normal"
        dlg.destroy()

        try:
            _update_spinner_status("Layer Blend: exporting layers...")
            # Export Layer A
            a_img = Gimp.Image.new(image.get_width(), image.get_height(), Gimp.ImageBaseType.RGB)
            a_copy = Gimp.Layer.new_from_drawable(layers[la_idx], a_img)
            a_img.insert_layer(a_copy, None, 0); a_img.flatten()
            a_tmp = _export_image_to_tmp(a_img); a_img.delete()
            # Export Layer B
            b_img = Gimp.Image.new(image.get_width(), image.get_height(), Gimp.ImageBaseType.RGB)
            b_copy = Gimp.Layer.new_from_drawable(layers[lb_idx], b_img)
            b_img.insert_layer(b_copy, None, 0); b_img.flatten()
            b_tmp = _export_image_to_tmp(b_img); b_img.delete()

            a_name = f"blend_a_{uuid.uuid4().hex[:8]}.png"
            b_name = f"blend_b_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, a_tmp, a_name); os.unlink(a_tmp)
            _upload_image(srv, b_tmp, b_name); os.unlink(b_tmp)

            wf = build_layer_blend(a_name, b_name, ratio, mode)

            results = _run_with_spinner("Layer Blend: processing...",
                                         lambda: list(_run_comfyui_workflow(srv, wf)))
            for i, (fn, sf, ft) in enumerate(results):
                _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft), f"Blend {100 - ratio*100:.0f}A/{ratio*100:.0f}B #{i+1}", False)
            Gimp.displays_flush()
            Gimp.progress_end()
            _LAST_PROCEDURE["name"] = "spellcaster-layer-blend-ratio"
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Layer Blend Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    # ── Upscaler Ratio Blender ────────────────────────────────────────
    def _run_upscale_blend(self, procedure, run_mode, image, drawables, config, data):
        """Upscale with two models and blend results by ratio."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        GimpUi.init("spellcaster")

        # Filter out (none)
        models = {k: v for k, v in UPSCALE_PRESETS.items() if v is not None}

        dlg = Gtk.Dialog(title="Spellcaster — Upscaler Ratio Blender")
        dlg.set_default_size(500, -1)
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Upscale && Blend", Gtk.ResponseType.OK)
        bx = dlg.get_content_area()
        bx.set_spacing(6); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(10); bx.set_margin_bottom(10)

        # Server
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        srv_e = Gtk.Entry(); srv_e.set_text(COMFYUI_DEFAULT_URL); srv_e.set_hexpand(True)
        hb.pack_start(srv_e, True, True, 0); bx.pack_start(hb, False, False, 0)
        srv_e.set_tooltip_text("ComfyUI server URL (e.g. http://192.168.x.x:8188)")

        bx.pack_start(Gtk.Label(label="Upscale with two different models and blend the results.\n"
                                      "Example: 40% ESRGAN (sharp) + 60% Remacri (smooth) for balanced output."),
                       False, False, 4)

        # Model A
        ha = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        ha.pack_start(Gtk.Label(label="Model A:"), False, False, 0)
        ma_combo = Gtk.ComboBoxText()
        for k in models: ma_combo.append(k, k)
        ma_combo.set_active(0)
        ma_combo.set_tooltip_text("First upscale model. Its result weight = (1 - ratio)")
        ha.pack_start(ma_combo, True, True, 0); bx.pack_start(ha, False, False, 0)

        # Model B
        hb2 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb2.pack_start(Gtk.Label(label="Model B:"), False, False, 0)
        mb_combo = Gtk.ComboBoxText()
        for k in models: mb_combo.append(k, k)
        # Default to Remacri if available
        keys = list(models.keys())
        mb_combo.set_active(3 if len(keys) > 3 else min(1, len(keys)-1))
        mb_combo.set_tooltip_text("Second upscale model. Its result weight = ratio")
        hb2.pack_start(mb_combo, True, True, 0); bx.pack_start(hb2, False, False, 0)

        # Ratio slider
        hr = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hr.pack_start(Gtk.Label(label="Blend ratio:"), False, False, 0)
        ratio_sp = Gtk.SpinButton.new_with_range(0.0, 1.0, 0.05)
        ratio_sp.set_value(0.60)
        ratio_sp.set_digits(2)
        ratio_sp.set_tooltip_text("0.0 = 100% Model A\n0.5 = equal mix\n1.0 = 100% Model B\n\n"
                                   "Example: 0.60 = 40% Model A + 60% Model B")
        hr.pack_start(ratio_sp, True, True, 0)
        pct_label = Gtk.Label(label="40% A / 60% B")
        def _update_pct(*_a):
            r = ratio_sp.get_value()
            pct_label.set_text(f"{100 - r*100:.0f}% A / {r*100:.0f}% B")
        ratio_sp.connect("value-changed", _update_pct)
        hr.pack_start(pct_label, False, False, 4)
        bx.pack_start(hr, False, False, 0)

        # Quick presets
        bx.pack_start(Gtk.Label(label="Quick recipes:"), False, False, 2)
        RECIPES = {
            "Balanced (50/50 UltraSharp + Remacri)": ("4x UltraSharp (general)", "4x Remacri (restoration)", 0.50),
            "Sharp detail (70% UltraSharp + 30% ESRGAN)": ("4x UltraSharp (general)", "4x RealESRGAN (photo)", 0.30),
            "Smooth restoration (30% ESRGAN + 70% Remacri)": ("4x RealESRGAN (photo)", "4x Remacri (restoration)", 0.70),
            "Anime blend (60% Anime + 40% UltraSharp)": ("4x RealESRGAN Anime", "4x UltraSharp (general)", 0.40),
            "Portrait (40% Faces + 60% Remacri)": ("8x NMKD Faces (portraits)", "4x Remacri (restoration)", 0.60),
        }
        recipe_combo = Gtk.ComboBoxText()
        recipe_combo.append("(custom)", "(custom — use settings above)")
        for k in RECIPES: recipe_combo.append(k, k)
        recipe_combo.set_active(0)
        recipe_combo.set_tooltip_text("Pre-configured upscaler blending recipes.\n"
                                       "Select one to auto-fill Model A, Model B, and ratio")
        def _on_recipe(*_a):
            key = recipe_combo.get_active_id()
            if key and key != "(custom)" and key in RECIPES:
                a_key, b_key, r = RECIPES[key]
                ma_combo.set_active_id(a_key)
                mb_combo.set_active_id(b_key)
                ratio_sp.set_value(r)
        recipe_combo.connect("changed", _on_recipe)
        bx.pack_start(recipe_combo, False, False, 0)

        bx.show_all()
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())

        srv = srv_e.get_text().strip(); _propagate_server_url(srv)
        ma_key = ma_combo.get_active_id()
        mb_key = mb_combo.get_active_id()
        ma_file = models.get(ma_key)
        mb_file = models.get(mb_key)
        ratio = ratio_sp.get_value()
        dlg.destroy()

        if not ma_file or not mb_file:
            Gimp.message("Please select two valid upscale models.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())

        try:
            _update_spinner_status("Upscale Blend: exporting image...")
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_upblend_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)

            wf = build_upscale_blend(uname, ma_file, mb_file, ratio, scale_by=1.0)

            results = _run_with_spinner("Upscale Blend: upscaling with two models and blending...",
                                         lambda: list(_run_comfyui_workflow(srv, wf, timeout=600)))
            for i, (fn, sf, ft) in enumerate(results):
                _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft),
                                        f"Upscale {100 - ratio*100:.0f}%{ma_key.split('(')[0].strip()}"
                                        f" + {ratio*100:.0f}%{mb_key.split('(')[0].strip()} #{i+1}")
            Gimp.displays_flush()
            Gimp.progress_end()
            _LAST_PROCEDURE["name"] = "spellcaster-upscale-blend"
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Upscaler Blend Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

