    def _run_sam3_anything_but(self, procedure, run_mode, image, drawables, config, data):
        """SAM3 Anything But — select everything EXCEPT a described subject.

        User types what to EXCLUDE ("person", "car", "sky") and SAM3 returns
        an inverted mask. The mask becomes the active GIMP selection — marching
        ants around everything in the image except the detected target.
        """
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        srv = _load_config().get("server_url") or COMFYUI_DEFAULT_URL
        try:
            _api_get(srv, "/object_info/SAM3Segment")
        except Exception:
            Gimp.message(
                "SAM3 node pack is not installed on your ComfyUI server.\n\n"
                "Install via ComfyUI Manager, search for 'SAM3' or\n"
                "'Segment Anything 3', then restart ComfyUI.\n\n"
                f"Server checked: {srv}")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        GimpUi.init("spellcaster")
        dlg = Gtk.Dialog(title="Spellcaster — Anything But... (Reverse Select)")
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Select", Gtk.ResponseType.OK)
        bx = dlg.get_content_area()
        bx.set_spacing(8); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(12); bx.set_margin_bottom(12)
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        se = Gtk.Entry(); se.set_text(COMFYUI_DEFAULT_URL); se.set_hexpand(True)
        se.set_tooltip_text("ComfyUI server URL")
        hb.pack_start(se, True, True, 0); bx.pack_start(hb, False, False, 0)
        hb2 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb2.pack_start(Gtk.Label(label="Exclude:"), False, False, 0)
        pe = Gtk.Entry(); pe.set_text("person"); pe.set_hexpand(True)
        pe.set_tooltip_text("Describe what NOT to select. Everything else becomes the selection.\nExamples: 'person', 'sky', 'car', 'shirt'.")
        hb2.pack_start(pe, True, True, 0); bx.pack_start(hb2, False, False, 0)
        hb3 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb3.pack_start(Gtk.Label(label="Feather (px):"), False, False, 0)
        fe = Gtk.SpinButton.new_with_range(0, 100, 1); fe.set_value(4)
        fe.set_tooltip_text("Feather the selection edges by this many pixels (0 = hard edge).")
        hb3.pack_start(fe, False, False, 0); bx.pack_start(hb3, False, False, 0)
        bx.pack_start(Gtk.Label(label="SAM3 detects the target, inverts the mask,\nand creates a selection of everything else."), False, False, 4)
        bx.show_all()
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        srv = se.get_text().strip()
        prompt = pe.get_text().strip()
        feather = int(fe.get_value())
        _propagate_server_url(srv); dlg.destroy()
        if not prompt:
            Gimp.message("Anything But needs something to exclude. Type what to skip.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        try:
            _update_spinner_status("Anything But: exporting image...")
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_antibut_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)
            # invert=True -> mask output (slot 1) is reversed.
            wf = build_sam3_segment(uname, prompt, invert=True,
                                     mask_expand=0, mask_blur=0)
            _update_spinner_status("Anything But: segmenting on ComfyUI...")
            results = _run_with_spinner("Anything But: segmenting on ComfyUI...",
                                         lambda: list(_run_comfyui_workflow(srv, wf)))
            mask_path = None
            for fn, sf, ft in results:
                if 'mask' in fn.lower():
                    mask_path = _download_image(srv, fn, sf, ft)
                    break
            if not mask_path:
                raise RuntimeError("SAM3 did not return a mask image")
            _mask_image_to_gimp_selection(image, mask_path, feather=feather)
            Gimp.displays_flush()
            Gimp.progress_end()
            _LAST_PROCEDURE["name"] = "spellcaster-anything-but"
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Spellcaster Anything But Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    def _run_magic_eraser(self, procedure, run_mode, image, drawables, config, data):
        """Magic Eraser — SAM3 detect + LaMa seamless inpaint.

        User describes an unwanted object; SAM3 segments it and LaMa
        paints over it. No mask painting, no selection needed — just describe
        what to remove. Fast, deterministic, non-destructive (new layer).
        """
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        srv = _load_config().get("server_url") or COMFYUI_DEFAULT_URL
        try:
            _api_get(srv, "/object_info/SAM3Segment")
        except Exception:
            Gimp.message(
                "SAM3 node pack is not installed on your ComfyUI server.\n\n"
                "Install via ComfyUI Manager (search 'SAM3'), then restart.\n\n"
                f"Server checked: {srv}")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        try:
            _api_get(srv, "/object_info/LamaRemover")
        except Exception:
            Gimp.message(
                "LaMa node is not installed on your ComfyUI server.\n\n"
                "Install 'ComfyUI-LaMA-Preprocessor' via ComfyUI Manager\n"
                "(or equivalent LaMa pack), then restart ComfyUI.\n\n"
                f"Server checked: {srv}")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        GimpUi.init("spellcaster")
        dlg = Gtk.Dialog(title="Spellcaster — Magic Eraser")
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Erase", Gtk.ResponseType.OK)
        bx = dlg.get_content_area()
        bx.set_spacing(8); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(12); bx.set_margin_bottom(12)
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        se = Gtk.Entry(); se.set_text(COMFYUI_DEFAULT_URL); se.set_hexpand(True)
        se.set_tooltip_text("ComfyUI server URL")
        hb.pack_start(se, True, True, 0); bx.pack_start(hb, False, False, 0)
        hb2 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb2.pack_start(Gtk.Label(label="Remove:"), False, False, 0)
        pe = Gtk.Entry(); pe.set_text(""); pe.set_hexpand(True)
        pe.set_tooltip_text("Describe what to remove — be specific.\nExamples: 'power line', 'tourist in background', 'car on road', 'watermark'.")
        hb2.pack_start(pe, True, True, 0); bx.pack_start(hb2, False, False, 0)
        hb3 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb3.pack_start(Gtk.Label(label="Mask expand (px):"), False, False, 0)
        exp = Gtk.SpinButton.new_with_range(0, 64, 1); exp.set_value(8)
        exp.set_tooltip_text("Grow the detected mask so LaMa can hide contact shadows and edge artifacts (default 8).")
        hb3.pack_start(exp, False, False, 0); bx.pack_start(hb3, False, False, 0)
        hb4 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb4.pack_start(Gtk.Label(label="Mask blur (px):"), False, False, 0)
        blr = Gtk.SpinButton.new_with_range(0, 32, 1); blr.set_value(4)
        blr.set_tooltip_text("Feather the grown mask edge for a seamless blend (default 4).")
        hb4.pack_start(blr, False, False, 0); bx.pack_start(hb4, False, False, 0)
        bx.pack_start(Gtk.Label(label="SAM3 detects what you described, LaMa inpaints over it.\nNo diffusion — fast and deterministic. Result is a new layer."), False, False, 4)
        bx.show_all()
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        srv = se.get_text().strip()
        prompt = pe.get_text().strip()
        if not prompt:
            Gimp.message("Magic Eraser needs a description of what to remove.")
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        expand_px = int(exp.get_value())
        blur_px = int(blr.get_value())
        _propagate_server_url(srv); dlg.destroy()
        try:
            _update_spinner_status("Magic Eraser: exporting image...")
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_magicerase_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)
            wf = build_magic_eraser(uname, prompt,
                                     mask_expand=expand_px, mask_blur=blur_px)
            _update_spinner_status("Magic Eraser: detecting + inpainting...")
            results = _run_with_spinner("Magic Eraser: detecting + inpainting...",
                                         lambda: list(_run_comfyui_workflow(srv, wf)))
            if not results:
                raise RuntimeError("Magic Eraser returned no result")
            fn, sf, ft = results[0]
            _import_result_as_layer(image, _download_image(srv, fn, sf, ft),
                                    f"Erased: {prompt}", keep_size=True)
            Gimp.displays_flush()
            Gimp.progress_end()
            _LAST_PROCEDURE["name"] = "spellcaster-magic-eraser"
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Spellcaster Magic Eraser Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    def _run_send(self, procedure, run_mode, image, drawables, config, data):
        """Upload current canvas to ComfyUI's input folder (no generation)."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        GimpUi.init("spellcaster")
        dlg = Gtk.Dialog(title="Upload to Spellcaster")
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Upload", Gtk.ResponseType.OK)
        bx = dlg.get_content_area()
        bx.set_spacing(8); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(12); bx.set_margin_bottom(12)
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        se = Gtk.Entry(); se.set_text(COMFYUI_DEFAULT_URL); se.set_hexpand(True)
        se.set_tooltip_text("ComfyUI server address. Default: http://127.0.0.1:8188")
        hb.pack_start(se, True, True, 0); bx.pack_start(hb, False, False, 0)
        uname = f"gimp_upload_{uuid.uuid4().hex[:8]}.png"
        hb2 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb2.pack_start(Gtk.Label(label="Filename:"), False, False, 0)
        ne = Gtk.Entry(); ne.set_text(uname); ne.set_hexpand(True)
        ne.set_tooltip_text("Filename for the uploaded image on the ComfyUI server.\nAuto-generated with a unique ID to avoid overwriting.")
        hb2.pack_start(ne, True, True, 0); bx.pack_start(hb2, False, False, 0)
        bx.show_all()
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        srv = se.get_text().strip(); _propagate_server_url(srv); fn = ne.get_text().strip(); dlg.destroy()
        try:
            _update_spinner_status("Uploading...")
            tmp = _export_image_to_tmp(image)
            r = _upload_image_sync(srv, tmp, fn); os.unlink(tmp)
            Gimp.message(f"Uploaded as: {r.get('name', fn)}")
            Gimp.progress_end()
            _LAST_PROCEDURE["name"] = "spellcaster-send-image"
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Upload Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    def _run_my_presets(self, procedure, run_mode, image, drawables, config, data):
        """My Spellcaster Presets: quick access to all saved presets across tools."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        GimpUi.init("spellcaster")
        _apply_spellcaster_theme()
        dlg = Gtk.Dialog(title="My Spellcaster Presets")
        dlg.set_default_size(600, 400)
        dlg.add_button("_Close", Gtk.ResponseType.CLOSE)
        _style_dialog_buttons(dlg)
        bx = dlg.get_content_area()
        bx.set_spacing(8); bx.set_margin_start(16); bx.set_margin_end(16)
        bx.set_margin_top(16); bx.set_margin_bottom(16)

        _hdr = _make_branded_header()
        if _hdr:
            bx.pack_start(_hdr, False, False, 0)

        # Map dialog keys to human-readable tool names
        # Keys MUST match what _add_preset_ui uses in each dialog
        tool_names = {
            "preset_dialog": "img2img / txt2img / Inpaint",
            "wan_i2v": "Wan I2V Video",
            "faceid": "FaceID",
            "klein": "Klein Editor",
            "pulid_flux": "PuLID Flux",
        }

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        list_box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=4)
        scroll.add(list_box)

        found_any = False
        for dialog_key, tool_label in tool_names.items():
            saved = _load_user_presets(dialog_key)
            if not saved:
                continue

            # Section header
            header = Gtk.Label()
            header.set_markup(f'<b><span foreground="#E32234">{tool_label}</span></b>')
            header.set_xalign(0)
            list_box.pack_start(header, False, False, 4)

            for preset in saved:
                found_any = True
                row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
                row.set_margin_start(12)

                # Preset name
                name_lbl = Gtk.Label(label=preset.get("name", "Unnamed"), xalign=0)
                name_lbl.set_hexpand(True)
                row.pack_start(name_lbl, True, True, 0)

                # Info tooltip with preset details
                info_parts = []
                if preset.get("model_preset_idx") is not None:
                    idx = preset["model_preset_idx"]
                    if 0 <= idx < len(MODEL_PRESETS):
                        info_parts.append(f"Model: {MODEL_PRESETS[idx]['label']}")
                if preset.get("prompt"):
                    p = preset["prompt"][:80]
                    info_parts.append(f"Prompt: {p}...")
                if preset.get("steps"):
                    info_parts.append(f"Steps: {preset['steps']}")
                name_lbl.set_tooltip_text("\n'.join(info_parts) if info_parts else 'Saved preset")

                # Load button — applies preset to session and opens the tool
                load_btn = Gtk.Button(label="Load")
                load_btn.set_tooltip_text(f"Load this preset into {tool_label} and open the tool")
                def _make_load_cb(dk, p):
                    def on_load(btn):
                        # Store preset into session for the correct tool
                        session_key = {
                            "preset_dialog": "img2img",
                            "wan_i2v": "wan_i2v",
                            "faceid": "faceid",
                            "klein": "klein",
                            "pulid_flux": "pulid_flux",
                        }.get(dk, dk)
                        _SESSION[session_key] = p
                        _save_session()
                        dlg.destroy()
                    return on_load
                load_btn.connect("clicked", _make_load_cb(dialog_key, preset))
                row.pack_end(load_btn, False, False, 0)

                # Delete button
                del_btn = Gtk.Button(label="Delete")
                del_btn.set_tooltip_text(f"Delete this preset permanently")
                def _make_del_cb(dk, pname, r):
                    def on_del(btn):
                        presets = _load_user_presets(dk)
                        presets = [pp for pp in presets if pp.get("name") != pname]
                        _save_user_presets(presets, dk)
                        r.destroy()
                    return on_del
                del_btn.connect("clicked", _make_del_cb(dialog_key, preset.get("name"), row))
                row.pack_end(del_btn, False, False, 0)

                list_box.pack_start(row, False, False, 0)

            list_box.pack_start(Gtk.Separator(), False, False, 2)

        if not found_any:
            empty = Gtk.Label()
            empty.set_markup(
                '<span foreground="#888888">No saved presets yet.\n\n'
                'To save a preset, open any Spellcaster tool,\n'
                'configure your settings, then click "Save" in\n'
                'the My Presets section of the dialog.</span>')
            list_box.pack_start(empty, True, True, 20)

        bx.pack_start(scroll, True, True, 0)
        bx.show_all()
        dlg.run()
        dlg.destroy()
        _LAST_PROCEDURE["name"] = "spellcaster-my-presets"
        Gimp.progress_end()
        return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())

    # ── Travelling Wizard (Signal Bridge + Scaffold) ───────────────────
    def _run_bridge(self, procedure, run_mode, image, drawables, config, data):
        """Travelling Wizard: scaffold editor, workflow library, LLM wizard."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        try:
            GimpUi.init("spellcaster")
        except Exception:
            pass
        try:
            _apply_spellcaster_theme()
        except Exception:
            pass
        cfg = _load_config()
        server_url = cfg.get("server_url", COMFYUI_DEFAULT_URL).rstrip("/")

        dlg = Gtk.Dialog(title="The Travelling Wizard")
        dlg.set_default_size(560, 520)
        dlg.add_button("_Close", Gtk.ResponseType.CLOSE)
        _style_dialog_buttons(dlg)
        bx = dlg.get_content_area()
        bx.set_spacing(10); bx.set_margin_start(16); bx.set_margin_end(16)
        bx.set_margin_top(16); bx.set_margin_bottom(16)

        # Header
        _hdr = _make_branded_header()
        if _hdr:
            bx.pack_start(_hdr, False, False, 0)
        title = Gtk.Label()
        title.set_markup(
            '<span size="large" weight="bold">The Travelling Wizard</span>\n'
            '<span size="small">Signal Bridge &amp; Spellcaster Scaffold</span>')
        title.set_halign(Gtk.Align.START)
        bx.pack_start(title, False, False, 0)
        bx.pack_start(Gtk.Separator(), False, False, 4)

        # Server status
        status_box = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
        status_icon = Gtk.Label()
        status_text = Gtk.Label()
        try:
            req = urllib.request.Request(f"{server_url}/system_stats", method="GET")
            with urllib.request.urlopen(req, timeout=3) as resp:
                sdata = json.loads(resp.read())
                gpu = sdata.get("devices", [{}])[0].get("name", "GPU")
                vram = sdata.get("devices", [{}])[0].get("vram_total", 0)
                if vram:
                    status_icon.set_markup('<span foreground="#00E676">●</span>')
                    status_text.set_markup(
                        f'<span foreground="#00E676">ComfyUI Online</span>'
                        f'  <span size="small" foreground="#888">{server_url} — {gpu} ({vram//1024//1024//1024} GB)</span>')
                else:
                    status_icon.set_markup('<span foreground="#00E676">●</span>')
                    status_text.set_markup(f'<span foreground="#00E676">Connected</span>  <span size="small" foreground="#888">{server_url}</span>')
        except Exception:
            status_icon.set_markup('<span foreground="#FF5252">●</span>')
            status_text.set_markup(f'<span foreground="#FF5252">ComfyUI Offline</span>  <span size="small" foreground="#888">{server_url}</span>')
        status_box.pack_start(status_icon, False, False, 0)
        status_box.pack_start(status_text, True, True, 0)
        bx.pack_start(status_box, False, False, 0)

        # ── Actions frame ──
        actions_frame = Gtk.Frame(label="Actions")
        actions_box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
        actions_box.set_margin_start(12); actions_box.set_margin_end(12)
        actions_box.set_margin_top(12); actions_box.set_margin_bottom(12)

        def _make_action_button(title_text, desc_text, on_click):
            btn = Gtk.Button()
            vb = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
            t = Gtk.Label(); t.set_markup(f"<b>{title_text}</b>"); t.set_halign(Gtk.Align.START)
            d = Gtk.Label(); d.set_text(desc_text); d.set_halign(Gtk.Align.START); d.set_line_wrap(True)
            d.get_style_context().add_class("dim-label")
            vb.pack_start(t, False, False, 0); vb.pack_start(d, False, False, 0)
            btn.add(vb); btn.connect("clicked", on_click)
            actions_box.pack_start(btn, False, False, 0)
            return btn

        # Button 1: Open scaffold settings in browser
        def _on_open_settings(btn):
            # Look for the settings HTML in known locations
            plugin_dir = os.path.dirname(os.path.abspath(__file__))
            candidates = [
                os.path.join(plugin_dir, "signal_bridge_settings.html"),
                os.path.join(plugin_dir, "..", "signal_bridge_settings.html"),
                cfg.get("wizard_settings_path", ""),
            ]
            for path in candidates:
                if path and os.path.isfile(path):
                    import webbrowser
                    webbrowser.open(f"file://{os.path.abspath(path)}")
                    return
            # Fallback: try server endpoint
            import webbrowser
            webbrowser.open(f"{server_url}/spellcaster/settings")
        _make_action_button(
            "Open Scaffold Editor",
            "Opens the full Travelling Wizard settings UI in your browser.\n"
            "Configure scaffolds, import workflows, manage Signal Bridge.",
            _on_open_settings)

        # Button 2: Browse workflow library from ComfyUI server
        def _on_browse_workflows(btn):
            _bridge_workflow_browser(dlg, server_url, cfg)
        _make_action_button(
            "Browse Workflow Library",
            "Browse and import ComfyUI workflows from your server.\n"
            "Any workflow JSON can be parsed and added as a Spellcaster action.",
            _on_browse_workflows)

        # Button 3: Import workflow JSON from disk
        def _on_import_file(btn):
            fc = Gtk.FileChooserDialog(
                title="Import ComfyUI Workflow",
                parent=dlg,
                action=Gtk.FileChooserAction.OPEN)
            fc.add_button("_Cancel", Gtk.ResponseType.CANCEL)
            fc.add_button("_Open", Gtk.ResponseType.OK)
            filt = Gtk.FileFilter(); filt.set_name("JSON files"); filt.add_pattern("*.json")
            fc.add_filter(filt)
            if fc.run() == Gtk.ResponseType.OK:
                path = fc.get_filename()
                fc.destroy()
                _bridge_import_workflow(dlg, path, cfg)
            else:
                fc.destroy()
        _make_action_button(
            "Import Workflow File",
            "Import a ComfyUI workflow JSON from your computer.\n"
            "Supports litegraph (UI export) and API format.",
            _on_import_file)

        actions_frame.add(actions_box)
        bx.pack_start(actions_frame, False, False, 0)

        # ── Installed custom workflows list ──
        custom_frame = Gtk.Frame(label="Installed Workflows")
        custom_box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6)
        custom_box.set_margin_start(12); custom_box.set_margin_end(12)
        custom_box.set_margin_top(8); custom_box.set_margin_bottom(8)
        custom_wfs = cfg.get("custom_workflows", {})
        if custom_wfs:
            for wf_name, wf_info in custom_wfs.items():
                row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
                lbl = Gtk.Label(); lbl.set_markup(f"<b>{wf_name}</b>"); lbl.set_halign(Gtk.Align.START)
                row.pack_start(lbl, True, True, 0)
                wf_type = wf_info.get("workflow_type", "General")
                tlbl = Gtk.Label(); tlbl.set_markup(f'<span size="small" foreground="#888">{wf_type}</span>')
                row.pack_start(tlbl, False, False, 0)
                custom_box.pack_start(row, False, False, 0)
        else:
            empty = Gtk.Label()
            empty.set_markup(
                '<span foreground="#888">No custom workflows installed.\n'
                'Use Import or Browse to add workflows.</span>')
            empty.set_halign(Gtk.Align.CENTER)
            custom_box.pack_start(empty, False, False, 4)
        custom_frame.add(custom_box)
        bx.pack_start(custom_frame, True, True, 0)

        bx.show_all()
        dlg.run()
        dlg.destroy()
        _LAST_PROCEDURE["name"] = "spellcaster-bridge"
        Gimp.progress_end()
        return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())

    # ══════════════════════════════════════════════════════════════════════
    #  F5: Flux Kontext Editor
    # ══════════════════════════════════════════════════════════════════════

    def _run_kontext(self, procedure, run_mode, image, drawables, config, data):
        """Flux Kontext: instruction-based image editing."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        GimpUi.init("spellcaster")
        dlg = KontextDialog("Spellcaster — Flux Kontext Editor")
        last = _SESSION.get("kontext")
        if last:
            dlg._apply_user_preset(last)
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        v = dlg.get_values()
        _SESSION["kontext"] = dlg._collect_user_preset()
        _save_session()
        dlg.destroy()
        runs = v.get("runs", 1)
        try:
            _update_spinner_status("Kontext: exporting image...")
            srv = v["server"]
            _propagate_server_url(srv)
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_kontext_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)
            # Build a preset dict compatible with build_img2img
            preset = {
                "arch": "flux_kontext",
                "ckpt": KONTEXT_DEFAULTS["ckpt"],
                "width": image.get_width(), "height": image.get_height(),
                "steps": v["steps"], "cfg": v["cfg"],
                "denoise": v["denoise"],
                "sampler": KONTEXT_DEFAULTS["sampler"],
                "scheduler": KONTEXT_DEFAULTS["scheduler"],
            }
            loras = []
            if v.get("lora_name"):
                loras.append({"name": v["lora_name"],
                              "strength_model": v["lora_strength"],
                              "strength_clip": v["lora_strength"]})
            base_seed = v["seed"]
            for run_i in range(runs):
                seed = base_seed if runs == 1 else random.randint(0, 2**32 - 1)
                wf = _build_img2img(uname, preset, v["prompt"], "", seed,
                                    loras=loras or None)
                label = f"Kontext run {run_i+1}/{runs}" if runs > 1 else "Kontext"
                _wf = wf
                results = _run_with_spinner(f"{label}: processing on ComfyUI...",
                                            lambda: list(_run_comfyui_workflow(srv, _wf)))
                for i, (fn, sf, ft) in enumerate(results):
                    lbl = f"Kontext run {run_i+1} #{i+1}" if runs > 1 \
                          else f"Kontext #{i+1}"
                    _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft), lbl, False)
                Gimp.displays_flush()
            _LAST_PROCEDURE["name"] = "spellcaster-kontext"
            _LAST_PROCEDURE["session_key"] = "kontext"
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Spellcaster Kontext Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    # ══════════════════════════════════════════════════════════════════════
    #  F2: Re-run Last
    # ══════════════════════════════════════════════════════════════════════

    def _run_rerun_last(self, procedure, run_mode, image, drawables, config, data):
        """Re-run the last Spellcaster operation with same settings."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        last_name = _LAST_PROCEDURE.get("name")
        if not last_name:
            Gimp.message("No previous Spellcaster operation to repeat.\n"
                         "Run any Spellcaster tool first, then use Re-run Last.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        # Look up the procedure callback from the menu_map
        try:
            pdb = Gimp.get_pdb()
            pdb_proc = pdb.lookup_procedure(last_name)
            if pdb_proc:
                pdb_config = pdb_proc.create_config()
                pdb_config.set_property("run-mode", Gimp.RunMode.WITH_LAST_VALS)
                pdb_config.set_property("image", image)
                drawables_arg = image.get_selected_drawables()
                result = pdb.run_procedure_config(last_name, pdb_config)
                return result
        except Exception:
            pass
        # Fallback: call the callback directly with interactive mode
        # (shows dialog pre-filled with last settings via session recall)
        GimpUi.init("spellcaster")
        menu_map = self._get_menu_map()
        if last_name in menu_map:
            _label, callback, _doc = menu_map[last_name]
            return callback(procedure, Gimp.RunMode.INTERACTIVE, image,
                            drawables, config, data)
        Gimp.message(f"Cannot re-run: procedure '{last_name}' not found.")
        return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    def _get_menu_map(self):
        """Return the procedure→callback mapping (for re-run-last fallback)."""
        return {
            "spellcaster-img2img": ("", self._run_img2img, ""),
            "spellcaster-txt2img": ("", self._run_txt2img, ""),
            "spellcaster-inpaint": ("", self._run_inpaint, ""),
            "spellcaster-kontext": ("", self._run_kontext, ""),
            "spellcaster-klein-img2img": ("", self._run_klein, ""),
        }

    # ══════════════════════════════════════════════════════════════════════
    #  F3: Quick Context Menu Actions (right-click canvas)
    # ══════════════════════════════════════════════════════════════════════

    def _run_quick_enhance(self, procedure, run_mode, image, drawables, config, data):
        """Quick Enhance: re-run img2img with last settings, zero dialogs."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        v = _session_to_values("img2img", image)
        if not v:
            # No previous settings — open the full dialog instead
            GimpUi.init("spellcaster")
            return self._run_img2img(procedure, Gimp.RunMode.INTERACTIVE,
                                      image, drawables, config, data)
        try:
            srv = v["server"]
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_qe_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)
            seed = random.randint(0, 2**32 - 1)
            wf = _build_img2img(uname, v["preset"], v["prompt"], v["negative"],
                                seed, loras=v.get("loras"),
                                controlnet=v.get("controlnet"),
                                controlnet_2=v.get("controlnet_2"))
            results = _run_with_spinner("Quick Enhance...",
                                        lambda: list(_run_comfyui_workflow(srv, wf)))
            for i, (fn, sf, ft) in enumerate(results):
                _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft),
                                 f"Quick Enhance #{i+1}", False)
            _LAST_PROCEDURE["name"] = "spellcaster-img2img"
            _LAST_PROCEDURE["session_key"] = "img2img"
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Quick Enhance Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    def _run_quick_inpaint(self, procedure, run_mode, image, drawables, config, data):
        """Quick Inpaint: inpaint current selection with last settings."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        v = _session_to_values("inpaint", image)
        if not v:
            GimpUi.init("spellcaster")
            return self._run_inpaint(procedure, Gimp.RunMode.INTERACTIVE,
                                      image, drawables, config, data)
        # Check for active selection
        try:
            sel_exists = Gimp.Selection.bounds(image).non_empty
        except Exception:
            try:
                sel_exists, *_ = Gimp.Selection.bounds(image)
            except Exception:
                sel_exists = False
        if not sel_exists:
            Gimp.message("Quick Inpaint requires an active selection.\n"
                         "Use any selection tool (or SAM3 AI Selection) first.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        try:
            srv = v["server"]
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_qi_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)
            # Export selection as mask
            mask_tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
            mask_tmp.close()
            _create_selection_mask_png(mask_tmp.name, image)
            mask_uname = f"gimp_qi_mask_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, mask_tmp.name, mask_uname); os.unlink(mask_tmp.name)
            seed = random.randint(0, 2**32 - 1)
            wf = _build_inpaint(uname, mask_uname, v["preset"], v["prompt"],
                                v["negative"], seed, loras=v.get("loras"),
                                controlnet=v.get("controlnet"),
                                controlnet_2=v.get("controlnet_2"))
            results = _run_with_spinner("Quick Inpaint...",
                                        lambda: list(_run_comfyui_workflow(srv, wf)))
            for i, (fn, sf, ft) in enumerate(results):
                _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft),
                                 f"Quick Inpaint #{i+1}", False)
            _LAST_PROCEDURE["name"] = "spellcaster-inpaint"
            _LAST_PROCEDURE["session_key"] = "inpaint"
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Quick Inpaint Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

