    # ══════════════════════════════════════════════════════════════════════
    #  NormalCrafter — 3D surface normal map generation
    # ══════════════════════════════════════════════════════════════════════

    def _run_normal_map(self, procedure, run_mode, image, drawables, config, data):
        """Generate a 3D surface normal map using NormalCrafter."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        try:
            # Fix 1 (3D audit 2026-04-20): honor the user's configured
            # server URL. Previously hardcoded COMFYUI_DEFAULT_URL so
            # users who had set a custom server in Settings silently
            # hit the fallback default instead.
            srv = _load_config().get("server_url") or COMFYUI_DEFAULT_URL
            # Fix 4: preflight the NormalCrafter node so the user gets
            # a clear "install NormalCrafter" message instead of an
            # opaque workflow-submit error 60 s into the run.
            nodes = _probe_comfyui_nodes(srv)
            if nodes and "NormalCrafterNode" not in nodes:
                Gimp.message(
                    "3D Normal Map needs the NormalCrafter custom node "
                    "on your ComfyUI server.\n\n"
                    "Install it from ComfyUI Manager → Install Custom "
                    "Nodes → search 'NormalCrafter', or from:\n"
                    "  https://github.com/Stable-X/ComfyUI-NormalCrafter\n\n"
                    f"Then restart ComfyUI and try again.\n(Server: {srv})")
                return procedure.new_return_values(
                    Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_normal_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)
            wf = build_normal_map(uname, max_res=min(image.get_width(), 1024))
            results = _run_with_spinner("NormalCrafter: generating normal map...",
                                        lambda: list(_run_comfyui_workflow(srv, wf, timeout=300)))
            for i, (fn, sf, ft) in enumerate(results):
                _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft),
                                 f"Normal Map #{i+1}", False)
            Gimp.displays_flush()
            Gimp.progress_end()
            _LAST_PROCEDURE["name"] = "spellcaster-normal-map"
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"NormalCrafter Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    # ══════════════════════════════════════════════════════════════════════
    #  AI Eraser — select anything, erase it, AI fills the gap
    # ══════════════════════════════════════════════════════════════════════

    def _run_ai_eraser(self, procedure, run_mode, image, drawables, config, data):
        """AI Eraser: select any object and erase it — AI fills the background.

        Mirrors the exact export/upload/workflow/download pattern used by
        Quick Inpaint (_run_quick_inpaint) — same order, same temp file
        handling, same result import.
        """
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        # Check for active selection (same guard as Quick Inpaint)
        try:
            sel_exists = Gimp.Selection.bounds(image).non_empty
        except Exception:
            try:
                sel_exists, *_ = Gimp.Selection.bounds(image)
            except Exception:
                sel_exists = False
        if not sel_exists:
            Gimp.message("AI Eraser: No selection found.\n\n"
                         "Select what you want to erase first:\n"
                         "  \u2022 SAM3 AI Select (type what to select)\n"
                         "  \u2022 Fuzzy Select (magic wand)\n"
                         "  \u2022 Free Select (lasso)\n"
                         "  \u2022 Any GIMP selection tool\n\n"
                         "Then run AI Eraser again.")
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        try:
            srv = _load_config().get("server_url") or COMFYUI_DEFAULT_URL
            # Export image (same as Quick Inpaint line 21380)
            tmp = _export_image_to_tmp(image)
            uname = f"gimp_erase_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, uname); os.unlink(tmp)
            # Export selection as mask (same as Quick Inpaint line 21384)
            mask_tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
            mask_tmp.close()
            _create_selection_mask_png(mask_tmp.name, image)
            mask_uname = f"gimp_erase_mask_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, mask_tmp.name, mask_uname); os.unlink(mask_tmp.name)
            # Build LaMa removal workflow (no prompt, deterministic)
            wf = build_lama_remove(uname, mask_uname)
            results = _run_with_spinner("AI Eraser: removing selection...",
                                        lambda: list(_run_comfyui_workflow(srv, wf)))
            for i, (fn, sf, ft) in enumerate(results):
                _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft),
                                 f"AI Erased #{i+1}", False)
            # Clear the selection (the object is gone)
            try:
                Gimp.Selection.none(image)
            except Exception:
                pass
            _LAST_PROCEDURE["name"] = "spellcaster-quick-erase"
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"AI Eraser Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    # ══════════════════════════════════════════════════════════════════════
    #  F6: AI Color Match
    # ══════════════════════════════════════════════════════════════════════

    def _run_color_match(self, procedure, run_mode, image, drawables, config, data):
        """AI Color Match: transfer color palette from a reference image."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        GimpUi.init("spellcaster")
        dlg = Gtk.Dialog(title="Spellcaster — AI Color Match")
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Match Colors", Gtk.ResponseType.OK)
        _style_dialog_buttons(dlg)
        bx = dlg.get_content_area()
        bx.set_spacing(8); bx.set_margin_start(12); bx.set_margin_end(12)
        bx.set_margin_top(12); bx.set_margin_bottom(12)
        # Server
        hb = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb.pack_start(Gtk.Label(label="Server:"), False, False, 0)
        se = Gtk.Entry(); se.set_text(COMFYUI_DEFAULT_URL); se.set_hexpand(True)
        hb.pack_start(se, True, True, 0); bx.pack_start(hb, False, False, 0)
        se.set_tooltip_text("ComfyUI server URL (e.g. http://192.168.x.x:8188)")
        # Reference image
        bx.pack_start(Gtk.Label(label="Reference Image (color source):", xalign=0), False, False, 0)
        ref_chooser = Gtk.FileChooserButton(title="Select reference image")
        ref_chooser.set_action(Gtk.FileChooserAction.OPEN)
        ref_chooser.set_tooltip_text(
            "Select the image whose colors you want to match.\n"
            "The canvas image will be recolored to match this reference.")
        ff = Gtk.FileFilter(); ff.set_name("Images")
        ff.add_pattern("*.png"); ff.add_pattern("*.jpg"); ff.add_pattern("*.jpeg")
        ff.add_pattern("*.webp"); ff.add_pattern("*.bmp")
        ref_chooser.add_filter(ff)
        bx.pack_start(ref_chooser, False, False, 0)
        # Method
        hb2 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb2.pack_start(Gtk.Label(label="Method:"), False, False, 0)
        method_combo = Gtk.ComboBoxText()
        method_combo.set_tooltip_text(
            "Color transfer algorithm.\n"
            "MKL is best for photographs, Reinhard is a classic option.")
        for label_text in COLOR_MATCH_METHODS:
            method_combo.append(label_text, label_text)
        method_combo.set_active(0)
        hb2.pack_start(method_combo, True, True, 0); bx.pack_start(hb2, False, False, 0)
        # Strength
        hb3 = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
        hb3.pack_start(Gtk.Label(label="Strength:"), False, False, 0)
        strength_spin = Gtk.SpinButton.new_with_range(0.0, 1.0, 0.05)
        strength_spin.set_value(0.85)
        strength_spin.set_digits(2)
        strength_spin.set_tooltip_text("How strongly to apply the color transfer.\n0.0 = no change, 1.0 = full match.")
        hb3.pack_start(strength_spin, True, True, 0); bx.pack_start(hb3, False, False, 0)
        bx.show_all()
        # Recall last settings
        last = _SESSION.get("color_match")
        if last:
            if "method" in last:
                method_combo.set_active_id(last["method"])
            if "strength" in last:
                strength_spin.set_value(last["strength"])
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())
        srv = se.get_text().strip(); _propagate_server_url(srv)
        ref_path = ref_chooser.get_filename()
        method_label = method_combo.get_active_id()
        method_key = COLOR_MATCH_METHODS.get(method_label, "mkl")
        strength = strength_spin.get_value()
        _SESSION["color_match"] = {"method": method_label, "strength": strength}
        _save_session()
        dlg.destroy()
        if not ref_path:
            Gimp.message("No reference image selected.")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())
        try:
            _update_spinner_status("Color Match: exporting images...")
            tmp = _export_image_to_tmp(image)
            src_uname = f"gimp_cm_src_{uuid.uuid4().hex[:8]}.png"
            ref_uname = f"gimp_cm_ref_{uuid.uuid4().hex[:8]}.png"
            _upload_image(srv, tmp, src_uname); os.unlink(tmp)
            _upload_image(srv, ref_path, ref_uname)
            wf = build_color_match(src_uname, ref_uname, strength, method_key)
            results = _run_with_spinner("Color Match: processing...",
                                        lambda: list(_run_comfyui_workflow(srv, wf)))
            for i, (fn, sf, ft) in enumerate(results):
                _apply_mask_mode(srv, image, _download_image(srv, fn, sf, ft),
                                 f"Color Match ({method_label}) #{i+1}", False)
            _LAST_PROCEDURE["name"] = "spellcaster-color-match"
            _LAST_PROCEDURE["session_key"] = "color_match"
            Gimp.displays_flush()
            Gimp.progress_end()
            return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())
        except Exception as e:
            Gimp.message(f"Spellcaster Color Match Error: {e}")
            return procedure.new_return_values(Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

    # R105: cross-plugin transfer helpers ─────────────────────────────
    # The three _run_send_to_<target> callbacks all route through the
    # Guild's shared asset gallery + event bus. The active canvas is
    # exported to PNG, uploaded via CrossInterfaceClient.upload_asset
    # (so it gets a stable /api/assets/<hash> URL), then an
    # <origin>.asset.send event is published with the URL. Each target
    # plugin (Resolve Bridge, Darktable, SillyTavern) has a
    # subscriber that ingests assets matching its kind. See
    # spellcaster_core/cross_interface.py for the client API.

    def _cross_interface_send(self, image, target: str, kind: str,
                                friendly: str) -> bool:
        """Common path for Send-to-<X> procedures. Returns True on
        successful publish. target = one of 'resolve', 'darktable',
        'sillytavern' — used as the event prefix and subscriber
        matcher."""
        # Presence gate: if we can confirm the target isn't running,
        # bail with a clearer message than the generic "Guild unreachable"
        # path would produce. If presence query fails (ComfyUI + Guild
        # both down), _peer_online returns None and we fall through —
        # the existing Guild-upload error handling still catches it.
        peer_status = _peer_online(target)
        if peer_status is False:
            Gimp.message(
                f"Send to {friendly}: {friendly} isn't running right now. "
                f"Start it and click Send again — your canvas is still here.")
            return False
        try:
            tmp = _export_image_to_tmp(image)
            with open(tmp, "rb") as fh:
                png_bytes = fh.read()
            os.unlink(tmp)
        except Exception as e:
            Gimp.message(f"Send to {friendly}: couldn't export canvas:\n{e}")
            return False
        # Re-use the memoized, heartbeating client from
        # _get_cross_interface_client() instead of spawning a fresh one
        # each click — a new client starts a new daemon heartbeat thread
        # that is never joined until the GIMP process exits.
        client = _get_cross_interface_client()
        if client is None:
            Gimp.message(
                "Send to {}: Wizard Guild unreachable. Start the Guild "
                "and try again.".format(friendly))
            return False
        # Transport preference (audit tier-3 blob bus): try ComfyUI's
        # blob bus first — bytes skip the Guild's machine, peer plugins
        # download direct from ComfyUI. Falls back to the Guild
        # AssetGallery upload when blob_put fails (no ComfyUI URL
        # configured, blob bus off, request 5xx, etc). Event still
        # publishes via Guild either way; the transport field tells
        # subscribers which URL shape they got.
        cfg = _load_config()
        comfy_url = cfg.get("server_url") or ""
        asset_url: str
        asset_hash: str
        transport: str
        if comfy_url:
            blob_rec = client.blob_put(
                comfy_url, png_bytes, kind=kind, timeout=15.0)
        else:
            blob_rec = None
        if blob_rec and blob_rec.get("hash") and blob_rec.get("url"):
            asset_url = blob_rec["url"]
            asset_hash = blob_rec["hash"]
            transport = "blob"
        else:
            rec = client.upload_asset(
                png_bytes, kind=kind,
                title=f"From GIMP → {friendly}",
                tags=[f"to_{target}", "gimp_export"],
            )
            if not rec or not rec.get("hash"):
                Gimp.message(
                    f"Send to {friendly} failed — Guild unreachable or "
                    f"rejected the upload. Start the Wizard Guild and "
                    f"try again.")
                return False
            asset_hash = rec["hash"]
            asset_url = f"/api/assets/{asset_hash}"
            transport = "guild"
        # Publish the directed-send event. The receiving subscriber
        # pulls the bytes via asset_url (either blob-bus or Guild
        # gallery URL — both are plain http(s), subscribers don't
        # care).
        client.publish(f"{target}.asset.send", data={
            "image_url": asset_url,
            "hash": asset_hash,
            "source": "gimp",
            "kind": kind,
            "transport": transport,
        })
        Gimp.message(
            f"Sent to {friendly} via {transport}. "
            f"Asset hash: {asset_hash[:10]}… "
            f"The {friendly} plugin picks it up automatically.")
        return True

    def _run_send_to_resolve(self, procedure, run_mode, image,
                               drawables, config, data):
        """R105: publish the active canvas for DaVinci Resolve's
        MediaPoolSync subscriber to auto-import."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(
                Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        ok = self._cross_interface_send(
            image, target="resolve", kind="asset",
            friendly="DaVinci Resolve")
        return procedure.new_return_values(
            Gimp.PDBStatusType.SUCCESS if ok
            else Gimp.PDBStatusType.EXECUTION_ERROR,
            GLib.Error())

    def _run_send_to_darktable(self, procedure, run_mode, image,
                                 drawables, config, data):
        """R105: publish the active canvas for Darktable."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(
                Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        ok = self._cross_interface_send(
            image, target="darktable", kind="asset",
            friendly="Darktable")
        return procedure.new_return_values(
            Gimp.PDBStatusType.SUCCESS if ok
            else Gimp.PDBStatusType.EXECUTION_ERROR,
            GLib.Error())

    def _run_send_to_sillytavern(self, procedure, run_mode, image,
                                   drawables, config, data):
        """R105: publish the active canvas for SillyTavern (character
        avatar / scene reference)."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(
                Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        ok = self._cross_interface_send(
            image, target="sillytavern", kind="asset",
            friendly="SillyTavern")
        return procedure.new_return_values(
            Gimp.PDBStatusType.SUCCESS if ok
            else Gimp.PDBStatusType.EXECUTION_ERROR,
            GLib.Error())

    def _run_character_card_editor(self, procedure, run_mode, image,
                                     drawables, config, data):
        """Import a SillyTavern character card PNG, edit its V2 metadata
        in a large scrolled Gtk dialog (with per-field + all-field LLM
        scaffolded auto-optimization), then export a PNG whose `chara`
        tEXt chunk carries the edited data and whose pixels are the
        current GIMP canvas.

        The round-trip is loss-free: metadata chunks we don't touch
        (pose, etc.) survive verbatim; the `chara` chunk is rebuilt
        from the edited fields. Implementation lives in
        spellcaster_core.sillytavern_card — do NOT duplicate the PNG
        chunk IO or the best-practice scaffolds here.
        """
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(
                Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        try:
            GimpUi.init("spellcaster")
        except Exception:
            pass
        try:
            _apply_spellcaster_theme()
        except Exception:
            pass

        try:
            from spellcaster_core import sillytavern_card as _st
        except ImportError as e:
            Gimp.message(f"Character Card Editor: helper module missing — {e}")
            return procedure.new_return_values(
                Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())
        try:
            from spellcaster_core.cross_interface import resolve_guild_url
        except ImportError:
            resolve_guild_url = lambda: "http://127.0.0.1:7777"

        import os, json, tempfile, copy
        import urllib.request as _ur
        import urllib.error as _ue

        # ── 1. File picker ──────────────────────────────────────────
        fc = Gtk.FileChooserDialog(
            title="Import SillyTavern Character Card",
            action=Gtk.FileChooserAction.OPEN)
        fc.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        fc.add_button("_Open", Gtk.ResponseType.OK)
        ff = Gtk.FileFilter()
        ff.set_name("SillyTavern Character Cards (*.png)")
        ff.add_pattern("*.png")
        ff.add_pattern("*.PNG")
        fc.add_filter(ff)
        resp = fc.run()
        src_path = fc.get_filename() if resp == Gtk.ResponseType.OK else None
        fc.destroy()
        if not src_path:
            return procedure.new_return_values(
                Gimp.PDBStatusType.CANCEL, GLib.Error())

        # ── 2. Parse tEXt chunks + decode chara ─────────────────────
        try:
            with open(src_path, "rb") as f:
                original_bytes = f.read()
        except Exception as e:
            Gimp.message(f"Character Card Editor: read failed — {e}")
            return procedure.new_return_values(
                Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

        chunks_in = _st.extract_text_chunks(original_bytes)
        chara_b64 = chunks_in.get("chara") or chunks_in.get("ccv3")
        if chara_b64:
            try:
                card = _st.decode_chara(chara_b64)
            except Exception as e:
                Gimp.message(
                    "Character Card Editor: the `chara` chunk couldn't be "
                    f"decoded ({e}). Starting from an empty card.")
                card = {}
        else:
            Gimp.message(
                "Character Card Editor: this PNG has no embedded SillyTavern "
                "character data. Starting from an empty card — you can fill "
                "in the fields and save as a new card.")
            card = {}

        # Original fields for later diff / cancel-revert.
        fields = _st.card_fields(card)

        # ── 3. Open the PNG in GIMP so the user can repaint art ─────
        try:
            gfile = Gio.File.new_for_path(src_path)
            loaded = Gimp.file_load(Gimp.RunMode.NONINTERACTIVE, gfile)
            if loaded is not None:
                Gimp.Display.new(loaded)
        except Exception as e:
            loaded = None
            Gimp.message(
                "Character Card Editor: GIMP couldn't open the PNG for "
                f"editing ({e}). The dialog will still work — the saved "
                "card will reuse the original pixels.")

        # ── 4. Build the editor dialog ──────────────────────────────
        title = f"Character Card Editor — {os.path.basename(src_path)}"
        dialog = Gtk.Dialog(title=title, flags=0)
        dialog.set_default_size(900, 760)
        try:
            _style_dialog_buttons(dialog)
        except Exception:
            pass
        content = dialog.get_content_area()
        content.set_spacing(8)
        content.set_border_width(10)

        # Info banner
        info = Gtk.Label()
        info.set_markup(
            "<b>Round-trip-safe card editor.</b> Edit any field below, "
            "paint over the image in GIMP, then Save. The V2 <tt>chara</tt> "
            "chunk is rebuilt from these fields; any other tEXt metadata "
            "(pose, etc.) survives verbatim.")
        info.set_line_wrap(True)
        info.set_xalign(0.0)
        content.pack_start(info, False, False, 0)

        # Scrolled area holding the field grid.
        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.AUTOMATIC,
                         Gtk.PolicyType.AUTOMATIC)
        scroll.set_hexpand(True)
        scroll.set_vexpand(True)
        field_box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6)
        field_box.set_border_width(4)
        scroll.add(field_box)
        content.pack_start(scroll, True, True, 0)

        # Widget registry so Optimize/Save can read them back.
        widgets: dict[str, object] = {}
        buffers: dict[str, Gtk.TextBuffer] = {}

        # Single-line fields get Gtk.Entry, multi-line get Gtk.TextView.
        SINGLE_LINE = {"name", "creator", "character_version", "tags"}

        # Per-field labels + hints.
        _LABELS = {
            "name":                      "Name",
            "description":               "Description",
            "personality":               "Personality",
            "scenario":                  "Scenario",
            "first_mes":                 "First Message",
            "mes_example":               "Example Messages",
            "system_prompt":             "System Prompt",
            "post_history_instructions": "Post-History Instructions",
            "creator":                   "Creator",
            "character_version":         "Version",
            "creator_notes":             "Creator Notes",
            "tags":                      "Tags (comma-separated)",
        }

        # Fields optimizable by the LLM scaffold (the rest are bookkeeping).
        _OPTIMIZABLE = {
            "description", "personality", "scenario", "first_mes",
            "mes_example", "system_prompt", "post_history_instructions",
            "creator_notes",
        }

        def _make_row(key: str):
            row = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
            header = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=6)
            lbl = Gtk.Label()
            lbl.set_markup(f"<b>{_LABELS[key]}</b>")
            lbl.set_xalign(0.0)
            header.pack_start(lbl, True, True, 0)
            if key in _OPTIMIZABLE:
                opt_btn = Gtk.Button(label="🪄 Optimize")
                opt_btn.set_tooltip_text(
                    f"Rewrite {_LABELS[key]} via the scaffolded LLM using "
                    "best-practice SillyTavern card conventions.")
                header.pack_end(opt_btn, False, False, 0)
                opt_btn.connect("clicked", lambda _b, k=key: _optimize_field(k))
            row.pack_start(header, False, False, 0)

            val = fields.get(key, "")
            if key == "tags":
                val = ", ".join(val) if isinstance(val, list) else str(val)

            if key in SINGLE_LINE:
                entry = Gtk.Entry()
                entry.set_text(str(val))
                row.pack_start(entry, False, False, 0)
                widgets[key] = entry
            else:
                # Multiline — size per field.
                height_map = {
                    "description": 140, "personality": 80, "scenario": 80,
                    "first_mes": 160, "mes_example": 160,
                    "system_prompt": 80, "post_history_instructions": 70,
                    "creator_notes": 70,
                }
                tv = Gtk.TextView()
                tv.set_wrap_mode(Gtk.WrapMode.WORD_CHAR)
                tv.set_accepts_tab(False)
                buf = tv.get_buffer()
                buf.set_text(str(val))
                sw = Gtk.ScrolledWindow()
                sw.set_policy(Gtk.PolicyType.AUTOMATIC,
                              Gtk.PolicyType.AUTOMATIC)
                sw.set_min_content_height(height_map.get(key, 100))
                sw.add(tv)
                row.pack_start(sw, False, False, 0)
                widgets[key] = tv
                buffers[key] = buf

            field_box.pack_start(row, False, False, 0)
            field_box.pack_start(Gtk.Separator(
                orientation=Gtk.Orientation.HORIZONTAL),
                False, False, 0)

        # Build rows in display order.
        for key in ("name", "description", "personality", "scenario",
                    "first_mes", "mes_example", "system_prompt",
                    "post_history_instructions", "creator",
                    "character_version", "creator_notes", "tags"):
            _make_row(key)

        # ── Read/write widgets ──────────────────────────────────────
        def _read_widget(key: str) -> str:
            w = widgets.get(key)
            if w is None:
                return ""
            if key in SINGLE_LINE:
                return w.get_text()
            buf = buffers[key]
            start, end = buf.get_bounds()
            return buf.get_text(start, end, True)

        def _write_widget(key: str, value):
            w = widgets.get(key)
            if w is None:
                return
            text = ", ".join(value) if isinstance(value, list) else str(value)
            if key in SINGLE_LINE:
                w.set_text(text)
            else:
                buffers[key].set_text(text)

        def _current_card() -> dict:
            """Merge widget state into a fresh copy of the original card."""
            edits = {k: _read_widget(k) for k in _LABELS}
            c = copy.deepcopy(card) if card else {}
            _st.apply_card_fields(c, edits)
            return c

        # ── LLM call ────────────────────────────────────────────────
        guild_base = resolve_guild_url()
        llm_url = f"{guild_base}/api/llm_generate"

        def _llm_call(prompt: str, max_tokens: int = 700) -> str:
            req = _ur.Request(
                llm_url,
                data=json.dumps({
                    "prompt": prompt,
                    "max_length": max_tokens,
                    "temperature": 0.7,
                }).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST")
            with _ur.urlopen(req, timeout=180) as resp:
                body = json.loads(resp.read())
            try:
                return body["results"][0]["text"]
            except (KeyError, IndexError, TypeError):
                return ""

        def _optimize_field(field: str):
            try:
                prompt = _st.build_optimize_prompt(_current_card(), field=field)
            except Exception as e:
                Gimp.message(f"Optimize {field}: prompt build failed — {e}")
                return
            try:
                raw = _llm_call(prompt, max_tokens=600)
            except (_ue.URLError, TimeoutError, OSError) as e:
                Gimp.message(
                    "Optimize: the Guild LLM isn't reachable at "
                    f"{llm_url} — {e}.\nStart the Wizard Guild and try again.")
                return
            except Exception as e:
                Gimp.message(f"Optimize {field}: LLM error — {e}")
                return
            cleaned = _st.parse_optimize_response(raw, field=field)
            if cleaned and isinstance(cleaned, str):
                _write_widget(field, cleaned)

        def _optimize_all(_btn):
            try:
                prompt = _st.build_optimize_prompt(_current_card(), field=None)
            except Exception as e:
                Gimp.message(f"Optimize All: prompt build failed — {e}")
                return
            try:
                raw = _llm_call(prompt, max_tokens=2400)
            except (_ue.URLError, TimeoutError, OSError) as e:
                Gimp.message(
                    "Optimize All: the Guild LLM isn't reachable at "
                    f"{llm_url} — {e}.\nStart the Wizard Guild and try again.")
                return
            except Exception as e:
                Gimp.message(f"Optimize All: LLM error — {e}")
                return
            try:
                obj = _st.parse_optimize_response(raw, field=None)
            except Exception as e:
                Gimp.message(
                    f"Optimize All: LLM reply wasn't valid JSON — {e}\n\n"
                    f"Reply:\n{raw[:500]}")
                return
            if not isinstance(obj, dict):
                Gimp.message("Optimize All: LLM reply was not a JSON object.")
                return
            applied = 0
            for k, v in obj.items():
                if k in _LABELS and v:
                    _write_widget(k, v)
                    applied += 1
            Gimp.message(
                f"Optimize All: rewrote {applied} field(s). Review and edit "
                "before saving.")

        # ── Bottom button row ───────────────────────────────────────
        btn_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
        btn_row.set_margin_top(4)
        opt_all_btn = Gtk.Button(label="🪄 Optimize All (Scaffolded)")
        opt_all_btn.set_tooltip_text(
            "Run the LLM scaffold across every optimizable field using "
            "SillyTavern V2 best practices. Review each field and tweak "
            "before saving.")
        opt_all_btn.connect("clicked", _optimize_all)
        btn_row.pack_start(opt_all_btn, False, False, 0)

        spacer = Gtk.Label()
        btn_row.pack_start(spacer, True, True, 0)

        cancel_btn = Gtk.Button(label="Cancel")
        save_btn = Gtk.Button(label="💾 Save Card As…")
        save_btn.get_style_context().add_class("suggested-action")
        btn_row.pack_start(cancel_btn, False, False, 0)
        btn_row.pack_start(save_btn, False, False, 0)
        content.pack_start(btn_row, False, False, 0)

        result = {"saved": False, "path": None}

        cancel_btn.connect("clicked", lambda _b: dialog.response(Gtk.ResponseType.CANCEL))

        def _export_image_for_card(img) -> bytes:
            """Flatten `img` and write to a temp PNG via Gimp.file_save,
            then read the bytes back. PNG-only (not the JPEG-fast path
            used elsewhere — we need lossless pixels AND we post-process
            the chunks, so JPEG is a non-starter)."""
            if img is None:
                raise RuntimeError("no image loaded in GIMP")
            dup = img.duplicate()
            try:
                dup.flatten()
                layers = dup.get_layers()
                flat = layers[0] if layers else None
                tmp = tempfile.NamedTemporaryFile(
                    suffix=".png", delete=False,
                    prefix="spellcaster_stcard_")
                tmp.close()
                gf = Gio.File.new_for_path(tmp.name)
                try:
                    Gimp.file_save(
                        Gimp.RunMode.NONINTERACTIVE,
                        dup, [flat] if flat else [], gf)
                except Exception:
                    pdb = Gimp.get_pdb()
                    for pname in ("file-png-export", "file-png-save"):
                        if pdb.lookup_procedure(pname):
                            _pdb_run(pname, {
                                "run-mode": Gimp.RunMode.NONINTERACTIVE,
                                "image": dup,
                                "file": gf,
                            })
                            break
                with open(tmp.name, "rb") as f:
                    png_bytes = f.read()
                try:
                    os.unlink(tmp.name)
                except Exception:
                    pass
                if not png_bytes or not png_bytes.startswith(b"\x89PNG"):
                    raise RuntimeError("export produced no/invalid PNG")
                return png_bytes
            finally:
                try:
                    dup.delete()
                except Exception:
                    pass

        def _do_save(_btn):
            # Ask for output path.
            sf = Gtk.FileChooserDialog(
                title="Save SillyTavern Character Card",
                action=Gtk.FileChooserAction.SAVE)
            sf.add_button("_Cancel", Gtk.ResponseType.CANCEL)
            sf.add_button("_Save", Gtk.ResponseType.OK)
            sf.set_do_overwrite_confirmation(True)
            base, ext = os.path.splitext(os.path.basename(src_path))
            sf.set_current_name(f"{base}_edited.png")
            folder = os.path.dirname(src_path) or os.path.expanduser("~")
            try:
                sf.set_current_folder(folder)
            except Exception:
                pass
            gf = Gtk.FileFilter()
            gf.set_name("PNG")
            gf.add_pattern("*.png")
            sf.add_filter(gf)
            sresp = sf.run()
            dest = sf.get_filename() if sresp == Gtk.ResponseType.OK else None
            sf.destroy()
            if not dest:
                return
            if not dest.lower().endswith(".png"):
                dest += ".png"

            # Export the GIMP image (current canvas) to temp PNG, or
            # fall back to the original pixel bytes if GIMP didn't
            # open the image.
            try:
                exported_bytes = _export_image_for_card(loaded)
            except Exception as e:
                Gimp.message(
                    "Save: couldn't export the GIMP canvas — falling back "
                    f"to the original pixels. ({e})")
                exported_bytes = original_bytes

            # Build the new chunk set: all original chunks preserved,
            # chara/ccv3 replaced with the edited state.
            new_chunks: dict[str, str] = dict(chunks_in)
            final_card = _current_card()
            new_chunks["chara"] = _st.encode_chara(final_card)
            # Drop ccv3 to avoid a stale V3 spec wrapper conflicting with
            # the rebuilt V2 payload; SillyTavern falls back to chara.
            new_chunks.pop("ccv3", None)

            try:
                final = _st.inject_text_chunks(exported_bytes, new_chunks)
            except Exception as e:
                Gimp.message(
                    f"Save: tEXt chunk injection failed — {e}\n"
                    "No file written.")
                return
            try:
                with open(dest, "wb") as f:
                    f.write(final)
            except Exception as e:
                Gimp.message(f"Save: write failed — {e}")
                return

            # Verify round-trip.
            try:
                with open(dest, "rb") as f:
                    verify = _st.extract_text_chunks(f.read())
                if "chara" not in verify:
                    Gimp.message(
                        f"Save: wrote {dest} but the `chara` chunk isn't "
                        "readable after write. SillyTavern may not load it.")
                    return
            except Exception:
                pass

            result["saved"] = True
            result["path"] = dest
            dialog.response(Gtk.ResponseType.OK)

        save_btn.connect("clicked", _do_save)

        dialog.show_all()
        rv = dialog.run()
        dialog.destroy()

        if result["saved"]:
            Gimp.message(
                f"✨ Saved character card:\n{result['path']}\n\n"
                f"Embedded {len(_current_card().get('data', {}))} V2 "
                "fields. Original non-chara metadata preserved.")
            return procedure.new_return_values(
                Gimp.PDBStatusType.SUCCESS, GLib.Error())
        return procedure.new_return_values(
            Gimp.PDBStatusType.CANCEL if rv == Gtk.ResponseType.CANCEL
            else Gimp.PDBStatusType.SUCCESS,
            GLib.Error())

    def _run_check_inbox(self, procedure, run_mode, image,
                           drawables, config, data):
        """R106: pull pending assets from gimp's cross-interface inbox
        and open each as a new GIMP image.

        Pulls via GET /api/gimp/inbox?consume=1&max=20. For each
        message whose kind matches ``gimp.asset.send``, downloads the
        referenced asset from the Guild (absolute URL, or relative
        path prepended with the Guild's base URL) and opens it as a
        new image. Messages are consumed on read, so pressing Check
        Inbox a second time gives an empty pull.

        Shares its worker (`_drain_inbox_worker`) with the auto-poll
        path: every Spellcaster menu invocation also drains silently
        in the background via `_maybe_auto_drain_inbox`, so users
        typically don't need to click this manually — it's the force
        drain + diagnostic view.
        """
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(
                Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        result = _drain_inbox_worker(
            http_timeout=10, per_asset_timeout=30,
            max_asset_size=100 * 1024 * 1024,
            silent=False)
        status = result.get("status")
        if status == "cross_interface_missing":
            Gimp.message(f"Check Inbox: cross_interface helper missing — "
                         f"{result.get('error') or 'ImportError'}")
            return procedure.new_return_values(
                Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())
        if status == "guild_backbone_off":
            Gimp.message(
                "Check Inbox: the Guild's mailbox primitives are "
                "disabled (cross-interface backbone off). Start the "
                "Wizard Guild with cross_interface enabled.")
            return procedure.new_return_values(
                Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())
        if status == "guild_http_error":
            Gimp.message(
                f"Check Inbox: Guild returned HTTP {result.get('http_code')}.")
            return procedure.new_return_values(
                Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())
        if status == "guild_unreachable":
            Gimp.message(f"Check Inbox: Guild unreachable — {result.get('error')}")
            return procedure.new_return_values(
                Gimp.PDBStatusType.EXECUTION_ERROR, GLib.Error())

        opened = result.get("opened", 0)
        failures = result.get("failures") or []
        if status == "empty":
            Gimp.message("Check Inbox: nothing waiting.")
            return procedure.new_return_values(
                Gimp.PDBStatusType.SUCCESS, GLib.Error())

        lines = [f"Opened {opened} image(s) from the inbox."]
        if failures:
            lines.append("")
            lines.append("Failures:")
            for f in failures[:5]:
                lines.append(f"  • {f}")
            if len(failures) > 5:
                lines.append(f"  • …and {len(failures) - 5} more")
        Gimp.message("\n".join(lines))
        return procedure.new_return_values(
            Gimp.PDBStatusType.SUCCESS, GLib.Error())

    def _run_calibration_wizard(self, procedure, run_mode, image, drawables, config, data):
        """Calibration Wizard: tune AI settings with A/B image comparisons."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        try:
            GimpUi.init("spellcaster")
        except Exception:
            pass
        try:
            _apply_spellcaster_theme()
        except Exception:
            pass

        cfg = _load_config()
        server = cfg.get("server_url", "http://127.0.0.1:8188")

        dlg = CalibrationWizardDialog(server)
        dlg.run()
        dlg.destroy()

        return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())

    def _run_settings(self, procedure, run_mode, image, drawables, config, data):
        """Spellcaster Settings: configure server URL, defaults, and preferences."""
        if run_mode == Gimp.RunMode.NONINTERACTIVE:
            return procedure.new_return_values(Gimp.PDBStatusType.CALLING_ERROR, GLib.Error())
        try:
            GimpUi.init("spellcaster")
        except Exception:
            pass
        try:
            _apply_spellcaster_theme()
        except Exception:
            pass
        dlg = Gtk.Dialog(title="Spellcaster Settings")
        dlg.set_default_size(520, -1)
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("_Save", Gtk.ResponseType.OK)
        dlg.set_default_response(Gtk.ResponseType.OK)
        _style_dialog_buttons(dlg)
        bx = dlg.get_content_area()
        bx.set_spacing(10); bx.set_margin_start(16); bx.set_margin_end(16)
        bx.set_margin_top(16); bx.set_margin_bottom(16)

        # Header
        _hdr = _make_branded_header()
        if _hdr:
            bx.pack_start(_hdr, False, False, 0)

        # Load current config
        cfg = _load_config()

        # ── Server URL ──
        bx.pack_start(Gtk.Label(label="ComfyUI Server URL:", xalign=0), False, False, 0)
        server_entry = Gtk.Entry()
        server_entry.set_text(cfg.get("server_url", COMFYUI_DEFAULT_URL))
        server_entry.set_tooltip_text(
            "The URL of your ComfyUI server. This is saved permanently and used\n"
            "as the default for all Spellcaster dialogs.\n\n"
            "Local:  http://127.0.0.1:8188\n"
            "LAN:    http://192.168.x.x:8188\n"
            "Remote: http://your-server:8188")
        bx.pack_start(server_entry, False, False, 0)

        # Test connection button
        test_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
        test_btn = Gtk.Button(label="Test Connection")
        test_status = Gtk.Label(label="")
        test_btn.set_tooltip_text("Send a test request to the ComfyUI server to verify connectivity.")
        def on_test(btn):
            url = server_entry.get_text().strip().rstrip("/")
            test_status.set_text("Testing...")
            try:
                req = urllib.request.Request(f"{url}/system_stats", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    data = json.loads(resp.read())
                    vram = data.get("devices", [{}])[0].get("vram_total", 0)
                    gpu = data.get("devices", [{}])[0].get("name", "Unknown")
                    if vram:
                        test_status.set_markup(f'<span foreground="#00E676">Connected: {gpu} ({vram//1024//1024//1024} GB)</span>')
                    else:
                        test_status.set_markup('<span foreground="#00E676">Connected</span>')
            except Exception as e:
                test_status.set_markup(f'<span foreground="#FF5252">Failed: {e}</span>')
        test_btn.connect("clicked", on_test)
