        reload_row.pack_start(reload_status, True, True, 0)
        expert_box.pack_start(reload_row, False, False, 0)

        # Helper already called expert_expander.add(expert_box); just pack.
        bx.pack_start(expert_expander, False, False, 0)

        # ── Info ──
        bx.pack_start(Gtk.Separator(), False, False, 5)
        info_label = Gtk.Label()
        info_label.set_markup(
            f'<span size="small" foreground="#888888">'
            f'Config file: {os.path.join(os.path.dirname(os.path.abspath(__file__)), "config.json")}\n'
            f'Current session URL: {COMFYUI_DEFAULT_URL}\n'
            f'Plugin version: Spellcaster v1.0'
            f'</span>')
        info_label.set_xalign(0)
        bx.pack_start(info_label, False, False, 0)

        bx.show_all()
        if dlg.run() != Gtk.ResponseType.OK:
            dlg.destroy()
            return procedure.new_return_values(Gimp.PDBStatusType.CANCEL, GLib.Error())

        # Save settings
        new_url = server_entry.get_text().strip().rstrip("/")
        new_timeout = int(timeout_spin.get_value()) if timeout_check.get_active() else 0
        new_auto_update = auto_update_cb.get_active()
        new_debug = debug_cb.get_active()
        new_output_dir = output_entry.get_text().strip()
        new_cleanup = cleanup_combo.get_active_id() or "copy"
        fav_id = fav_combo.get_active_id()
        new_fav = int(fav_id) if fav_id and fav_id != "-1" else -1
        dlg.destroy()

        # Apply timeout globally for this session
        global WORKFLOW_TIMEOUT, _PROMPT_ENHANCE, _LLM_URL
        WORKFLOW_TIMEOUT = new_timeout

        # Apply prompt enhancement settings globally for this session
        new_enhance = enhance_cb.get_active()
        new_llm = llm_entry.get_text().strip().rstrip("/")
        _PROMPT_ENHANCE = new_enhance
        _LLM_URL = new_llm

        # Parse extra workflow dirs from expert settings
        _buf = extra_dirs_buf
        _raw_dirs = _buf.get_text(_buf.get_start_iter(), _buf.get_end_iter(), False)
        _extra_dirs = [d.strip() for d in _raw_dirs.split("\n") if d.strip()]

        _save_config({
            "server_url": new_url,
            "workflow_timeout": new_timeout,
            "auto_update": new_auto_update,
            "debug_images": new_debug,
            "favourite_model": new_fav,
            "output_dir": new_output_dir,
            "output_cleanup": new_cleanup,
            "extra_workflow_dirs": _extra_dirs,
            "prompt_enhance": new_enhance,
            "llm_url": new_llm,
        })
        _propagate_server_url(new_url)
        enhance_msg = " | AI Enhance: ON" if new_enhance else ""
        Gimp.message(f"Settings saved. Server: {new_url}{enhance_msg}")
        return procedure.new_return_values(Gimp.PDBStatusType.SUCCESS, GLib.Error())


